#!/usr/bin/env python3
"""
HomeAnt host control — cross-platform (Windows / Linux / macOS).

Usage (platform entry points):
  Windows:   .\\homeant    start|stop|status|logs|uninstall
  Linux/mac: ./homeant     start|stop|status|logs|uninstall

Config: project_root/homeant.cfg

Flow:
  start (foreground): probe the release host -> deploy config if the seed
         changed -> provision the owner -> launch hass -> then OAuth and MCP
         in that order, each stage stopping the chain until it is satisfied
"""

from __future__ import annotations

import argparse
import base64
import contextlib
import json
import locale
import os
import re
import shutil
import signal
import socket
import subprocess
import sys
import threading
import time
import webbrowser
from pathlib import Path

IS_WIN = sys.platform == "win32"

# ── paths ───────────────────────────────────────────────────────────────────

PROJECT_ROOT = Path(__file__).resolve().parent.parent
CONFIG_FILE = PROJECT_ROOT / "homeant.cfg"
# The shipped template. The release zip carries only this file; the live
# homeant.cfg above is generated by `start` and never packaged (it holds
# USERNAME / PASSWORD and the choices this home made — machine addresses yes,
# paths no: everything path-shaped is derived from this file's own location).
CFG_TEMPLATE = PROJECT_ROOT / "homeant.cfg.default"
HA_ROOT = Path.home() / ".homeant"
# One pid record, one authority — HA's own .ha_run.lock:
#
#   .ha_run.lock  written by *HA* (runner._write_lock_info: pid, ha_version,
#                 start_ts) for any instance using this config dir — including
#                 one started by hand — but never deleted, so its pid is only a
#                 claim until checked against a live process (see _ha_instance).
#
# There used to be a second one, .hass.pid, written by us right after Popen.
# It is gone.  Its only irreplaceable job was holding a pid during the ~8s a new
# hass needs to finish importing before HA writes its own, and a process scan
# used to cover that window.  Keeping both meant two records that could
# disagree — and they did: with HA_ROOT deleted while hass was still running,
# start found the process by scanning and reported it running while status, left
# with a deleted pid file, reported it stopped.  On Windows they never even held
# the same number (launcher vs python child), so they were never two copies of
# one fact to begin with.
#
# Liveness is never inferred from the file: its pid is validated with pid_exists
# *and* _pid_is_hass.  HA also
# flocks .ha_run.lock, but only on POSIX (runner.py: fcntl is None on Windows),
# and we must not probe that lock — HA takes LOCK_EX non-blocking exactly once
# at startup, so a probe of ours could make a healthy HA abort.
#
# The third tier that used to sit under this file is gone: a process-table
# scan matching every command line that carried both "--config" and HA_ROOT.  It
# was a guess — a `bash -c "... hass ... --config ..."` wrapper carries the same
# words, so that shell came back as a hit one pid ahead of the hass it launched
# — and on Windows it cost a PowerShell start-up (~1s) on a path `status` walks.
# What replaced it is not a cheaper scan but a different question:
# `_hass_via_service()` asks the supervisor whether its process is alive and the
# socket whether anything answers.  Once a service owns the home that is what
# "up" means, and it cannot be fooled by text.  The pid itself stays lock-only;
# when the lock is gone, `status` says "running (via service)" and stops there.
# No HA_LOCK_FILE constant on purpose: the lock lives *inside* HA_ROOT, and a
# module-level copy silently keeps pointing at the old root the moment anything
# rebases HA_ROOT (tests do; a future --ha-root would).  Deriving it at the one
# call site costs nothing and cannot drift.
HASS_LOG = HA_ROOT / "home-assistant.log"
SEED_MARKER = HA_ROOT / ".seed-state"
HOMEANT_SERVER = os.environ.get("HOMEANT_SERVER") or "dl.homeant.cn"
CONNECT_TIMEOUT = 15

# The online installer for this platform — one file that is both the thing to
# run and the version manifest. Each script is stamped with its version at
# package build time on a line every platform spells the same way
# (HOMEANT_VERSION="x.y.z" in install.sh, $HOMEANT_VERSION = "x.y.z"
# in install.ps1), so there is no separate manifest to upload and no way for
# the two to disagree about what "latest" means.
INSTALLER_URL = f"https://{HOMEANT_SERVER}/core/{'install.ps1' if IS_WIN else 'install.sh'}"
VERSION_RE = r'(?m)^\$?HOMEANT_VERSION\s*=\s*"([0-9][^"]*)"'

# loaded at main()
CFG: dict = {}

# ── venv site-packages fallback ────────────────────────────────────────────
# This script is intentionally zero-dependency so it can run with a bare
# `python` command, but yaml (used only for config merge) lives in the venv.
# We auto-append venv's site-packages to sys.path so yaml import just works.
def _bootstrap_venv_site_packages() -> None:
    # PROJECT_ROOT, not cwd.  Walking up from the directory the command was
    # typed in found the home directory's own .venv when run from there —
    # another project's environment, with no yaml in it — and the same tree
    # then looked broken from outside while working from inside.  This file's
    # own location is the only honest answer to "which tree am I part of".
    sp = PROJECT_ROOT / ".venv" / ("Lib" if IS_WIN else "lib") / \
        ("site-packages" if IS_WIN else f"python{sys.version_info.major}.{sys.version_info.minor}/site-packages")
    if sp.is_dir() and str(sp) not in sys.path:
        sys.path.insert(0, str(sp))

_bootstrap_venv_site_packages()

# ── venv auto-discovery ─────────────────────────────────────────────────────

def _python_bin() -> Path | None:
    """This tree's interpreter — PROJECT_ROOT/.venv, never the cwd's.

    cwd was the starting point until 2026-10-31, which made the answer depend
    on where the command was typed instead of on which tree is running: from
    the home directory, an absolute-path call to another install picked up
    the home directory's own .venv (a different uv, no hass) and reported
    "uv sync never completed here", while the same tree judged itself fine
    from its own directory.  Two verdicts for one install is how a healthy
    tree gets reinstalled for no reason.
    """
    p = PROJECT_ROOT / ".venv" / ("Scripts" if IS_WIN else "bin") / \
        ("python.exe" if IS_WIN else "python")
    return p if p.exists() else None


def _hass_bin() -> Path | None:
    """hass sits beside the interpreter, whichever layout the venv uses."""
    py = _python_bin()
    if py is None:
        return None
    p = py.parent / ("hass.exe" if IS_WIN else "hass")
    return p if p.exists() else None


_HASS = None


def hass_bin() -> Path | None:
    global _HASS
    if _HASS is None:
        _HASS = _hass_bin()
    return _HASS


# ── the child environment hass needs ───────────────────────────────────────

# Windows' default event loop (Proactor) has no add_reader/add_writer, and HA's
# MQTT client reads every packet through exactly those (mqtt/client.py:683/728).
# config/runtime/sitecustomize.py patches the loop class when Python starts; the
# two lines in _hass_child_env are the only thing that arms it.  With it on:
# SUBACK, PUBLISH and on_message all arrive; without it, 0 entities
# out of 482 and two `Error doing job` per connection attempt.
#
# The same directory holds the broker's authentication plugin, which amqtt
# imports by dotted path — so the broker child gets it on PYTHONPATH too, on
# every platform (see _broker_child_env).  Neither file is copied into
# HA_ROOT: a copy there would never be read and would go stale, since
# _merge_file never rewrites a .py.
_RUNTIME_DIR = PROJECT_ROOT / "config" / "runtime"


def _ca_bundle() -> str | None:
    """certifi's bundle path, or None when certifi is not installed.

    Why this exists: on Windows ``ssl.create_default_context()`` builds its
    trust store from the Windows ROOT store, and a thin store is a real thing —
    measured 11-18 on one Windows 11 box: 26 roots against 77 on the Windows 10
    box next to it.  That box was missing the self-signed GoDaddy root Xiaomi's
    chain terminates at, so OpenSSL walked one hop further, up to a 2004-era
    legacy root whose basicConstraints is not marked critical, and refused the
    handshake under ``VERIFY_X509_STRICT`` (a default of Python 3.13+).  The
    browser was fine on the same box — the critical flag is an OpenSSL strict
    rule, not a Windows one.

    certifi carries the Mozilla set, which includes that root.  Setting
    ``SSL_CERT_FILE`` only *adds* the bundle: ``load_default_certs()`` loads the
    Windows store first and then calls ``set_default_verify_paths()``, so
    anything the system trusts keeps working.
    """
    try:
        import certifi
    except ImportError:
        return None
    return certifi.where()


def _hass_child_env() -> dict | None:
    """Environment for the hass child, or None to inherit untouched.

    POSIX gets None on purpose: its selector loop implements the primitives, so
    a shim there would be dead weight and one more thing to explain.  On Windows
    sitecustomize pops the marker before installing, so processes hass spawns
    later (shell_command, command_line auth) inherit nothing — only the hass
    process itself is patched.

    The CA bundle is Windows-only for the same reason it is needed at all: a
    POSIX box reads a complete system bundle, while a Windows box reads a root
    store that may be missing roots.  It is a fallback, not an override — an
    explicit ``SSL_CERT_FILE`` is the user's decision and is left alone.
    """
    if not IS_WIN:
        return None
    env = os.environ.copy()
    env["HOMEANT_SOFT_SELECTOR"] = "1"
    if bundle := _ca_bundle():
        env.setdefault("SSL_CERT_FILE", bundle)
    parts = [str(_RUNTIME_DIR)]
    if prev := env.get("PYTHONPATH"):
        parts.append(prev)
    env["PYTHONPATH"] = os.pathsep.join(parts)
    return env


def _broker_child_env() -> dict:
    """Environment for the broker child: our plugin on the path, root pinned.

    Unlike the hass half this is not platform-specific — amqtt imports the
    authentication plugin by dotted path everywhere, so PYTHONPATH is always
    needed.  HOMEANT_HA_ROOT is what lets mqtt.yaml keep a relative
    ``storage_dir``: the config file ships to other machines, and an absolute
    path in it would be wrong on every one of them.  The cwd would answer too,
    but only as long as nobody ever starts the broker by hand from elsewhere.
    """
    env = os.environ.copy()
    parts = [str(_RUNTIME_DIR)]
    if prev := env.get("PYTHONPATH"):
        parts.append(prev)
    env["PYTHONPATH"] = os.pathsep.join(parts)
    env["HOMEANT_HA_ROOT"] = str(HA_ROOT)
    return env


# ── config ─────────────────────────────────────────────────────────────────

def load_cfg() -> dict:
    """Parse homeant.cfg → flat dict (KEY=VALUE, all strings)."""
    cfg: dict = {}
    if not CONFIG_FILE.exists():
        log(f"config not found: {_home_tilde(CONFIG_FILE)}")
        return cfg
    for raw in CONFIG_FILE.read_text(encoding="utf-8-sig").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        cfg[k.strip()] = v.strip()
    return cfg


def cf(k: str, default=None):
    """Read a config key with optional default."""
    v = CFG.get(k, default)
    if v is None:
        return default
    if isinstance(default, bool):
        return v.lower() in ("1", "true", "yes", "on")
    if isinstance(default, int):
        try:
            return int(v)
        except ValueError:
            return default
    return v


def log(msg: str) -> None:
    """Print a [homeant] line, coloured by its severity marker.

    Only ``FAIL  `` and ``WARN  `` are markers — everything else is a normal
    line — so the colour is derived from the text rather than passed in by
    each caller: red for FAIL, yellow for WARN, plain otherwise.  Matching
    the two spaces keeps words like ``WARNING:`` out of it: that is prose,
    not a badge.  _COLOR is defined below but resolved at call time.
    """
    color = "31" if msg.startswith("FAIL  ") else "33" if msg.startswith("WARN  ") else ""
    if color and _COLOR:
        print(f"\033[{color}m[homeant] {msg}\033[0m", flush=True)
    else:
        print(f"[homeant] {msg}", flush=True)
    _mirror_log(msg, msg.startswith("FAIL"))


def log_partial(msg: str) -> None:
    """Open a status line without a newline — the caller ticks dots into it.

    Used for phases with no progress callback of their own (hass cold start):
    a silent console reads as a hang, so the caller appends one dot per second
    via log_tick() and ends the line itself before logging the outcome.
    """
    print(f"[homeant] {msg}", end="", flush=True)


def log_tick() -> None:
    """One liveness dot, appended to a line opened by log_partial()."""
    print(".", end="", flush=True)


# ``sys.stdout`` is None in a Windows service — Session 0 has no console — and
# an unguarded isatty() would raise AttributeError at import time, i.e. before
# `--service-host` can even say why it died.
_COLOR = bool(sys.stdout and sys.stdout.isatty())
# The same fact, named for its other use: "a human is watching this already"
# decides whether a line also needs publishing to the platform log service.
_INTERACTIVE = _COLOR


def log_red(msg: str) -> None:
    if _COLOR:
        print(f"\033[31m[homeant] {msg}\033[0m", flush=True)
    else:
        print(f"[homeant] {msg}", flush=True)
    _mirror_log(msg, True)


def log_state(label: str, msg: str) -> None:
    """Print the run's closing verdict: SUCCESS / PENDING / FAIL.

    Every path out of the post-start stages ends with one of these, so the last
    line of a run cannot be mistaken for a finished install.  The word is
    print-only — callers return 0 or non-zero and never the state itself, so
    nothing downstream has to agree on a vocabulary.

    PENDING still returns 0: the files are in place and the service is up, only
    a human step is left, and re-running the command is the retry.  Reporting it
    as a failure is how a good setup gets reinstalled in a loop that cannot end
    differently.
    """
    color = {"SUCCESS": "32", "PENDING": "33", "FAIL": "31"}[label]
    if _COLOR:
        print(f"\033[{color}m[homeant] {label}: {msg}\033[0m", flush=True)
    else:
        print(f"[homeant] {label}: {msg}", flush=True)
    _mirror_log(f"{label}: {msg}", label == "FAIL")


def _cmd(name: str) -> str:
    """Spell a homeant command the way this platform actually types it.

    ``homeant`` is a wrapper in the install root, not on PATH, so the bare name
    was never typeable: Windows needs ``.\\homeant start`` and POSIX needs
    ``./homeant start``.  Every hint that names a command goes through here, so
    the reader gets something they can paste instead of something to translate.

    The path is relative on purpose and only half the answer: it holds *inside*
    the install root, so `log_run` chains a ``cd`` in front of it whenever the
    reader is somewhere else.
    """
    return f".\\homeant {name}" if IS_WIN else f"./homeant {name}"


def _installer_cmd() -> str:
    """The installer for this platform, as typed from the install root.

    Only used when the tree itself is broken (no interpreter), where a
    re-install is the repair — no homeant subcommand can fix that.
    """
    return ".\\install.ps1 --upgrade" if IS_WIN else "./install.sh --upgrade"


def _at_install_root() -> bool:
    """Is the shell the reader is in standing in the install root?

    Both installs drop a directory called ``homeant`` into the home directory —
    ``~/homeant`` — and the wrapper of the same name sits *inside* it.  So from
    ``~`` a hint reading ``./homeant start`` names the directory, not the
    command, and fails before doing anything.  This is what tells ``log_run``
    whether the short form can be pasted as printed.
    """
    try:
        cwd = Path.cwd().resolve()
    except OSError:
        # No cwd (it was deleted under us): the long form is always correct.
        return False
    return os.path.normcase(str(cwd)) == os.path.normcase(str(PROJECT_ROOT))


def _shell_and() -> str:
    """How this platform chains two commands on one line.

    PowerShell 5.1 has no ``&&`` — it is a parse error, not a failed run — so
    Windows gets ``;``.  A function rather than a constant because the tests
    flip ``IS_WIN`` after import.
    """
    return "; " if IS_WIN else " && "


def log_run(cmd: str, label: str = "run", cd: bool | None = None) -> None:
    """Put the command on its own indented line, never inside the sentence.

    A command glued to the end of a sentence gets wrapped by the console — and
    the half that survives is the half nobody needs.  ``label`` exists for the
    two-step case ("run: stop" / "then: start") and is a word, not a sentence.

    When the reader is *not* in the install root, the ``cd`` that has to come
    first is chained onto the same line (``cd ~/homeant && ./homeant start``):
    the relative path names the directory rather than the program from
    anywhere else, and one line is one paste.  Two lines would either be pasted
    as one (running the second half in the old directory) or run separately,
    which is exactly the failure the pair exists to prevent.  ``then:`` is a
    second command in the same block and never repeats it — by then the shell
    is already there.  ``cd=True`` forces it for a block that opens on a
    sentence instead of on a command.
    """
    if (label == "run" if cd is None else cd) and not _at_install_root():
        cmd = f"cd {_home_tilde(PROJECT_ROOT)}{_shell_and()}{cmd}"
    log(f"      {label}: {cmd}")


def enable_ansi() -> None:
    """Enable ANSI escape colors on Windows consoles."""
    if not IS_WIN:
        return
    try:
        import ctypes
        k = ctypes.windll.kernel32
        k.SetConsoleMode(k.GetStdHandle(-11), 7)
    except Exception:
        pass


# ── process helpers ─────────────────────────────────────────────────────────

# pid of the hass *this process* spawned, 0 when it spawned none.  In memory on
# purpose: its only consumer is the atexit/signal cleanup, which by definition
# cannot run after this process is gone — writing it to disk would keep a record
# alive for a run that no longer exists, which is exactly what .hass.pid used to
# do and why a stale copy could be mistaken for a running instance.
SPAWNED_PID = 0


def pid_exists(pid: int) -> bool:
    if IS_WIN:
        # tasklist emits ANSI code page text on zh-CN Windows; text=True would
        # decode as UTF-8 and leave stdout=None. Pin the preferred encoding.
        r = subprocess.run(
            ["tasklist", "/FI", f"PID eq {pid}"], capture_output=True, text=True,
            encoding=locale.getpreferredencoding(False), errors="ignore",
            creationflags=_no_console_flags())
        return r.stdout is not None and str(pid) in r.stdout
    try:
        os.kill(pid, 0)
        return True
    except (ProcessLookupError, PermissionError):
        return False


def _reap_child(pid: int) -> None:
    """Collect a child of *this* process, so a zombie stops looking alive.

    ``os.kill(pid, 0)`` answers True while the pid still has a slot, and a
    child that has exited but not been waited for keeps one — it sits as a
    zombie.  So ``pid_exists`` reports "still running" for a broker that is
    already gone, and a stop loop built on it waits out every window and then
    reports a FAIL for nothing.  ``waitpid`` is the only call that clears it.

    A pid that is not our child — the broker was started by another
    invocation, which is the `stop` the user runs by hand — raises
    ChildProcessError and is left alone: only its parent can reap it.
    """
    if IS_WIN:
        return
    try:
        os.waitpid(pid, os.WNOHANG)
    except OSError:
        pass


def _cmdline_is_hass(cmd: str) -> bool:
    """True when a full command line is an HA that serves HA_ROOT.

    ``--config`` is part of the test on purpose.  Without it any process that
    merely *mentions* the config dir passes — a `grep hass ~/.homeant/...`, a
    `tail -f` on the log, an editor holding it open — and the caller is about
    to kill whatever this function approves.

    Windows does not require the word "hass": the launcher hands the entry point
    over inside ``-c``, so the child's argv is only ``--ignore-os-check
    --config <root>``.  Root plus --config is specific enough there, and both
    sides are normalised because the same root reaches a process as
    ``C:\\Users\\x\\.homeant`` or ``C:/Users/x/.homeant`` depending on who
    typed it (measured: Git Bash rewrites the backslashes).
    """
    if IS_WIN:
        c = cmd.replace("\\", "/").lower()
        return "--config" in c and str(HA_ROOT).replace("\\", "/").lower() in c
    return "--config" in cmd and str(HA_ROOT) in cmd and "hass" in cmd


def _proc_image(pid: int) -> str:
    """Kernel's name for `pid` (/proc/<pid>/comm), lowercased; '' if unreadable."""
    try:
        return Path(f"/proc/{pid}/comm").read_text(
            encoding="utf-8", errors="replace").strip().lower()
    except OSError:
        return ""


def _pid_is_hass(pid: int) -> bool:
    """Cheap pid-reuse guard for a pid read out of .ha_run.lock.

    That file outlives every instance that ever ran in this config dir, so by
    the time we read it the number inside may belong to something unrelated —
    and the caller is about to SIGTERM or taskkill it.  Looking at what the
    process actually is costs microseconds and turns "probably ours" into
    "provably hass".
    """
    if IS_WIN:
        r = subprocess.run(
            ["tasklist", "/FI", f"PID eq {pid}", "/FO", "CSV", "/NH"],
            capture_output=True, text=True,
            encoding=locale.getpreferredencoding(False), errors="ignore",
            creationflags=_no_console_flags())
        image = (r.stdout or "").lower()
        # HA records the real python child's pid, not the hass.exe trampoline's.
        return "hass" in image or "python" in image
    try:
        raw = Path(f"/proc/{pid}/cmdline").read_bytes()
    except OSError:
        return True   # no /proc (macOS): liveness alone has to do
    image = _proc_image(pid)
    if image and not (image.startswith("python") or "hass" in image):
        return False
    return _cmdline_is_hass(raw.replace(b"\x00", b" ").decode("utf-8", "replace"))


def _ha_instance() -> int | None:
    """PID of the HA that owns HA_ROOT, or None when no pid can be named.

    The pid comes from one place only: ``.ha_run.lock``, which HA writes itself
    with ``os.getpid()``.  That makes it the one authoritative answer — it is
    the process talking about itself, not us guessing from a command line.

    T11 removed the fallback that scanned the process table whenever this file
    was missing or held a stale pid.  Two reasons: on Windows it started a
    PowerShell (~1s) on a path `status` walks, and matching on argv text is a
    guess — a ``bash -c "... hass ... --config ..."`` wrapper carries the same
    words.  The caller that needs "is it up at all" asks ``_hass_via_service()``
    instead, which asks the supervisor and the socket rather than the text.

    None therefore means "cannot name it", not "provably not running".
    """
    try:
        info = json.loads((HA_ROOT / ".ha_run.lock").read_text(encoding="utf-8") or "{}")
        pid = int(info.get("pid") or 0)
    except (OSError, ValueError, TypeError, AttributeError):
        # Missing, unreadable, truncated or not JSON.  The lock can be gone
        # while hass keeps running — deleted by hand, by a cleanup tool, or by a
        # `git clean` in the wrong directory — so this is not "not running".
        return None
    if pid > 0 and pid_exists(pid) and _pid_is_hass(pid):
        return pid
    # The lock outlives every instance (runner.py never unlinks it), so a dead
    # or recycled pid says nothing about what is running now — least of all on
    # Windows, where fcntl is None and HA's own single-instance lock is inert.
    return None


def _supervisor_running() -> bool:
    """True when a supervisor currently holds a live process for this home.

    ``_hass_via_service`` asks "is the home *serving*"; this asks "will a stop
    change anything".  An instance still importing is the one state where the
    two answers differ: the supervisor is up, nothing answers on the port, and
    a stop does stop something.  It is also the cheaper half — one query, no
    TCP connect (a refused one is the 2s connect ``port_in_use`` documents).

    ``cmd_stop`` needs this *before* it stops anything, because no supervisor
    distinguishes the two outcomes in its exit code: ``systemctl stop`` on an
    inactive unit exits 0, ``SERVICE_CONTROL_STOP`` against an already-stopped
    service succeeds, ``bootout`` of a label that is already unloaded is an
    idempotent success.  After the verb, "it was running" is unknowable.
    """
    kind = _service_kind()
    if kind == "systemd-user":
        return _service_active()
    if kind == "launchd":
        return _launchd_active()
    if kind == "service":
        return _win_service_state() == "running"
    return False


def _hass_via_service() -> bool:
    """True when a supervisor owns a live instance, even though no pid is known.

    hass is the supervisor's *grandchild* — Windows: service host →
    ``start --foreground`` → hass; Linux: MainPID (also ``start --foreground``)
    → hass — so neither manager will name it.  T11 deleted the process-table
    scan that used to guess, so this is what "it is up" means when the lock
    cannot say who: the supervisor reports its process alive **and** something
    is bound to the one port this home uses.

    Two questions on purpose.  "Active but nothing listening" is a real state
    (hass still importing, or wedged) and must not read as healthy — that is
    exactly the pair `status` shows as ``service: running`` beside a FAIL line.
    """
    return _supervisor_running() and port_in_use(PORT)


def port_in_use(port: int) -> bool:
    """True when *something* is listening on IPv4 — the protocol is never checked.

    A completed TCP connect only says a socket accepted; the peer may be HTTP,
    SSH, netcat, or anything else, and bind() would fail the same way for all of
    them.  That is exactly the question the port gate asks, so it stays a bare
    connect.  Anything that needs to know whether HA itself is answering must
    use ``_hass_serving()``, which speaks HTTP.

    IPv4 loopback only, deliberately not ``localhost``: HA binds both stacks by
    default (components/http/server.py: ``DEFAULT_BIND = ["0.0.0.0", "::"]``,
    and the deployed configuration.yaml sets no ``server_host``), so 127.0.0.1
    always sees our own instance.  ``localhost`` instead walks the name's whole
    address list — two addresses here — and on Windows a *refused* connect is
    not cheap: measured 2.04s for every closed port (8123, 9, 65000 alike)
    against 0.015s for an open one, so the second attempt doubled this call to
    4.07s and bought nothing.

    No platform branch, on purpose.  The extra address could only ever report a
    process holding ``::1`` alone, which cannot coexist with our own HA (it
    binds ``::`` too) and would surface one step later as a failed bind rather
    than as this gate's clear message.  Linux refuses in microseconds either
    way, so forking behaviour by OS would add a branch that changes nothing
    measurable anywhere.  See _hass_serving for the question this one does not
    answer.
    """
    try:
        s = socket.create_connection(("127.0.0.1", port), timeout=5)
        s.close()
        return True
    except OSError:
        return False


def _hass_serving(timeout: float = 1.5) -> bool:
    """True only once HA answers HTTP — holding the port is not enough.

    The ``http`` component binds its sockets during setup with
    ``start_serving=False`` and starts accepting only when ``frontend`` has
    finished setting up (components/http/server.py: ``async_bind`` vs
    ``start``), so a bare TCP connect succeeds half a second — far more on a
    cold guest — before any request is answered.  A request landing in that gap
    gets EOF instead of a response, which is exactly the RemoteDisconnected that
    used to kill the login POST.
    """
    import urllib.request as _ur
    try:
        with _ur.urlopen(f"http://127.0.0.1:{PORT}/", timeout=timeout):
            return True
    except _ur.HTTPError:
        return True     # any status at all proves the server is accepting
    except Exception:
        return False    # refused, reset, or still sitting unaccepted


# Public address used only for UDP ``connect`` — which sends no packet.  The
# kernel's answer is the interface holding the default route: used both to tell
# "do we have IPv4 yet" and to pin SSDP's multicast source to the LAN adapter.
# On a multi-homed box the default send interface is otherwise a virtual NIC,
# and no renderer ever sees the M-SEARCH.
ROUTE_PROBE_IP = "223.5.5.5"


def _route_source_ip() -> str | None:
    """IP the kernel routes a public destination through; None if none/loopback."""
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.connect((ROUTE_PROBE_IP, 53))
        ip = sock.getsockname()[0]
        return ip if ip and ip != "127.0.0.1" else None
    except OSError:
        return None
    finally:
        sock.close()


def _ipv4_ready() -> bool:
    """True once the kernel has a non-loopback IPv4 route to offer.

    A UDP ``connect`` sends no packet — it only asks the routing table, which is
    the same moment DHCP hands the interface its address.  Microseconds per
    call, so polling it costs nothing; that matters because this is asked on
    every start, in the normal case exactly once.
    """
    return _route_source_ip() is not None


def _wait_for_ipv4() -> float:
    """Wait up to ``NET_WAIT_SEC`` for that address; returns seconds waited.

    Silent when the address is already there, which is every start except the
    one a supervisor performs at boot.  When the budget runs out it says so and
    carries on: hass runs fine without an address, it just cannot announce
    itself, and refusing to start would be a much worse answer than a missing
    mDNS record.
    """
    started = time.monotonic()
    ticked = False
    while not _ipv4_ready():
        waited = time.monotonic() - started
        if waited >= NET_WAIT_SEC:
            if ticked:
                print(flush=True)
            log("WARN  network: no address after "
                f"{NET_WAIT_SEC}s — starting anyway, mDNS will not announce")
            return waited
        if not ticked:
            log_partial("waiting for a network address ")
            ticked = True
        log_tick()
        time.sleep(1.0)
    if ticked:
        print(flush=True)
        log(f"network: address available after {time.monotonic() - started:.1f}s")
    return time.monotonic() - started


def _uv_bin() -> Path | None:
    """The uv the installer would use — project-local .tools first, then PATH.

    Same order as install.ps1:416-424 and install.sh:451-462, so the checker
    and the thing it is checking for agree on which uv is authoritative.
    """
    name = "uv.exe" if IS_WIN else "uv"
    local = PROJECT_ROOT / ".tools" / "uv" / name
    if local.exists():
        return local
    found = shutil.which("uv")
    return Path(found) if found else None


def _deps_why() -> str:
    """Empty when .venv satisfies uv.lock, otherwise the reason it does not.

    `uv sync --check` asks uv itself what the lock wants and what is installed,
    and answers without writing anything — no state file of ours to keep
    honest.  --inexact matches the installer's own sync, so the packages HA
    installs at runtime from integration manifests (frontend, hassil, numpy
    ...) are not counted as drift.

    A missing or unrunnable uv is not a mismatch — it means we cannot answer.
    The honest response to "cannot answer" is to let the install start;
    reporting a mismatch would loop the tree through the installer forever.
    """
    if hass_bin() is None:
        return "no hass in .venv — uv sync never completed here"
    uv = _uv_bin()
    if uv is None:
        log("deps: no uv found — cannot verify .venv against uv.lock, continuing")
        return ""
    try:
        r = subprocess.run([str(uv), "sync", "--check", "--inexact"],
                           cwd=str(PROJECT_ROOT), capture_output=True,
                           text=True, timeout=60,
                           creationflags=_no_console_flags())
    except (OSError, subprocess.SubprocessError) as e:
        log(f"deps: uv check could not run ({e}) — continuing unverified")
        return ""
    if r.returncode == 0:
        return ""
    # uv puts the verdict on an `error:` line and the evidence above it
    # ("Would install 19 packages", "Would remove ..."), with progress chatter
    # like "Would use project environment at: .venv" ahead of both.  Quote the
    # verdict when there is one, else the first line that names a change.
    lines = [ln.strip() for ln in (r.stderr or r.stdout or "").splitlines() if ln.strip()]
    pick = next((ln for ln in lines if ln.startswith("error:")), "")
    if not pick:
        pick = next((ln for ln in lines if ln.startswith(
            ("Would install", "Would remove", "Would update", "Would replace"))), "")
    if not pick:
        pick = lines[0] if lines else ""
    return "the venv does not match uv.lock" + (f" — {pick}" if pick else "")


# ── HA endpoint — fixed values, deliberately not configuration ──────────────
# 8123 is Home Assistant's own HTTP port.  The hostname is not read from
# homeant.cfg — no install differs here — so it lives next to the code
# that depends on it rather than in a config file that would imply otherwise.
#
# MCP_HOSTNAME is ours — the short name handed to MCP clients.  Whether THIS
# box resolves it is irrelevant (see the MCP constants note); what matters is
# that clients can, and homeant_mdns advertises it for that.
#
# PORT is not xiaomi-only: status, the readiness probe and the MCP URL use it
# too.  All three are one fact — where HA answers — so they stay together.
MCP_HOSTNAME = "HomeAnt.local"
PORT = 8123


# ── desktop session ─────────────────────────────────────────────────────────
def has_desktop() -> bool:
    """True when this host can actually put a window on a screen.

    Windows and macOS always have a desktop session, so only Linux needs
    asking.  There the session is proven by ``DISPLAY`` (X11) or
    ``WAYLAND_DISPLAY`` (Wayland); a bare server has neither.  The distinction
    matters because ``webbrowser`` is not headless-safe: with no display it
    falls back to the console browsers it registers (``www-browser``, ``lynx``,
    ``w3m``), which would try to take over the terminal instead of showing a
    page.  A server therefore gets the URL printed, never a launch attempt.

    ``DISPLAY`` can also be set by X11 forwarding over SSH or leaked into a
    container; those are best-effort and are covered by the caller checking
    what ``webbrowser.open`` returns.
    """
    if IS_WIN or sys.platform == "darwin":
        return True
    return bool(os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"))


# ── service manager ───────────────────────────────────────────────────────────
#
# HomeAnt does not supervise itself.  Boot start-up and crash restart belong to
# whatever supervisor the host already runs — systemd, launchd, the Windows SCM,
# docker/k8s — and every one of them is handed the same contract: a foreground
# process that exits when hass exits.  This section only *describes* that
# relationship: which supervisor exists, and what its unit file says.  Writing
# it, enabling it and waiting for HTTP are the caller's job.

SERVICE_NAME = "homeant"
# One name for "the file that makes this host start the home": a systemd unit
# on Linux, a launchd plist on macOS.  Both live in the *user* domain and both
# survive `stop`, so every caller that only asks "is it registered?" or "delete
# the registration" stays platform-agnostic.  The plist keeps a `.service`
# infix in its filename while the label stays `cn.homeant`: launchd indexes jobs
# by Label, not by filename, and the longer name puts it next to the unit in
# anyone's eye.
LAUNCHD_LABEL = "cn.homeant"
UNIT_PATH = (Path.home() / "Library" / "LaunchAgents" / f"{LAUNCHD_LABEL}.service.plist"
             if sys.platform == "darwin"
             else Path.home() / ".config" / "systemd" / "user" / f"{SERVICE_NAME}.service")

# Stop budget, same number as HASS_STOP_WAIT_SEC in install.sh / install.ps1:
# HA needs the window to flush .storage, and stopping earlier loses the owner
# account that start just provisioned.
STOP_WAIT_SEC = 20

# The code hass exits with when it is asking to be restarted, not stopped —
# ``homeassistant.const.RESTART_EXIT_CODE``.  Copied rather than imported: this
# CLI has to run before hass is installed and while hass is broken, so it may
# not depend on the tree it supervises.  Only the Windows service host reads
# it; every other supervisor treats any non-zero code as "restart me" already.
HASS_RESTART_CODE = 100

# How long start-up waits for an IPv4 address before going ahead anyway.
# hass will not set up zeroconf without one: it logs "the system does not have
# any enabled IPv4 addresses" and then fails with [Errno 19] No such device, so
# nothing announces HomeAnt.local until someone restarts the home by hand.
# On the Debian VM the user unit starts ~2s after boot
# with the interface still addressless, and `After=network-online.target` is no
# help there — that target only exists in the *system* manager, and on that
# machine it had never been reached at all (`ActiveEnterTimestamp` empty, the
# address comes from `networking.service`/ifupdown, which orders before
# `network.target`).
# Bounded because a home that is not on a LAN must still come up: what is lost
# without an address is the announcement, not the home itself.
NET_WAIT_SEC = 20

# `ERROR_SERVICE_SPECIFIC_ERROR`: what a service reports as dwWin32ExitCode
# when it wants the SCM to record "this failed, with code N" instead of
# "stopped cleanly".  The two are the difference between the failure actions
# firing and being skipped, so it matters more than the number suggests —
# pywin32 does not export the constant, hence the literal.
WIN_ERROR_SERVICE_SPECIFIC = 1066


def _no_console_flags() -> int:
    """Spawn flags that stop a console child from opening a window of its own.

    A console-less parent — the service host in Session 0, or anything spawned
    by it — makes Windows allocate a *new* console for each console child.  The
    window is invisible in Session 0 but the console still costs a window
    station slot, and the same code path under a shell that has no console
    flashes a black box on the user's desktop.  Asking for CREATE_NO_WINDOW
    suppresses both.

    Deliberately conditional: when a console already exists it must be
    inherited, because hass writes its log to stdout and a child with no
    console handle would drop every line.  POSIX has no such flag, so 0 there.
    """
    if not IS_WIN:
        return 0
    try:
        import ctypes

        if ctypes.windll.kernel32.GetConsoleWindow():
            return 0
    except Exception:  # pragma: no cover - console APIs are always present
        return 0
    return subprocess.CREATE_NO_WINDOW


_WIN_JOBS: dict[str, object] = {}


def _win_job_arm(scope: str):
    """Win32 only: take this process's children down when it dies, however it dies.

    A requested `stop` runs code, so `_mqtt_stop()` + `taskkill /T` can collect
    the tree.  A *crash* runs nothing: this process vanishes and whatever it
    spawned — hass, the broker — keeps the ports and the supervisor cannot tell
    them apart from a stranger.  `JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE` moves that
    cleanup into the kernel: the last handle to the job is closed when this
    process ends, and closing it terminates every member.

    Children inherit the job, so one assignment at the top of a process covers
    everything it spawns later.  Nested jobs (a process already inside one —
    the SCM's, a container's) are supported since Windows 8, and measured on
    this box: assigning to a second job returns success, and closing the outer
    handle still takes the inner members down.  That measurement is what makes
    this safe to call unconditionally.

    `scope` names the owner ("service", "foreground") and the handle is kept in
    a *module-level* dict on purpose: dropping the last handle is what kills the
    members, so a local would take hass and the broker down the moment the
    enclosing function returned.  One process arms at most one of these per
    scope, and the kernel closes it when the process really ends.

    None when the platform or pywin32 is missing: every caller degrades to the
    old behaviour rather than refusing to start over a hardening step.
    """
    if scope in _WIN_JOBS:
        return _WIN_JOBS[scope]
    if not IS_WIN:
        return None
    try:
        import win32api
        import win32job
    except ImportError:  # pragma: no cover - pywin32 ships with the service
        return None
    try:
        job = win32job.CreateJobObject(None, "")
        info = win32job.QueryInformationJobObject(
            job, win32job.JobObjectExtendedLimitInformation)
        info["BasicLimitInformation"]["LimitFlags"] |= (
            win32job.JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE)
        win32job.SetInformationJobObject(
            job, win32job.JobObjectExtendedLimitInformation, info)
        win32job.AssignProcessToJobObject(job, win32api.GetCurrentProcess())
    except Exception:  # noqa: BLE001 - hardening must never block a start
        return None
    _WIN_JOBS[scope] = job
    return job


def _user_bus_env() -> dict | None:
    """Environment for ``systemctl --user``, or None when there is no user bus.

    Non-login shells (ssh, cron, ``sh -c``) do not carry ``XDG_RUNTIME_DIR`` and
    ``systemctl --user`` then dies with "Failed to connect to bus".  The path is
    derivable, so derive it: this is the one error direction that would silently
    demote a working systemd host to "no service manager".  Shared by the probe
    and by every acting call, because the two must never disagree about whether
    a bus exists.
    """
    env = dict(os.environ)
    if not env.get("XDG_RUNTIME_DIR"):
        runtime = Path(f"/run/user/{os.getuid()}")
        if not runtime.is_dir():
            return None
        env["XDG_RUNTIME_DIR"] = str(runtime)
    return env


def _service_kind() -> str:
    """Which supervisor this host has: ``systemd-user``/``launchd``/``service``/``none``.

    Read-only: probes, writes nothing, spawns nothing long-lived.  ``none`` is a
    legitimate answer — containers, bare hosts, a VM without systemd enabled —
    and the caller's job then is to ask for ``--foreground`` rather than to
    invent a daemon of its own.
    """
    if IS_WIN:
        return "service"
    if sys.platform == "darwin":
        return "launchd"
    if not Path("/run/systemd/system").is_dir():
        # Only exists while systemd is PID 1, which is also the cheapest honest
        # test for it; containers therefore answer "none" without a special case.
        return "none"
    env = _user_bus_env()
    if env is None:
        return "none"
    try:
        r = subprocess.run(["systemctl", "--user", "show-environment"],
                           capture_output=True, env=env, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return "none"
    return "systemd-user" if r.returncode == 0 else "none"


def _service_registered() -> bool:
    """Is a registration already standing for this host?

    One predicate for the three places that must agree: `start`'s hand-over
    migration (a hass running outside the supervisor), `stop`'s choice between
    its verbs, and `status`'s "not installed" line.
    """
    if IS_WIN:
        return _win_service_installed()
    return UNIT_PATH.is_file()


def _autostart_state() -> bool | None:
    """Will this host start the home by itself after a reboot?

    ``True`` / ``False`` / ``None``, and the last value is load-bearing: it means
    "could not ask", which is not the same answer as "off".  Only an
    unambiguous off earns the ``(autostart off)`` suffix in ``status`` —
    guessing there would report a setting the user never chose.

    Every probe is read-only and needs no rights: ``systemctl is-enabled`` owns
    a *user* unit, the registry's ``Start`` value is world-readable, and
    ``launchctl print-disabled`` reads the caller's own GUI domain.
    """
    kind = _service_kind()
    if kind == "systemd-user":
        r = _systemctl("is-enabled", SERVICE_NAME)
        if r is None:
            return None
        word = (r.stdout or "").strip()
        if word in ("enabled", "enabled-runtime"):
            return True
        if word == "disabled":
            return False
        return None             # static / indirect / mask / anything else
    if kind == "service":
        value = _win_reg_value("Start")
        if value == "2":        # SERVICE_AUTO_START
            return True
        if value == "3":        # SERVICE_DEMAND_START — what `disable` writes
            return False
        return None             # 4=disabled, 0/1=boot drivers, or unreadable
    if kind == "launchd":
        r = _launchctl("print-disabled", _launchd_domain())
        if r is None or r.returncode != 0:
            return None
        for line in (r.stdout or "").splitlines():
            label, sep, value = line.partition("=>")
            if not sep or label.strip().strip('"') != LAUNCHD_LABEL:
                continue
            value = value.strip().strip('";')
            if value == "disabled":
                return False
            if value == "enabled":
                return True
            return None
        # No record at all: launchd was never told either way, and the plist we
        # write carries RunAtLoad=true, so it will start.
        return True
    return None


def _render_unit() -> tuple[str, Path]:
    """Return ``(unit file text, where it belongs)``.  Pure — nothing is written.

    The unit anchors on *this source tree*, not on a launcher copied into
    HA_ROOT: a copy is one more thing to keep in sync, and it would hide the
    real path from ``systemctl cat homeant``, which is where anyone debugging a
    failed start looks first.  The corollary is that moving the tree changes
    this text, so the installer compares before rewriting.

    ``ExecStart`` calls the venv interpreter directly: the release zip does not
    preserve the executable bit on ``homeant``, and the installer must not have
    to depend on it.  ``Restart=on-failure`` rather than ``always`` so the tree
    is not resurrected during an upgrade, when it is being replaced underneath.
    """
    py = PROJECT_ROOT / ".venv" / "bin" / "python"
    script = PROJECT_ROOT / "scripts" / "homeant.py"
    text = f"""[Unit]
Description=HomeAnt
After=network-online.target
Wants=network-online.target
StartLimitIntervalSec=120
StartLimitBurst=5

[Service]
Type=simple
ExecStart="{py}" "{script}" start --foreground
WorkingDirectory={PROJECT_ROOT}
Restart=on-failure
RestartSec=10
# 143 is SIGTERM, i.e. "stop as asked".  The foreground wrapper already
# reports 0 when it forwarded the signal itself, but a stop that lands while
# the wrapper is still setting up — before it reaches hass — kills Python on
# the default handler, and systemd then files the unit as failed even though
# nothing went wrong.  Declaring the signal this way covers both paths, and
# costs nothing on the ones that never reach it: a real crash exits non-zero
# and Restart=on-failure still applies.
SuccessExitStatus=143
TimeoutStopSec={STOP_WAIT_SEC}
KillMode=mixed

[Install]
WantedBy=default.target
"""
    return text, UNIT_PATH


def _render_plist() -> tuple[str, Path]:
    """Return ``(plist text, where it belongs)`` — the macOS twin of _render_unit.

    Same contract, different spelling: ``ProgramArguments`` runs exactly the
    command ``ExecStart`` runs, so ``--foreground`` is proven portable by the
    two files agreeing instead of by an extra code path.  Only three keys are
    not a translation of the unit: ``RunAtLoad`` (bootstrap alone would leave
    the job idle), ``KeepAlive{SuccessfulExit=false}`` — the launchd way of
    saying ``Restart=on-failure``, i.e. restart a crash but never a deliberate
    stop — and ``ThrottleInterval=10``, the same ten seconds as ``RestartSec``.

    ``StandardOutPath`` / ``StandardErrorPath`` go to ``/dev/null``: a
    LaunchAgent has no console, and this layer publishes to the macOS unified
    log instead (``_mirror_log`` -> ``logger``), which is where ``log show`` and
    Console.app already look.  A file in ~/Library/Logs would be the only thing
    this project owns outside HA_ROOT — exactly the residue uninstall would
    then have to chase — and a file in HA_ROOT would only duplicate what the
    unified log already keeps.  hass's own output is dropped here as well: it
    writes ``home-assistant.log`` in HA_ROOT, which is what ``homeant logs``
    streams.
    """
    from xml.sax.saxutils import escape           # paths may contain & or <
    py = PROJECT_ROOT / ".venv" / "bin" / "python"
    script = PROJECT_ROOT / "scripts" / "homeant.py"
    text = f"""<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>{LAUNCHD_LABEL}</string>
    <key>ProgramArguments</key>
    <array>
        <string>{escape(str(py))}</string>
        <string>{escape(str(script))}</string>
        <string>start</string>
        <string>--foreground</string>
    </array>
    <key>WorkingDirectory</key>
    <string>{escape(str(PROJECT_ROOT))}</string>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <dict>
        <key>SuccessfulExit</key>
        <false/>
    </dict>
    <key>ThrottleInterval</key>
    <integer>10</integer>
    <key>StandardOutPath</key>
    <string>/dev/null</string>
    <key>StandardErrorPath</key>
    <string>/dev/null</string>
</dict>
</plist>
"""
    return text, UNIT_PATH


# How long to wait for the *service* to answer HTTP.  Matches the spawn path's
# 300 ticks: a cold boot on /mnt/d (9p) was measured at 86s, so a 30s ceiling
# would report a healthy first boot as dead.
SERVICE_START_TIMEOUT = 300


def _systemctl(*args: str) -> subprocess.CompletedProcess | None:
    """Run ``systemctl --user <args>``; None when it cannot run at all.

    ``capture_output`` throughout: enable/daemon-reload are chatty on stderr and
    the caller decides what part of that is worth showing.
    """
    env = _user_bus_env()
    if env is None:
        return None
    try:
        return subprocess.run(["systemctl", "--user", *args], capture_output=True,
                              text=True, env=env, timeout=120)
    except (OSError, subprocess.SubprocessError):
        return None


def _service_active() -> bool:
    r = _systemctl("is-active", SERVICE_NAME)
    return bool(r and r.returncode == 0 and r.stdout.strip() == "active")


def _service_main_pid() -> int:
    r = _systemctl("show", SERVICE_NAME, "-p", "MainPID", "--value")
    try:
        return int((r.stdout or "").strip()) if r is not None else 0
    except ValueError:
        return 0


def _parent_pid(pid: int) -> int:
    """Parent of ``pid``: /proc on Linux, ``ps`` on macOS, psutil on Windows.

    The Windows branch is not symmetry for its own sake.  A service runs as
    LocalSystem, so a plain user's prompt cannot read its command line — but
    ``ppid`` stays readable (measured 11-16 under a restricted token), which is
    what lets ownership be decided by the process tree when the text is gone.
    Before this branch existed the function answered 0 on Windows, so any walk
    up the tree stopped at its first step.

    ``systemctl show -p MainPID`` names the wrapper (``start --foreground``),
    never hass, so the only cheap proof that the service owns the running hass
    is the parent link — and this is where that link is read.  launchd reports a
    real pid rather than a MainPID, but the pid it reports is the wrapper too,
    so the same comparison applies on both platforms.
    """
    if IS_WIN:
        try:
            import psutil
        except ImportError:
            return 0
        try:
            return psutil.Process(pid).ppid()
        except (psutil.Error, OSError):
            return 0
    try:
        stat = Path(f"/proc/{pid}/stat").read_text()
    except OSError:
        if sys.platform != "darwin":
            return 0
        try:
            r = subprocess.run(["ps", "-o", "ppid=", "-p", str(pid)],
                               capture_output=True, text=True, timeout=10)
            return int((r.stdout or "").strip() or 0)
        except (OSError, subprocess.SubprocessError, ValueError):
            return 0
    # comm may contain spaces and parentheses, so split after the last ')';
    # what follows starts at state, making fields[1] the ppid.
    rest = stat.rsplit(")", 1)
    if len(rest) != 2:
        return 0
    fields = rest[1].split()
    try:
        return int(fields[1]) if len(fields) > 1 else 0
    except ValueError:
        return 0


def _unit_tree(text: str) -> str | None:
    """The source tree a rendered unit points at — for the repoint message."""
    m = re.search(r'^ExecStart="[^"]+" "([^"]+)"', text, re.M)
    return str(Path(m.group(1)).parent.parent) if m else None


def _service_enable() -> bool:
    """Enable at boot.  Idempotent, so ask first and only act when it is not."""
    r = _systemctl("is-enabled", SERVICE_NAME)
    if r is not None and r.returncode == 0 and r.stdout.strip() == "enabled":
        return True
    r = _systemctl("enable", SERVICE_NAME)
    if r is None or r.returncode != 0:
        detail = (r.stderr.strip() if r is not None and r.stderr else "systemctl --user enable failed")
        log_red(f"service: cannot enable — {detail}")
        return False
    return True


def _service_disable() -> bool:
    """Turn off start-at-boot.  Idempotent: ask first, act only when it is on.

    The state word is read from stdout, not from the exit code: measured on
    Debian 13, ``systemctl --user is-enabled`` exits 1 for a disabled unit while
    still printing ``disabled``.  So a second call touches nothing and says
    nothing, which is what a scripted caller needs.

    Only autostart changes.  The process keeps running and its crash-restart
    policy is untouched — that policy belongs to the registration, not to this
    verb.  Ending the process is `stop`'s job.
    """
    r = _systemctl("is-enabled", SERVICE_NAME)
    if r is not None and (r.stdout or "").strip() == "disabled":
        return True
    r = _systemctl("disable", SERVICE_NAME)
    if r is None or r.returncode != 0:
        detail = (r.stderr.strip() if r is not None and r.stderr
                  else "systemctl --user disable failed")
        log_red(f"service: cannot disable — {detail}")
        return False
    return True


def _install_unit() -> bool:
    """Make the unit on disk match this tree.

    Rewriting is content-compared, not unconditional: the unit is anchored on the
    source tree, so an in-place upgrade leaves it byte-identical and
    ``daemon-reload`` is skipped with it.  Moving the tree changes the text, and
    that is the only case that prints the repoint line — otherwise "which tree
    is the service really running" would only be answerable from
    ``systemctl cat``.
    """
    text, path = _render_unit()
    try:
        current: str | None = path.read_text(encoding="utf-8")
    except OSError:
        current = None

    if current == text:
        return _service_enable()

    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    except OSError as e:
        log_red(_tilde_text(f"service: cannot write {path} — {e}"))
        return False

    if current is None:
        log(_tilde_text(f"service installed: {path}"))
    else:
        old, new = _unit_tree(current), str(PROJECT_ROOT)
        if old and old != new:
            log(_tilde_text(f"service repointed: {old} -> {new}"))
        else:
            log(_tilde_text(f"service: unit updated ({path})"))

    r = _systemctl("daemon-reload")
    if r is None or r.returncode != 0:
        # Without the reload systemd keeps running the old text, so this is a
        # failure rather than a warning: the next start would silently use the
        # previous tree.
        log_red("service: systemctl --user daemon-reload failed — "
                "the unit on disk is newer than what systemd loaded")
        return False
    return _service_enable()


def _service_reap() -> None:
    """Stop a failed unit and show why it failed.

    Without this, ``Restart=on-failure`` retries every 10s forever and the only
    evidence sits in the journal: a boot that never happens, with no output on
    the terminal that started it.
    """
    _systemctl("stop", SERVICE_NAME)
    env = _user_bus_env()
    if env is None:
        return
    try:
        r = subprocess.run(["journalctl", "--user", "-u", SERVICE_NAME, "-n", "20", "--no-pager"],
                           capture_output=True, text=True, env=env, timeout=30)
    except (OSError, subprocess.SubprocessError):
        return
    log(f"last 20 journal lines (journalctl --user -u {SERVICE_NAME}):")
    print((r.stdout or "").strip() or "(empty)", flush=True)


# ── macOS: launchd ───────────────────────────────────────────────────────────
#
# A LaunchAgent in ``~/Library/LaunchAgents`` is the same deal as a systemd
# *user* unit: no root, no password, and it dies with the user session.  Three
# things differ from the Linux path and none of them is cosmetic.
#
# 1. ``load``/``unload`` are deprecated; the verbs are ``bootstrap <domain>
#    <path>`` and ``bootout <domain>/<label>``.  There is no ``enable``: a plist
#    that is present is picked up at the next login, which is also the price of
#    the user domain — after a reboot the home starts **when someone logs in to
#    the GUI**, not when the kernel comes up.  That is a property of launchd, and
#    the README says so instead of pretending otherwise.
# 2. ``bootout`` waits for the process to exit, and the process is the same
#    ``start --foreground`` wrapper, so the SIGTERM forwarding that gives hass
#    its 20-second flush window is what makes the stop survivable here too.
# 3. There is no journal.  The wrapper's output goes to /dev/null; writing it
#    to ~/Library/Logs would leave the only file we own outside HA_ROOT.  HA's
#    own log inside HA_ROOT is the diagnostic source, via `homeant logs`.

def _launchctl(*args: str) -> subprocess.CompletedProcess | None:
    """Run ``launchctl <args>``; None when the binary cannot run at all."""
    try:
        return subprocess.run(["launchctl", *args], capture_output=True,
                              text=True, timeout=STOP_WAIT_SEC + 20)
    except (OSError, subprocess.SubprocessError):
        return None


def _launchd_domain() -> str:
    """``gui/<uid>`` — the only domain a LaunchAgent can be bootstrapped into."""
    return f"gui/{os.getuid()}"


def _launchd_target() -> str:
    return f"{_launchd_domain()}/{LAUNCHD_LABEL}"


def _launchd_info() -> tuple[str, int]:
    """``(state, pid)`` for the job; ``("", 0)`` when it is not loaded.

    One ``launchctl print`` answers both questions, and it is also the only way
    to tell "registered but stopped" from "never registered": a label that was
    never bootstrapped exits 113 ("Could not find service") rather than
    returning an empty state.  Only single-tab keys are read — the same words
    appear again inside the job's nested sub-dictionaries, where they describe
    something else.
    """
    r = _launchctl("print", _launchd_target())
    if r is None or r.returncode != 0:
        return "", 0
    state, pid = "", 0
    for line in (r.stdout or "").splitlines():
        if not line.startswith("\t") or line.startswith("\t\t"):
            continue
        key, sep, value = line.strip().partition(" = ")
        if not sep:
            continue
        if key == "state":
            state = value.strip()
        elif key == "pid":
            try:
                pid = int(value.strip())
            except ValueError:
                pid = 0
    return state, pid


def _launchd_active() -> bool:
    return _launchd_info()[0] == "running"


def _launchd_bootout() -> bool:
    """Unload the job; True once it is gone.  Idempotent.

    ``bootout`` against a label that was never loaded exits non-zero with
    "Could not find service", and that is not a failure to stop anything — the
    requested state already holds.  Any *other* non-zero exit is a failure:
    reporting "stopped" while launchd keeps the home alive is the one outcome
    this must never fake.
    """
    r = _launchctl("bootout", _launchd_target())
    if r is not None and r.returncode != 0:
        chatter = ((r.stderr or "") + (r.stdout or "")).strip()
        if "Could not find service" not in chatter and "No such process" not in chatter:
            why = chatter.splitlines()[-1] if chatter else f"launchctl exit {r.returncode}"
            log_state("FAIL", f"cannot stop the service — {why}")
            return False
    # bootout blocks until the job exits, but a wrapper forwarding SIGTERM to
    # hass is still inside its own 20-second window at that point: confirm the
    # pid is gone before a caller deploys files under a live home.
    deadline = time.monotonic() + STOP_WAIT_SEC + 10
    while time.monotonic() < deadline:
        state, _ = _launchd_info()
        if not state:
            return True
        time.sleep(0.2)
    log_state("FAIL", f"service: still {state} after {STOP_WAIT_SEC + 10}s")
    return False


def _launchd_set_enabled(on: bool) -> bool:
    """Turn start-at-login on or off; True once launchd's ledger agrees.

    Verified against ``print-disabled``, never against the exit code: ``enable``
    and ``disable`` report nothing useful, and a disabled label then makes
    ``bootstrap`` fail with a bare ``5: Input/output error`` — measured on
    macOS 15 on 11-07, together with the two facts below.  That opaque failure
    is exactly why this runs *before* the verb that needs it instead of being
    diagnosed from it afterwards.

    1. ``launchctl disable`` is this platform's ``mask``, stronger than
       ``systemctl --user disable``: it gates *loading*, so ``bootstrap`` is
       refused while the record says disabled, on the same uid, without root.
    2. It gates loading only.  Measured the same day: a running job was disabled
       and its process killed with SIGKILL; KeepAlive brought it back 15s later
       (new pid, HTTP 200).  The crash-restart policy is untouched, which is
       what this verb promises — it changes boot behaviour and nothing else.

    Idempotent: the ledger is read first, so a second call issues no command.
    ``_autostart_state()`` answers from that same ledger and treats "no record"
    as on (the plist carries ``RunAtLoad=true``), so this converges from any of
    the three states instead of assuming a record exists.
    """
    verb = "enable" if on else "disable"
    if _autostart_state() == on:
        return True
    r = _launchctl(verb, _launchd_target())
    if r is None:
        log_state("FAIL", "service: launchctl could not run")
        return False
    if r.returncode != 0:
        chatter = ((r.stderr or "") + (r.stdout or "")).strip()
        why = chatter.splitlines()[-1] if chatter else f"launchctl exited {r.returncode}"
        log_state("FAIL", f"cannot {verb} the service — {why}")
        return False
    if _autostart_state() != on:
        log_state("FAIL", f"service: launchctl {verb} did not take — "
                          f"launchctl print-disabled {_launchd_domain()}")
        return False
    return True


def _plist_tree(text: str) -> str | None:
    """The source tree an existing plist points at, for the repoint message."""
    from xml.sax.saxutils import unescape
    m = re.search(r"<key>WorkingDirectory</key>\s*<string>(.*?)</string>", text)
    return unescape(m.group(1)) if m else None


def _install_plist() -> bool:
    """Make the plist on disk match this tree.  Content-compared, like the unit.

    A plist is read when it is bootstrapped, not when it is written, so this
    only puts bytes on disk; ``_service_up_launchd`` is what makes launchd look
    at them again.
    """
    text, path = _render_plist()
    try:
        current: str | None = path.read_text(encoding="utf-8")
    except OSError:
        current = None
    if current == text:
        return True
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    except OSError as e:
        log_state("FAIL", _tilde_text(f"service: cannot write {path} — {e}"))
        return False
    if current is None:
        log(_tilde_text(f"service installed: {path}"))
    else:
        old = _plist_tree(current)
        if old and old != str(PROJECT_ROOT):
            log(_tilde_text(f"service repointed: {old} -> {PROJECT_ROOT}"))
        else:
            log(_tilde_text(f"service: plist updated ({path})"))
    return True


def _service_up_launchd() -> int:
    """Write, register and start the job; return its pid, or 0 on failure.

    0 means the start did not happen and the caller must not fall back to
    spawning — the same rule as ``_service_up``, for the same reason.

    ``bootstrap`` refuses a label that is already loaded, and the plist bytes
    may be newer than what launchd holds, so the sequence is always "bootout,
    then bootstrap".  Nothing of ours is running when this is reached: ``start``
    only calls it from its cold path.
    """
    if not _install_plist():
        return 0
    _launchd_bootout()
    r = _launchctl("bootstrap", _launchd_domain(), str(UNIT_PATH))
    if r is None:
        log_state("FAIL", "service: launchctl could not run")
        return 0
    if r.returncode != 0:
        chatter = ((r.stderr or "") + (r.stdout or "")).strip()
        why = chatter.splitlines()[-1] if chatter else f"launchctl bootstrap exited {r.returncode}"
        log_state("FAIL", f"service did not start — {why}")
        return 0
    for _ in range(100):
        state, pid = _launchd_info()
        if pid:
            return pid
        if not state:
            break
        time.sleep(0.1)
    log_state("FAIL", "service started but launchd reports no pid")
    return 0


def _login_user() -> str:
    """The account that owns the user manager, without trusting ``$USER``.

    A non-login shell (ssh command, cron, systemd itself) can have no ``USER``,
    and the wrong name here would query somebody else's linger flag.
    """
    try:
        import pwd
        return pwd.getpwuid(os.getuid()).pw_name
    except (ImportError, KeyError, OSError):
        return os.environ.get("USER") or os.environ.get("LOGNAME") or ""


def _linger_state() -> str | None:
    """Does this user's manager survive logout?  ``yes`` / ``no`` / ``None``.

    ``None`` means "could not ask" — a container without logind, or a bus that
    is not there.  It is deliberately distinct from ``no``: one is a setting to
    fix, the other is a question that never got answered.
    """
    user = _login_user()
    if not user:
        return None
    try:
        r = subprocess.run(["loginctl", "show-user", user, "-p", "Linger"],
                           capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return None
    if r.returncode != 0:
        return None
    out = (r.stdout or "").strip()
    if not out.startswith("Linger="):
        return None
    return out.split("=", 1)[1].strip() or None


def _linger_ensure() -> bool:
    """Open linger before the start touches anything.  False = start must stop.

    Without linger systemd starts the user manager only when somebody logs in,
    so a reboot leaves the unit inactive until that login — which breaks the
    one promise the service layer exists to keep.  That is why this runs as a
    gate at the entry rather than as a note at the end: learning it after a
    successful start would turn the promise into a postscript.

    The bare form is the right one here: loginctl sends an empty user, logind
    resolves it to the owner of the caller's session, and logind picks the
    policy action by ``target == euid`` — asking for oneself gets
    ``set-self-linger`` (``allow_any=yes``), never ``auth_admin_keep``.  A
    policy file only counts on a host that runs polkit, though: without
    polkitd logind cannot evaluate any action and answers EACCES even for
    ``allow_any=yes`` (measured 11-05 on Debian 13 with no polkitd), so root is
    the only way in.  That retry goes through ``sudo -n`` and only that form: a
    plain sudo would sit on a password prompt no unattended start can answer,
    while ``-n`` either succeeds on a NOPASSWD host or fails immediately.

    The verdict is read back from ``Linger``, never from the wording of a
    failure: without polkit logind answers ``Could not enable linger: No such
    device or address`` (measured 11-10 on Debian 13) — there is no
    permission word anywhere in it — so a keyword test calls that failure a
    success and the start ends up promising a boot it cannot deliver.
    """
    if _linger_state() == "yes":
        return True                 # idempotent, and silent on the happy path

    # Two bounded attempts, ordered by how little they cost the host: the bare
    # form asks nobody for anything, and only when that fails do we spend one
    # non-interactive sudo.  Each attempt's own last line is kept, so the report
    # below quotes loginctl (or sudo) instead of guessing at a cause.
    attempts = [("loginctl", ["loginctl", "enable-linger"])]
    user = _login_user()
    if user:
        attempts.append(("sudo", ["sudo", "-n", "loginctl", "enable-linger", user]))

    said = []
    for label, cmd in attempts:
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
        except (OSError, subprocess.SubprocessError) as e:
            said.append((label, str(e)))
            continue
        if _linger_state() == "yes":
            return True             # it worked; the wording never mattered
        lines = ((r.stderr or "") + (r.stdout or "")).strip().splitlines()
        if lines:
            said.append((label, lines[-1]))

    # Neither attempt moved it, so the start stops here instead of promising a
    # boot it cannot deliver.  "$USER" keeps the hint copy-pastable: the shell
    # expands it before sudo runs, so the name is the user's, not root's.
    log_state("FAIL", "linger is off and could not be enabled without root")
    for label, text in said:
        # sudo's own message already starts with "sudo: ", so a plain label
        # prefix would read "sudo: sudo: a password is required".
        prefix = f"{label}: "
        if text.startswith(prefix):
            text = text[len(prefix):]
        log(f"      {label}: {text}")
    log(f'      run: sudo loginctl enable-linger "$USER" && {_cmd("start")}')
    return False


def _service_up() -> int:
    """Install, enable and start the unit; return hass's MainPID, or 0 on failure.

    0 means the start did not happen — the caller must return rather than fall
    back to spawning, because two start sources on one port is exactly what the
    unit exists to prevent.
    """
    if not _install_unit():
        return 0
    # Clear the start limiter before an explicit start.  StartLimitBurst=5 in
    # 120s is there to stop a *crash loop* from spinning, but it also outlives
    # the cause: after five failed boots, systemd answers every attempt with
    # "Start request repeated too quickly" until the window expires, so a user
    # who just fixed the problem and re-ran `homeant start` would still be
    # refused, with a message that names neither the unit nor the reason.
    # Measured on Debian 13: the sixth attempt inside 120s fails instantly this
    # way even though the interpreter was restored two lines earlier.
    _systemctl("reset-failed", SERVICE_NAME)
    r = _systemctl("start", SERVICE_NAME)
    if r is None:
        log_red("service: systemctl --user start could not run")
        return 0
    if r.returncode != 0:
        detail = (r.stderr or r.stdout or "").strip()
        log_state("FAIL", f"service did not start — {detail or 'systemctl --user start failed'}")
        _service_reap()
        return 0
    # Type=simple forks before MainPID settles; a short poll avoids reporting
    # "no MainPID" for the handful of milliseconds it is still 0.
    for _ in range(50):
        pid = _service_main_pid()
        if pid:
            return pid
        if not _service_active():
            break
        time.sleep(0.1)
    log_state("FAIL", "service started but systemd reports no MainPID")
    _service_reap()
    return 0


# ── Windows: the service control manager ─────────────────────────────────────
#
# A Windows service is a registry entry, not a file, and the SCM is the only
# supervisor this design accepts there — Task Scheduler is deliberately not a
# fallback.  Two rules shape the code below.
#
# 1. ``sc.exe`` is never called.  Its text is localised (measured on a zh-CN
#    host: the state comes back translated, not as the word RUNNING), so every
#    query would need a locale table.  pywin32 already speaks SCM and the venv
#    carries it — ``mcp`` depends on it and the dependency pins live in
#    pyproject.toml — so the state is a number and nothing has to be parsed.
# 2. pywin32 is imported *inside* these functions, never at module load: a
#    Linux host must not care that it exists, and a host without it has to get
#    one readable line instead of a traceback.

WIN_SERVICE_KEY = rf"SYSTEM\CurrentControlSet\Services\{SERVICE_NAME}"
SERVICE_DISPLAY_NAME = "HomeAnt"
SERVICE_DESCRIPTION = "HomeAnt — Control home through Agent"
# ── service-layer logging ────────────────────────────────────────────────────
# hass's log is hass's.  ``home-assistant.log`` in HA_ROOT is the one
# authoritative record of what the home did, HA owns its rotation, and nothing
# here keeps a second copy of it.
#
# What is left for this process to publish is the service layer itself: the
# start banner, the gate verdicts, "hass exited with code N", broker state.
# None of that goes to a file of ours — each platform already runs a log
# service that owns retention, rotation and querying, and leaning on it is what
# lets `uninstall` leave nothing behind:
#
#   Linux    stdout -> journald      (systemd is the parent; it costs nothing)
#   macOS    unified log             (`logger` is the only working entry point;
#                                     measured: a raw write to /var/run/syslog
#                                     and libc's syslog(3) are both dropped)
#   Windows  Application event log   (the SCM captures no stdout at all; the
#                                     source is registered by `install`)
#
# print() still happens everywhere: a foreground run has a console and that is
# where a human expects to read the same line.  These sinks are additive.
EVENT_SOURCE = "HomeAnt"
# ``eventcreate``'s id: its message template is "%1", so the string we insert is
# shown verbatim instead of "the description cannot be found".
EVENT_ID = 100


def _syslog_line(msg: str, is_error: bool) -> None:
    """Publish one line to the macOS unified log.

    ``logger`` costs ~2 ms (measured: 20 runs in 42 ms) and it is the only path
    that works — the daemon accepts what ``logger`` sends, not what a socket or
    an in-process syslog(3) call sends, so both of those come out empty in
    ``log show``.

    syslog caps a message near 1 KiB (measured: 3000 chars in, 1069-byte line
    out).  Every line this layer emits is short; a traceback is hass's and goes
    to hass's log.
    """
    with contextlib.suppress(OSError, subprocess.SubprocessError):
        subprocess.run(
            ["/usr/bin/logger", "-t", EVENT_SOURCE.lower(), "-p",
             "user.err" if is_error else "user.info", msg],
            stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL, timeout=5, check=False)


def _eventlog_line(msg: str, is_error: bool) -> None:
    """Publish one line to the Windows Application event log.

    ``ReportEvent`` rather than ``servicemanager.LogInfoMsg``: the latter needs
    a process that has finished the SCM handshake, and most lines worth having
    are written by the ``start --foreground`` child, which has not.
    """
    try:
        import win32evtlog
        import win32evtlogutil
    except ImportError:
        return
    with contextlib.suppress(Exception):
        win32evtlogutil.ReportEvent(
            EVENT_SOURCE, EVENT_ID,
            eventType=(win32evtlog.EVENTLOG_ERROR_TYPE if is_error
                       else win32evtlog.EVENTLOG_INFORMATION_TYPE),
            strings=[msg])


def _mirror_log(msg: str, is_error: bool = False) -> None:
    """Send one line to this platform's log service; print() covers Linux.

    The ``[homeant]`` marker is added here rather than at the call sites:
    ``print()`` prefixes the console path, and these two sinks are the only
    other consumers, so without this line the platform logs would be missing
    the marker every other surface shows — and a reader grepping one log for
    ``[homeant]`` would come up empty on Windows and macOS only.

    macOS: only when no terminal is attached.  A hand-run ``homeant start``
    writes its lines to that terminal, and a second copy in the unified log
    would be noise nobody asked for; launchd's stdout is /dev/null, which is
    exactly the case this exists for.

    Windows: only under the SCM, for the same reason.  ``HOMEANT_UNDER_SERVICE``
    is injected by the service host when it spawns the foreground child.
    """
    msg = f"[homeant] {msg}"
    if sys.platform == "darwin":
        if not _INTERACTIVE:
            _syslog_line(msg, is_error)
    elif sys.platform == "win32":
        if os.environ.get("HOMEANT_UNDER_SERVICE") == "1":
            _eventlog_line(msg, is_error)


# SERVICE_STOPPED(1) … SERVICE_RUNNING(4) … -> two words.  Pending joins
# "stopped" on purpose: a transition is not a start, and `status` has exactly
# one line to spend on this.
_WIN_STATES = {1: "stopped", 2: "stopped", 3: "stopped", 4: "running",
               5: "stopped", 6: "stopped", 7: "stopped"}


def _win_scm():
    """``(win32service, win32serviceutil)``, or None when pywin32 is absent."""
    try:
        import win32service
        import win32serviceutil
    except ImportError:
        return None
    return win32service, win32serviceutil


def _is_admin() -> bool:
    """May this process write HKLM and create services?"""
    try:
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except (AttributeError, OSError):
        return False


# ── firewall: one best-effort pass at the moment `start` already has privilege ──
#
# This is installer code, not the agent opening ports: it runs only when the
# *user* runs `start`, the way mainstream installers register a firewall
# exception on first launch.  Three rules keep it honest:
#   * idempotent — look before adding, so a second start is a no-op;
#   * best-effort — a failed write never blocks start, and `status` keeps its
#     "please allow" line as the fallback on every platform and in every state;
#   * ours only — PORT plus the broker port this home configured, never a port
#     lifted off some other process.
#
# No self-elevation: Windows writes only from an already-elevated start, Linux
# only through a non-interactive `sudo -n` that either works or returns at once.
# macOS has no such moment and filters per app rather than per port, so it is
# left to the status hint instead of writing a rule that rots on every rebuild.

def _fw_rule_name(port: int) -> str:
    """The idempotency key: one rule name we own, stable across runs."""
    return f"HomeAnt-{port}"


def _fw_run(cmd: list[str]) -> tuple[int, str]:
    """One firewall command; every failure becomes data, never an exception."""
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
        out = ((r.stdout or "") + (r.stderr or "")).strip()
        return r.returncode, out
    except Exception:
        return 1, ""


def _fw_windows(ports: list[int]) -> None:
    """netsh advfirewall inbound TCP rules, added only when absent.

    ``show rule`` reads unelevated, so a home that is already allowed stays
    quiet even from a plain prompt; ``add`` needs elevation and simply fails
    (with the status hint still pending) when this prompt does not have it.
    """
    added: list[int] = []
    for p in ports:
        name = _fw_rule_name(p)
        rc, out = _fw_run(["netsh", "advfirewall", "firewall", "show", "rule",
                           f"name={name}"])
        if rc == 0 and name.lower() in out.lower():
            continue
        rc, _ = _fw_run(["netsh", "advfirewall", "firewall", "add", "rule",
                         f"name={name}", "dir=in", "action=allow",
                         "protocol=TCP", f"localport={p}"])
        if rc == 0:
            added.append(p)
    if added:
        log("firewall: inbound allowed " + ", ".join(f"tcp/{p}" for p in added))


def _fw_privilege() -> list[str] | None:
    """Empty prefix when already root, ``sudo -n`` when it works, else None."""
    try:
        if os.geteuid() == 0:
            return []
    except AttributeError:
        return None
    rc, _ = _fw_run(["sudo", "-n", "true"])
    return ["sudo", "-n"] if rc == 0 else None


def _fw_linux(ports: list[int]) -> None:
    """First available backend wins: ufw, then firewalld, then raw iptables.

    Each backend is asked whether the rule already exists before it is added,
    and every command carries the non-interactive privilege prefix — `start`
    must never sit on a password prompt.  With no backend installed, or no
    privilege reachable, this is a silent no-op and the status hint stands.
    """
    prefix = _fw_privilege()
    if prefix is None:
        return
    backend = next((t for t in ("ufw", "firewall-cmd", "iptables")
                    if shutil.which(t)), None)
    if backend is None:
        return

    added: list[int] = []
    for p in ports:
        spec = f"{p}/tcp"
        if backend == "ufw":
            rc, out = _fw_run(prefix + ["ufw", "status"])
            if rc == 0 and re.search(rf"(?m)^\s*{re.escape(spec)}\s", out):
                continue
            rc, _ = _fw_run(prefix + ["ufw", "allow", spec])
        elif backend == "firewall-cmd":
            rc, _ = _fw_run(prefix + ["firewall-cmd", f"--query-port={spec}"])
            if rc == 0:
                continue
            rc, _ = _fw_run(prefix + ["firewall-cmd", "--permanent",
                                      f"--add-port={spec}"])
            if rc == 0:
                _fw_run(prefix + ["firewall-cmd", "--reload"])
        else:  # iptables
            base = ["iptables", "-I", "INPUT", "-p", "tcp", "--dport", str(p),
                    "-j", "ACCEPT"]
            rc, _ = _fw_run(prefix + ["iptables", "-C"] + base[2:])
            if rc == 0:
                continue
            rc, _ = _fw_run(prefix + base)
        if rc == 0:
            added.append(p)
    if added:
        log("firewall: inbound allowed " + ", ".join(f"tcp/{p}" for p in added))


def _firewall_ensure() -> None:
    """Best-effort inbound allow for the ports this home listens on.

    Called once from `start`, after every privilege/autostart gate has passed
    and before the "already running" branch, so even an idempotent re-start
    keeps its exception.  The status hint stays on purpose: a write this
    process could not perform is still the user's to do.
    """
    ports = [PORT]
    mqtt_port = _mqtt_conf().get("port")
    if isinstance(mqtt_port, int) and 0 < mqtt_port < 65536:
        ports.append(mqtt_port)
    if IS_WIN:
        if _is_admin():
            _fw_windows(ports)
    elif sys.platform == "darwin":
        return                      # per-app firewall, no unprivileged moment
    else:
        _fw_linux(ports)


def _win_service_installed() -> bool:
    """Is the registration there?  Read from the registry: no pywin32, no rights.

    ``sc query`` would answer the same question at the price of a subprocess
    whose output has to be understood in whatever language Windows is set to.
    """
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, WIN_SERVICE_KEY):
            return True
    except (ImportError, OSError):
        return False


def _win_service_state() -> str:
    """``running`` / ``stopped`` / ``not installed`` / ``unknown``."""
    if not _win_service_installed():
        return "not installed"
    scm = _win_scm()
    if scm is None:
        return "unknown"
    try:
        status = scm[1].QueryServiceStatus(SERVICE_NAME)
    except Exception:       # pywin32 raises its own type, which is not OSError
        return "unknown"
    return _WIN_STATES.get(status[1], "unknown")


def _win_service_bin_path() -> str:
    """The command line the SCM will run.

    The venv interpreter plus the script path — the same anchor the systemd
    unit uses, and never a copy: the project is one file whose name cannot be
    imported (``homeant.py`` has no module form), so ``-m`` is out and an
    absolute script path is the only shape that works.  ``--service-host`` is
    what turns that process into something the SCM can talk to.
    """
    py = PROJECT_ROOT / ".venv" / "Scripts" / "python.exe"
    script = PROJECT_ROOT / "scripts" / "homeant.py"
    return f'"{py}" "{script}" start --service-host'


def _win_reg_value(name: str) -> str | None:
    """Read one value from the service key, or None."""
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, WIN_SERVICE_KEY) as k:
            if name == "Environment":
                value, _ = winreg.QueryValueEx(k, name)
                return "|".join(value) if isinstance(value, list) else str(value)
            value, _ = winreg.QueryValueEx(k, name)
            return str(value)
    except (ImportError, OSError):
        return None


def _win_service_env() -> list[str]:
    """The environment the service carries — one REG_MULTI_SZ, four entries.

    Two unrelated jobs share this value, and only the first one was understood
    when it was written:

    ``USERPROFILE`` — a service runs as LocalSystem, where ``Path.home()`` is
    ``system32\\config\\systemprofile``, so without this every HA_ROOT lookup in
    the supervised process points at a directory nobody meant.  The SCM injects
    it into the wrapper *and* into the hass it spawns.

    ``TMP`` / ``TEMP`` / ``UV_CACHE_DIR`` — HA installs component requirements
    at run time with ``uv pip install`` into the venv.  With uv's defaults that
    cache lives in SYSTEM's own ``%LOCALAPPDATA%``, and the files uv then moves
    into site-packages keep SYSTEM's ACEs instead of inheriting the venv's:
    measured 11-14, 16995 of 26805 files became unreadable to the user who owns
    the install (``hass_frontend`` 15504, ``numpy`` 912 — the web UI answered
    500), and neither ``Get-Acl`` nor ``icacls /reset`` could repair them
    because that user is not their owner.  Pointed inside HA_ROOT, cache and
    temp inherit the data directory's ACLs; re-installing ``numpy`` through the
    service then produced 912 files, 0 unreadable (measured 11-14).
    """
    return [
        f"USERPROFILE={Path.home()}",
        f"TMP={HA_ROOT / 'tmp'}",
        f"TEMP={HA_ROOT / 'tmp'}",
        f"UV_CACHE_DIR={HA_ROOT / 'cache'}",
    ]


def _win_service_home_ok() -> bool:
    """Is the one entry HA_ROOT depends on already there?

    Deliberately *not* the whole of ``_win_service_env()``: a non-elevated
    ``start`` reaches this check on the hot path and cannot write HKLM, while
    missing working dirs are a warning — refusing to start over them would
    turn a pre-11-14 install into a machine that no longer starts at all.
    """
    want = f"USERPROFILE={Path.home()}"
    have = _win_reg_value("Environment") or ""
    return want in have.split("|")


def _win_service_dirs_ok() -> bool:
    """Are the working dirs set?  False on every install made before 11-14."""
    have = (_win_reg_value("Environment") or "").split("|")
    return all(entry in have for entry in _win_service_env()[1:])


def _win_service_home_write(quiet: bool = False) -> bool:
    """Write the whole service environment.  Administrator rights required.

    ``quiet`` is for the repair attempt on the start hot path: a plain user
    cannot write HKLM there, and that is expected rather than a failure — it
    costs one denied open, no UAC prompt, and the caller turns it into a
    warning instead of a FAIL.
    """
    for d in (HA_ROOT / "tmp", HA_ROOT / "cache"):
        try:
            d.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            log(f"service: cannot create {d} — {e}")
    try:
        import winreg
        with winreg.CreateKeyEx(winreg.HKEY_LOCAL_MACHINE, WIN_SERVICE_KEY, 0,
                                winreg.KEY_SET_VALUE) as k:
            winreg.SetValueEx(k, "Environment", 0, winreg.REG_MULTI_SZ,
                              _win_service_env())
    except (ImportError, OSError) as e:
        if not quiet:
            log_state("FAIL", f"cannot set the service environment — {e}")
        return False
    return True


def _win_grant_control(win32service, hs) -> None:
    """Add RP (start) and WP (stop) for interactive users to the service DACL.

    ``sc create`` leaves ``IU`` with query/interrogate rights only, so every
    ``homeant stop`` would need an elevated prompt — the one promise this design
    cannot break.  Only this service's DACL is touched, and only the ``IU`` ace:
    administrators keep their full rights, SYSTEM keeps everything, and nobody
    gains the right to *reconfigure* the service (``DC``), which would let any
    user repoint the binary at anything.
    """
    try:
        import win32security
        sd = win32service.QueryServiceObjectSecurity(
            hs, win32security.DACL_SECURITY_INFORMATION)
        sddl = win32security.ConvertSecurityDescriptorToStringSecurityDescriptor(
            sd, win32security.SDDL_REVISION_1,
            win32security.DACL_SECURITY_INFORMATION)
    except Exception as e:
        log(f"service: cannot read the service DACL — {e}")
        return
    m = re.search(r"\(A;;([A-Z]+);;;IU\)", sddl)
    if m is None:
        # A hardened image whose default DACL has no interactive-user ace.
        # Not a failure — start/stop will simply ask for elevation, which is
        # the behaviour this is improving on.
        log("service: no interactive-user ACE to extend — start/stop will "
            "need administrator rights")
        return
    rights = m.group(1)
    pairs = {rights[i:i + 2] for i in range(0, len(rights) - 1, 2)}
    if {"RP", "WP"} <= pairs:
        return
    try:
        patched = sddl.replace(m.group(0), f"(A;;{rights}RPWP;;;IU)")
        win32service.SetServiceObjectSecurity(
            hs, win32security.DACL_SECURITY_INFORMATION,
            win32security.ConvertStringSecurityDescriptorToSecurityDescriptor(
                patched, win32security.SDDL_REVISION_1))
    except Exception as e:
        log(f"service: cannot grant start/stop to users — {e}")


def _win_failure_flag_api():
    """Query/set ``SERVICE_CONFIG_FAILURE_ACTIONS_FLAG`` through advapi32.

    pywin32 cannot do this one level, and that is not a guess: the strings in
    ``win32service.pyd`` are ``QueryServiceConfig2: Level %d is not supported``
    and ``Unsupported information level``, and only
    ``SERVICE_CONFIG_FAILURE_ACTIONS`` (2) has a known shape there.  The flag is
    level 4.  Both calls therefore go to the Win32 API directly, which takes a
    plain ``BOOL*`` for this level.

    Returns ``(get, put, why)``: ``get(handle)`` is ``True``/``False``/``None``
    (``None`` = the read failed, so the caller still tries to write),
    ``put(handle)`` is the boolean result, and ``why()`` names the last Win32
    error.  ``None`` when advapi32 is not reachable at all.
    """
    try:
        import ctypes
        from ctypes import wintypes

        lib = ctypes.WinDLL("advapi32", use_last_error=True)
        lib.QueryServiceConfig2W.argtypes = (
            wintypes.HANDLE, wintypes.DWORD, ctypes.c_void_p,
            ctypes.POINTER(wintypes.DWORD))
        lib.QueryServiceConfig2W.restype = wintypes.BOOL
        lib.ChangeServiceConfig2W.argtypes = (
            wintypes.HANDLE, wintypes.DWORD, ctypes.c_void_p)
        lib.ChangeServiceConfig2W.restype = wintypes.BOOL
    except (AttributeError, OSError):
        return None

    level = 4  # SERVICE_CONFIG_FAILURE_ACTIONS_FLAG

    def get(handle: int):
        value = wintypes.BOOL()
        needed = wintypes.DWORD(0)
        if not lib.QueryServiceConfig2W(
                handle, level, ctypes.byref(value), ctypes.byref(needed)):
            return None
        return bool(value.value)

    def put(handle: int) -> bool:
        value = wintypes.BOOL(True)
        return bool(lib.ChangeServiceConfig2W(handle, level, ctypes.byref(value)))

    def why() -> str:
        return str(ctypes.WinError(ctypes.get_last_error()))

    return get, put, why


def _win_put_crash_flag(handle: int) -> bool | None:
    """Set the flag on one open service handle.

    ``True`` = written, ``None`` = it was already on (nothing written),
    ``False`` = refused, and the reason has been logged.  Split out because two
    callers need it: the repair path (which opens the service itself) and
    registration (which already holds a handle it created).
    """
    api = _win_failure_flag_api()
    if api is None:
        return False
    get, put, why = api
    try:
        if get(handle):
            return None
        if not put(handle):
            log(f"service: cannot enable restart-on-crash — {why()}")
            return False
    except Exception as e:
        log(f"service: cannot enable restart-on-crash — {e}")
        return False
    return True


def _win_ensure_crash_recovery() -> None:
    """Flag a plain non-zero exit as a failure too, when it is still unset.

    Registration writes this, so every service installed from now on has it.
    A service registered by an earlier build has the failure *actions* and not
    the flag, and the SCM then restarts it only when the process crashes.  hass
    dying is not a crash: the host sees its child's exit status and returns that
    code, which is an ordinary exit — so the home would stay down until someone
    noticed.  Linux gets this for free from ``Restart=on-failure``.

    Best effort on purpose: a start that is otherwise fine must not fail over a
    setting that only matters after a crash — but a *silent* except is what hid
    this being broken for three attempts, so a failure now says so in one line
    and still returns normally.      Nothing is written when the flag is already
    right, and the caller skips all of it when we are not elevated.  A service
    that is not registered yet is skipped too: registration writes the flag
    itself, and calling OpenService before that prints a spurious 1060 line on
    the first `start` after an uninstall.
    """
    if not _win_service_installed():
        return
    import win32service

    try:
        hscm, hs = _win_open_service(
            win32service, win32service.SERVICE_CHANGE_CONFIG)
    except Exception as e:
        log(f"service: cannot open the service to enable restart-on-crash — {e}")
        return
    try:
        if _win_put_crash_flag(int(hs)):
            log("service: restart-on-crash enabled")
    except Exception as e:
        log(f"service: cannot enable restart-on-crash — {e}")
    finally:
        for h in (hs, hscm):
            try:
                win32service.CloseServiceHandle(h)
            except Exception:
                pass


def _win_event_source_ensure() -> bool:
    """Register this product as an Application-log source, idempotently.

    Needed because ``_eventlog_line`` writes under ``HomeAnt``: without the
    key, the record still lands but every viewer shows "the description for
    Event ID 100 cannot be found", and ``Get-WinEvent -ProviderName HomeAnt``
    has nothing to filter on.

    ``EventCreate.exe`` is the message file on purpose — its id-100 template is
    ``%1``, so the string we insert is displayed verbatim.  Writing HKLM needs
    administrator rights, the same ones the service registration needs, so this
    runs on that path; a non-elevated ``start`` reads the key and leaves it.
    """
    key = rf"SYSTEM\CurrentControlSet\Services\EventLog\Application\{EVENT_SOURCE}"
    want = r"%SystemRoot%\System32\EventCreate.exe"
    try:
        import win32api
        import win32con
        import win32evtlogutil
    except ImportError:
        return False
    try:
        hkey = win32api.RegOpenKeyEx(win32con.HKEY_LOCAL_MACHINE, key)
    except Exception:
        hkey = None
    if hkey is not None:
        try:
            cur = str(win32api.RegQueryValueEx(hkey, "EventMessageFile")[0])
            if cur.lower() == want.lower():
                return True
        except Exception:
            pass
        finally:
            win32api.RegCloseKey(hkey)
    try:
        win32evtlogutil.AddSourceToRegistry(EVENT_SOURCE, msgDLL=want)
    except Exception:
        return False
    return True


def _win_service_ensure() -> bool:
    """Create the registration, or repoint it, and nothing when it is right.

    Called on every ``start``, but most of this needs administrator rights, so
    the first question is whether anything needs doing: an in-place upgrade
    leaves ``ImagePath`` byte-identical and this returns without writing HKLM.
    A moved tree rewrites the path and says so — the same line the systemd side
    prints, and the only honest way to answer "which tree is the service really
    running".
    """
    scm = _win_scm()
    if scm is None:
        log_state("FAIL", "pywin32 is required for service mode — "
                          "uv sync installs it (mcp depends on it)")
        return False
    win32service = scm[0]
    bin_path = _win_service_bin_path()
    installed = _win_service_installed()
    # Before the hot-path return: a read of one HKLM key costs nothing, and an
    # upgrade that predates this line still needs the source once.  A
    # non-elevated run cannot write it and gets False back, which is not fatal
    # here — the service works, only the viewer's description is missing.
    _win_event_source_ensure()

    if installed and _win_reg_value("ImagePath") == bin_path and _win_service_home_ok():
        # The hot path is what a non-elevated `start` takes, and it stays free
        # of SCM calls on purpose: every one of them needs a right the prompt
        # denies.  The one setting an upgrade cannot reach is repaired by
        # _win_ensure_crash_recovery, which cmd_start calls at the entry gate
        # where it also covers the "already running" path.
        #
        # The working dirs get the same treatment, for a harder reason: an
        # An install registered by an older release only ever reaches *this* branch, so
        # leaving it to the registration code means the repair never runs.  A
        # denied HKLM write is the normal non-elevated outcome — no UAC prompt
        # — and only downgrades to a warning here.
        if not _win_service_dirs_ok() and not _win_service_home_write(quiet=True):
            log("WARN  service: TMP/TEMP/UV_CACHE_DIR unset — HA run-time "
                "installs may leave .venv files you cannot read")
            log_run(_cmd("start"))
        return True

    try:
        hscm = win32service.OpenSCManager(
            None, None, win32service.SC_MANAGER_CREATE_SERVICE)
    except Exception as e:
        log_state("FAIL", f"cannot open the service manager — {e}")
        if not _is_admin():
            log_run(_cmd("start"))
        return False

    try:
        try:
            if installed:
                hs = win32service.OpenService(
                    hscm, SERVICE_NAME, win32service.SERVICE_ALL_ACCESS)
            else:
                hs = win32service.CreateService(
                    hscm, SERVICE_NAME, SERVICE_DISPLAY_NAME,
                    win32service.SERVICE_ALL_ACCESS,
                    win32service.SERVICE_WIN32_OWN_PROCESS,
                    win32service.SERVICE_AUTO_START,
                    win32service.SERVICE_ERROR_NORMAL,
                    bin_path, None, 0, None, None, None)
        except Exception as e:
            log_state("FAIL", f"cannot {'open' if installed else 'create'} "
                              f"the service — {e}")
            return False

        try:
            if installed:
                old = _win_reg_value("ImagePath") or "(none)"
                if old != bin_path:
                    win32service.ChangeServiceConfig(
                        hs, win32service.SERVICE_NO_CHANGE,
                        win32service.SERVICE_NO_CHANGE,
                        win32service.SERVICE_NO_CHANGE, bin_path,
                        None, 0, None, None, None, None)
                    log(_tilde_text(f"service repointed: {old} -> {bin_path}"))
            win32service.ChangeServiceConfig2(
                hs, win32service.SERVICE_CONFIG_DESCRIPTION, SERVICE_DESCRIPTION)
            # Crash restart, matching Restart=on-failure + RestartSec=10 on
            # Linux.  Three attempts and stop trying: a home that cannot boot is
            # not fixed by a fourth, and an endless retry hides the reason.
            win32service.ChangeServiceConfig2(
                hs, win32service.SERVICE_CONFIG_FAILURE_ACTIONS,
                {"ResetPeriod": 86400, "RebootMsg": "", "Command": "",
                 "Actions": [(win32service.SC_ACTION_RESTART, 10_000)] * 3})
            # Without this flag the actions above fire only when the *process*
            # dies abnormally (TerminateProcess, unhandled exception).  hass
            # dying is not that: the host sees its child exit and returns that
            # code, i.e. an ordinary exit with a non-zero status — which the SCM
            # then treats as a plain stop and does not restart.  Set, so a
            # crashed hass is restarted exactly like Restart=on-failure does it
            # on Linux.  A user-requested stop stays quiet because SvcStop
            # returns 0.
            #
            # Not through win32service: level 4 is unimplemented there (it
            # answers "Unsupported information level", which failed the whole
            # registration when this line was a ChangeServiceConfig2 call).
            # _win_put_crash_flag goes to advapi32 and never raises.
            _win_put_crash_flag(int(hs))
            _win_grant_control(win32service, hs)
        except Exception as e:
            log_state("FAIL", f"cannot configure the service — {e}")
            return False
        finally:
            win32service.CloseServiceHandle(hs)
    finally:
        win32service.CloseServiceHandle(hscm)

    if not (_win_service_home_ok() and _win_service_dirs_ok()) \
            and not _win_service_home_write():
        return False
    if not installed:
        log(f"service installed: {SERVICE_NAME}")
    return True


def _win_open_service(win32service, access: int):
    """Open the SCM and *this* service with exactly the rights the caller needs.

    pywin32's convenience wrappers — ``StartService``, ``StopService``,
    ``RemoveService`` — hard-code ``SC_MANAGER_ALL_ACCESS`` and
    ``SERVICE_ALL_ACCESS``.  Measured on this machine: the service DACL really
    does carry ``RP``/``WP`` for interactive users (see
    ``(A;;CCLCSWRPWPLOCRRC;;;IU)``), yet those wrappers still fail with "Access
    is denied", because opening the *manager* with ``ALL_ACCESS`` is itself
    privileged — ``IU`` holds ``CC LC SW LO CR RC`` and nothing near ``GA``.
    So the manager is opened with ``SC_MANAGER_CONNECT`` (which ``IU`` has by
    default) and the service with the one mask the operation needs.

    Returns ``(hscm, hs)``; the caller closes both.
    """
    hscm = win32service.OpenSCManager(None, None, win32service.SC_MANAGER_CONNECT)
    try:
        hs = win32service.OpenService(hscm, SERVICE_NAME, access)
    except Exception:
        win32service.CloseServiceHandle(hscm)
        raise
    return hscm, hs


def _win_service_set_start(auto: bool) -> bool:
    """Set start-at-boot, or explain why this prompt cannot.

    The hot path is a registry read: ``Start`` is world-readable, so a host that
    is already in the requested state needs no rights at all and no SCM call.
    Changing it is the privileged half — ``ChangeServiceConfig`` needs
    ``SERVICE_CHANGE_CONFIG``, and measured on this machine a plain user gets
    ``(5, 'OpenService', '拒绝访问')`` for that mask.  The right cannot be
    granted to ``IU`` either: it also allows rewriting ``ImagePath``, i.e.
    pointing a LocalSystem service at any binary.

    Refusing up front instead of warning afterwards is the contract every verb
    in this file follows.  A `disable` that "mostly worked" would read as done
    while the home still came back at the next boot.

    ``DEMAND_START`` rather than ``DISABLED``: the service must stay startable
    by hand, and only autostart is being turned off.
    """
    want = "2" if auto else "3"
    if _win_reg_value("Start") == want:
        return True                 # idempotent, no rights, no SCM call
    verb = "enable" if auto else "disable"
    if not _is_admin():
        log_state("FAIL", f"cannot {verb} the service — run as administrator")
        log(f"      run: .\\homeant {verb}")
        return False
    scm = _win_scm()
    if scm is None:
        log_state("FAIL", "pywin32 is required for service mode — "
                          "uv sync installs it (mcp depends on it)")
        return False
    win32service = scm[0]
    try:
        hscm, hs = _win_open_service(win32service,
                                     win32service.SERVICE_CHANGE_CONFIG)
    except Exception as e:
        log_state("FAIL", f"cannot {verb} the service — {e}")
        return False
    try:
        win32service.ChangeServiceConfig(
            hs,
            win32service.SERVICE_NO_CHANGE,
            win32service.SERVICE_AUTO_START if auto else win32service.SERVICE_DEMAND_START,
            win32service.SERVICE_NO_CHANGE,
            None, None, 0, None, None, None, None)
    except Exception as e:
        log_state("FAIL", f"cannot {verb} the service — {e}")
        return False
    finally:
        win32service.CloseServiceHandle(hs)
        win32service.CloseServiceHandle(hscm)
    return True


def _win_service_start() -> bool:
    """Ask the SCM to start it.  StartService blocks until it reports RUNNING."""
    scm = _win_scm()
    if scm is None:
        return False
    win32service = scm[0]
    try:
        hscm, hs = _win_open_service(
            win32service,
            win32service.SERVICE_START | win32service.SERVICE_QUERY_STATUS)
        try:
            # The second argument is mandatory in pywin32's binding even though
            # it means "no command-line arguments": StartService(hs) raises
            # "takes exactly 2 arguments (1 given)".
            win32service.StartService(hs, None)
        finally:
            win32service.CloseServiceHandle(hs)
            win32service.CloseServiceHandle(hscm)
    except Exception as e:
        log_state("FAIL", f"service did not start — {e}")
        return False
    return True


def _win_reap() -> None:
    """Show why the service died, the way journalctl does on Linux.

    The event log is the only place the service layer keeps anything, so this
    asks it the same question ``_service_reap`` asks systemd.  pywin32's API
    rather than ``wevtutil``: the latter writes in the
    console code page, which this process does not decode (measured: a 0xce
    byte in the middle of its output raised UnicodeDecodeError inside
    subprocess's reader thread, so the reader printed "(no events)" while the
    events were right there).
    """
    try:
        import win32evtlog
    except ImportError:
        return
    flags = (win32evtlog.EVENTLOG_BACKWARDS_READ
             | win32evtlog.EVENTLOG_SEQUENTIAL_READ)
    found: list[str] = []
    scanned = 0
    handle = None
    try:
        handle = win32evtlog.OpenEventLog(None, "Application")
        # Newest first, and bounded: an Application log with tens of thousands
        # of foreign records must not turn "why did it fail" into a scan.
        while len(found) < 20 and scanned < 500:
            records = win32evtlog.ReadEventLog(handle, flags, 0)
            if not records:
                break
            scanned += len(records)
            for rec in records:
                if rec.SourceName != EVENT_SOURCE:
                    continue
                msg = "  ".join(rec.StringInserts or ()) or "(no message)"
                found.append(f"{rec.TimeGenerated:%Y-%m-%d %H:%M:%S}  {msg}")
    except Exception:
        return
    finally:
        if handle is not None:
            with contextlib.suppress(Exception):
                win32evtlog.CloseEventLog(handle)
    log(f"last 20 events from the {EVENT_SOURCE} source:")
    print("\n".join(found) or "(no events)", flush=True)


def _launchd_reap() -> None:
    """Show why the job failed, the way journalctl does on Linux.

    The unified log is where this layer published everything.  ``--info`` is
    mandatory (measured: the default level filter hides these records) and the
    predicate is on the message text because ``logger``'s ``-t`` tag does not
    reach the ``eventMessage`` field — only the leading ``[homeant]`` does.
    """
    try:
        r = subprocess.run(
            ["/usr/bin/log", "show", "--last", "10m", "--info",
             "--predicate", 'eventMessage CONTAINS "[homeant]"',
             "--style", "compact"],
            capture_output=True, text=True, timeout=60)
    except (OSError, subprocess.SubprocessError):
        return
    tail = (r.stdout or "").strip().splitlines()[-20:]
    log("last 20 unified-log lines (log show --last 10m --info):")
    print("\n".join(tail) or "(no entries)", flush=True)


def _win_service_stop() -> bool:
    """Stop it and wait for the SCM to confirm.

    The start type is deliberately *not* touched here.  Changing it needs
    ``SERVICE_CHANGE_CONFIG``, which only an administrator may hold — granting
    it to interactive users would let them repoint the binary — so a Windows
    ``stop`` stops the process and leaves start-at-boot alone.  Linux has no
    such split: `disable` there is unprivileged, which is why `cmd_stop` does
    both verbs on that side and one here.
    """
    scm = _win_scm()
    if scm is None:
        return False
    if _win_service_state() != "running":
        return True
    win32service = scm[0]
    try:
        # Same minimal mask as `start`: STOP alone would be enough for the
        # control call, but QUERY_STATUS is what lets the wait below read a
        # state the SCM will actually hand an interactive user.
        hscm, hs = _win_open_service(
            win32service,
            win32service.SERVICE_STOP | win32service.SERVICE_QUERY_STATUS)
        try:
            win32service.ControlService(hs, win32service.SERVICE_CONTROL_STOP)
        finally:
            win32service.CloseServiceHandle(hs)
            win32service.CloseServiceHandle(hscm)
    except Exception as e:
        log_state("FAIL", f"cannot stop the service — {e}")
        return False
    # The SCM reports STOPPED once our SvcStop's tree-kill has finished; wait
    # for it instead of assuming, because the caller may delete the tree next.
    for _ in range(STOP_WAIT_SEC * 2):
        if _win_service_state() != "running":
            return True
        time.sleep(0.5)
    log_state("FAIL", f"service still running after {STOP_WAIT_SEC}s")
    return False


def _service_stop_now() -> bool | None:
    """Stop the supervisor's process without touching its start type.

    ``None`` means nothing supervises this host, so the caller keeps its own way
    of stopping.  Same single verb as ``cmd_stop`` — the difference is only who
    asks: this runs *inside* ``start``, which is about to bring the home back,
    and it also runs inside ``uninstall``, which clears the registration next.
    Both branches wait for the manager to confirm, so a caller that deploys
    files next never races a process still flushing stores.
    """
    kind = _service_kind()
    if kind == "systemd-user" and UNIT_PATH.exists():
        r = _systemctl("stop", SERVICE_NAME)
        if r is None or r.returncode != 0:
            chatter = ((r.stderr or "") + (r.stdout or "")).strip() if r else ""
            why = (chatter.splitlines()[-1] if chatter
                   else f"systemctl exited {r.returncode}" if r
                   else "systemctl is unavailable")
            log_state("FAIL", f"cannot stop the service — {why}")
            return False
        return True
    if kind == "service" and _win_service_installed():
        return _win_service_stop()
    if kind == "launchd" and UNIT_PATH.exists():
        # bootout unloads the job; it does not delete the plist, which is what
        # makes this the "stop, keep the registration" verb `start` expects.
        return _launchd_bootout()
    return None


def _stop_own_hass() -> bool:
    """Stop the instance that owns HA_ROOT, by the one rule this host allows.

    Under a supervisor the request goes to the supervisor, never to the pid:
    killing its child behind its back is indistinguishable from a crash, and the
    SCM/systemd then restarts the home about ten seconds later — right in the
    middle of the redeploy that asked for the stop (measured on Windows: exit
    code 1066 plus the failure actions).  With no supervisor there is nothing to
    ask, so the pid is the only tool; when not even that is readable, report
    failure rather than pretend the port will free itself.
    """
    by_service = _service_stop_now()
    if by_service is not None:
        return by_service
    pid = _ha_instance()
    if pid:
        return _stop_pid(pid)
    return not port_in_use(PORT)


def _win_service_unregister() -> tuple[bool, str | None]:
    """Stop it if it runs, then delete the registration."""
    if not _win_service_installed():
        return True, None
    if not _win_service_stop():
        return False, None
    scm = _win_scm()
    if scm is None:
        log_state("FAIL", "pywin32 is required to remove the service")
        return False, None
    try:
        scm[1].RemoveService(SERVICE_NAME)
    except Exception as e:
        log_state("FAIL", f"cannot delete the service — {e}")
        if not _is_admin():
            log("      run as administrator")
            log("      run: .\\homeant uninstall")
        return False, None
    return True, f"service removed: {SERVICE_NAME}"


def _service_host_main() -> int:
    """Be the Windows service: hand the SCM a well-behaved supervised child.

    The SCM insists on a process that calls ``StartServiceCtrlDispatcherW``
    within 30 seconds and then answers control requests; a plain ``python.exe``
    does neither, which is why ``sc create`` around one fails with error 1053.
    This function supplies exactly that handshake and nothing else — the work
    stays in ``start --foreground``, spawned as a child and watched, so the
    SCM's restart policy sees a real exit code.

    A stop request is not a failure: the child is killed and we exit 0, so the
    failure actions do not resurrect a home the user just stopped.
    """
    try:
        import servicemanager
        # win32service is not optional here: SvcStop reads SERVICE_STOP_PENDING
        # from it, and this module deliberately imports it lazily everywhere
        # else, so leaving it out made the stop handler raise NameError at the
        # first line — the report, the kill and the event were all skipped and
        # the service stayed RUNNING, unstoppable, with nothing in the log.
        import win32event
        import win32service
        import win32serviceutil
    except ImportError:
        # pywin32 is the very thing that is missing, so neither the event log
        # (`win32evtlog`) nor a console is reachable from here — there is
        # nowhere to write.  The SCM records this failure itself under "Service
        # Control Manager", and `install` refuses to register a service without
        # pywin32, so this branch is a last line of defence rather than the
        # normal path.
        return 1

    # Session 0 has no console: sys.stdout/sys.stderr are None, and the first
    # print() inside a start the SCM cannot report would raise AttributeError.
    # Both are rebound to devnull, and the lines that matter go to the
    # Application event log instead (see `_mirror_log`).  The child inherits
    # devnull too, so hass's own output reaches nothing here — hass writes
    # `home-assistant.log` itself, which is the only copy we want of it.
    #
    # devnull rather than a file of ours for a second reason: measured on
    # Win10, two independent append handles to one path overwrite each other's
    # tail (a "service: starting hass" line came out as a stray
    # "...ipts\python.exe)" fragment), so a file would have forced handle
    # inheritance just to stay in order.  devnull has no tail to collide with
    # and nothing to rotate.
    with contextlib.suppress(OSError):
        HA_ROOT.mkdir(parents=True, exist_ok=True)
    # Set on this process, not just on the child: `_mirror_log` reads it, and
    # the host's own lines ("service: starting hass", "hass exited with code N")
    # are exactly the ones worth having when nothing comes back up.  The child
    # inherits the environment, so its Popen call needs no env= of its own.
    os.environ["HOMEANT_UNDER_SERVICE"] = "1"
    stream = child_log = open(os.devnull, "w", encoding="utf-8")
    sys.stdout = stream
    sys.stderr = stream

    state = {"rc": 0}
    py = PROJECT_ROOT / ".venv" / "Scripts" / "python.exe"
    script = PROJECT_ROOT / "scripts" / "homeant.py"

    class _HomeAnt(win32serviceutil.ServiceFramework):
        _svc_name_ = SERVICE_NAME
        _svc_display_name_ = SERVICE_DISPLAY_NAME
        _svc_description_ = SERVICE_DESCRIPTION

        def __init__(self, args):
            super().__init__(args)
            self.stop_event = win32event.CreateEvent(None, 0, 0, None)
            self.child: subprocess.Popen | None = None
            self.stopping = False
            # Two threads call _kill_child in the normal stop (see the guard
            # there); this is the latch that makes the second one a waiter, and
            # the event it waits on.
            self.killed = False
            self.kill_lock = threading.Lock()
            self.kill_done = threading.Event()

        def ServiceCtrlHandlerEx(self, control, event_type, data):
            # Every control the SCM delivers lands here first.  Logged because
            # `ControlService` answering 1061 ("cannot accept control at this
            # time") cannot tell "the SCM never delivered it" apart from "we
            # were called and did nothing" — and that difference is the whole
            # diagnosis.  Volume is a line per start/stop, not per second.
            log(f"service: control {control}")
            return super().ServiceCtrlHandlerEx(control, event_type, data)

        def SvcStop(self):
            # First line, before anything that can raise: whether the control
            # reached this instance at all is the fact worth having.  The
            # parenthesis carries the second half of that fact — reporting
            # returns *silently* when self.ssh is None, and killing returns
            # silently when self.child is None, so a control delivered to an
            # instance that never ran SvcDoRun looks exactly like one delivered
            # here and then ignored.  Printing both handles is what tells the
            # two apart.
            child = self.child
            log(f"service: stop requested (ssh={'set' if self.ssh else 'NONE'}, "
                f"child={child.pid if child else 'NONE'})")
            # Report first: the SCM gives a stop request 30s by default, and a
            # service that says nothing for that long is terminated outright.
            # Guarded because everything after it *is* the stop: an exception
            # in this one call skipped the kill and the event and left a
            # service that still reads RUNNING, refuses every further control
            # with 1061, and cannot be stopped except by killing the process.
            try:
                self.ReportServiceStatus(win32service.SERVICE_STOP_PENDING,
                                         waitHint=STOP_WAIT_SEC * 1000)
            except Exception as e:
                log_state("FAIL", f"service: cannot report STOP_PENDING — {e}")
            self.stopping = True
            try:
                self._kill_child()
            finally:
                # The event must be set even if the kill raises.  A control
                # handler that dies half-way leaves the service running with a
                # stop already queued, and from then on the SCM refuses every
                # further control with 1061 ("cannot accept control at this
                # time") while the state still reads RUNNING — the service is
                # then unstoppable except by killing the process.  Measured on
                # this machine.
                win32event.SetEvent(self.stop_event)

        def _kill_child(self) -> None:
            """End the whole tree: the wrapper is only the middle layer.

            ``child.kill()`` would TerminateProcess the wrapper and leave hass —
            its child — holding the venv and the port, which is the one outcome
            a stop must never produce.  ``taskkill /T`` is the same call
            ``_stop_pid`` makes for an unsupervised instance, and it stays here
            as the fallback: this service is the *other* Windows stop path, so
            it has to ask the core first for the same reason.  Both paths end in
            the same four shutdown stages only if neither skips the request.
            """
            child = self.child
            if child is None:
                return
            if child.poll() is not None:
                return
            # This function has two callers in the ordinary stop, and they are
            # two *threads*: SvcStop runs it from the control thread, and
            # SvcDoRun's loop runs it again the moment `stopping` or the stop
            # event is seen.  That is not a theoretical race — it is the one
            # measured on this machine before the latch: a second HTTP stop was
            # sent to a hass that had already exited (event log, one second
            # after "hass stopped gracefully": "graceful stop: request failed
            # (10061)") and then taskkill ran on a tree the first pass had just
            # ended politely.  So one pass owns the kill; the other only waits.
            with self.kill_lock:
                owner = not self.killed
                self.killed = True
            if owner:
                try:
                    # `child` is `start --foreground`, whose own child is hass —
                    # the one process that can answer `homeassistant.stop`.  Its
                    # pid comes from HA's lock file, the same record `status`
                    # reads.
                    hass_pid = _ha_instance()
                    if hass_pid and _win_graceful_stop(hass_pid) == "gone":
                        log("service: hass stopped gracefully")
                    else:
                        subprocess.run(
                            ["taskkill", "/PID", str(child.pid), "/F", "/T"],
                            capture_output=True,
                            creationflags=_no_console_flags())
                finally:
                    # Set even when the kill raises: the other thread is blocked
                    # on this event and a control handler that leaves it unset
                    # leaves SvcDoRun waiting out its window for nothing.
                    self.kill_done.set()
            else:
                # Reporting STOPPED while the other thread is still asking hass
                # to leave would end the service with its tree half down, so the
                # pass that did not own the kill waits for the one that did.
                self.kill_done.wait(STOP_WAIT_SEC)
            # Both passes wait, because SvcDoRun reports `child.returncode`
            # immediately after this returns and a None there comes out as
            # "service: hass exited with None" — a lie about
            # the one fact that line exists to carry.
            with contextlib.suppress(subprocess.TimeoutExpired):
                child.wait(timeout=STOP_WAIT_SEC)

        def SvcDoRun(self):
            log(f"service: starting hass ({py})")
            # Outer layer.  This host is what the SCM knows about and
            # will not restart on its own, so it is the right place to hold the
            # job handle: if it dies without running any code, the kernel
            # closes the handle and takes `start --foreground`, hass and the
            # broker with it.  That is the one failure mode no `stop` code path
            # can cover.  The child does not arm a job of its own under the SCM
            # (see the foreground entry): it inherits this one, and a second
            # self-assignment would cost it the exit code the restart branch
            # below reads.
            job = _win_job_arm("service")
            if job is not None and not getattr(self, "_job_logged", False):
                self._job_logged = True
                log("service: job object armed — a crash of this process "
                    "takes hass and the broker with it")
            while True:
                # A stop that arrived between passes must not be answered with
                # another hass: the SCM is waiting for this process to leave, and
                # spawning here would turn a stop into a restart.  Checked before
                # the spawn for the same reason: `stopping` is set by the control
                # thread, so it can land during the previous pass.
                if self.stopping:
                    log("service: stop requested before the restart — "
                        "not respawning hass")
                    return
                try:
                    self.child = subprocess.Popen(
                        [str(py), str(script), "start", "--foreground"],
                        stdin=subprocess.DEVNULL, stdout=child_log,
                        stderr=child_log,
                        cwd=str(PROJECT_ROOT),
                        creationflags=_no_console_flags())
                except OSError as e:
                    log_state("FAIL", f"cannot start hass — {e}")
                    state["rc"] = 1
                    return
                while True:
                    rc = self.child.poll()
                    if rc is not None:
                        break
                    # Both signals are checked, not just the event: if SetEvent ever
                    # fails to reach this thread, depending on the event alone means
                    # waiting forever while the SCM shows RUNNING and refuses every
                    # control with 1061.  The flag is set by the control thread
                    # before it touches the child, so it is the cheaper witness.
                    if self.stopping or (win32event.WaitForSingleObject(
                            self.stop_event, 1000) == win32event.WAIT_OBJECT_0):
                        self._kill_child()
                        rc = 0
                        break
                log(f"service: hass exited with {self.child.returncode} "
                    f"(loop_rc={rc}, stopping={self.stopping})")
                if self.stopping or not rc:
                    # Neither a stop the user asked for nor a clean exit is a
                    # failure: returning reports SERVICE_STOPPED with 0 and the
                    # failure actions stay quiet, which is exactly what a home the
                    # user just stopped needs.
                    return
                if rc != HASS_RESTART_CODE:
                    break
                # hass asked to be restarted — `homeassistant.restart`, the UI's
                # Restart button, and the update flow all exit with this code and
                # expect their supervisor to bring them back.  Respawning here
                # instead of handing the code to the SCM is the difference
                # between "down for the whole failure-action delay, and the
                # service recorded as failed" and "back in seconds with the
                # service never leaving RUNNING".  Measured on this machine: the
                # SCM path took 10s of delay plus a 20s cold start, and left the
                # service at STOPPED until the action fired.
                #
                # The kill latch belongs to one pass and is rearmed, or a later
                # `stop` finds it already spent, skips its own kill and only
                # waits — the second half of the same race the latch exists for.
                log(f"service: hass asked to restart (exit {rc}) — "
                    "respawning it, the service stays up")
                self.killed = False
                self.kill_done.clear()
            # hass died on its own with a non-zero code, so the SCM has to see
            # a failure or it will not restart anything.  Returning normally
            # reports STOPPED with exit code 0, i.e. "stopped on purpose" —
            # measured on this machine: flags=True, 3x RESTART/10s configured,
            # and the service still sat at (STOPPED, dwWin32ExitCode=0) for
            # minutes after hass was killed.  The failure *actions* only fire
            # when the exit code is non-zero, which is the one thing
            # FailureActionsOnNonCrashFailures is about.
            try:
                self.ReportServiceStatus(
                    win32service.SERVICE_STOPPED,
                    win32ExitCode=WIN_ERROR_SERVICE_SPECIFIC,
                    svcExitCode=rc)
            except Exception as e:
                log_state("FAIL", f"service: cannot report the failure — {e}")
            # os._exit rather than return: pywin32's dispatcher reports STOPPED
            # one more time, with 0, as soon as SvcDoRun returns, which would
            # overwrite the code just reported.  Flush first — os._exit skips
            # every buffer flush there is, and the line above is the evidence
            # the next start needs.
            try:
                sys.stdout.flush()
            except Exception:
                pass
            os._exit(rc)

    try:
        servicemanager.Initialize()
        servicemanager.PrepareToHostSingle(_HomeAnt)
        servicemanager.StartServiceCtrlDispatcher()
    except Exception as e:
        log_state("FAIL", f"cannot talk to the service manager — {e}")
        return 1
    return state["rc"]


# ── config deployment ─────────────────────────────────────────────────────────

_CONFIG_DIR = PROJECT_ROOT / "config"

# Files whose top-level keys are seed-owned: a template entry REPLACES the same
# key in the deployed copy, a key the seed no longer ships is REMOVED (via the
# .seed-keys.json snapshot), while keys the seed never owned (UI-created
# entries) are kept.
#
# scripts.yaml: keys are script IDs, and a script's `sequence` is an ordered
# action chain — merging it item-wise appends new steps to a stale chain instead
# of replacing it, which corrupts the script. Replacing the file wholesale is
# not an option either: HA's script UI (components/config/script.py,
# EditKeyBasedConfigView) rewrites the whole file, so any script created in the
# UI lives in the same mapping and would be dropped.
_SEED_ENTRY_REPLACE_FILES = {"scripts.yaml"}

# Files where the seed owns only the *presence* of its keys, never their values.
# The merge stays add-only (configuration.yaml is user-owned and hand-editable,
# so a template value must not overwrite what the user wrote there), but a
# top-level key the seed shipped last release and no longer ships is a deletion,
# not user content — leaving it behind keeps an integration the release retired.
#
# Deliberately NOT merged into the set above: replacement there is per top-level
# key, and configuration.yaml's top-level keys are aggregates (input_select:
# holds the seed's dropdowns *and* the user's), so replacing one would take the
# user's entries with it.
_SEED_ENTRY_OWNED_FILES = _SEED_ENTRY_REPLACE_FILES | {"configuration.yaml"}


def _seed_keys_path(dst_path: Path) -> Path:
    """Per-directory snapshot of the top-level keys the seed used to own.

    Beside the deployed file on purpose, not in HA_ROOT and not in
    ``.seed-state``: a source-tree ``--reinstall`` drops ``.seed-state`` but
    leaves this file, so the deploy that follows still knows which keys the
    *previous* release shipped and can tell a removed script from a script the
    user created in HA's UI.  Deriving it from ``dst_path`` also keeps tests
    that rebase HA_ROOT from writing into the real home.
    """
    return dst_path.parent / ".seed-keys.json"


def _read_seed_keys(dst_path: Path) -> dict:
    try:
        data = json.loads(_seed_keys_path(dst_path).read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def _write_seed_keys(tpl_path: Path, dst_path: Path) -> None:
    """Record this release's top-level keys, so the next deploy can remove stale ones.

    ``yaml.compose`` rather than ``safe_load``: ``configuration.yaml`` carries
    ``!include`` and cannot be constructed, yet its key set is all the snapshot
    needs — compose resolves tags without building anything.
    """
    try:
        import yaml
        root = yaml.compose(tpl_path.read_text(encoding="utf-8"),
                            Loader=yaml.SafeLoader)
    except Exception:  # unreadable or unparsable: leave the prior snapshot alone
        return
    keys = sorted(_yaml_mapping_keys(root))
    if not keys:
        return
    snapshot = _read_seed_keys(dst_path)
    snapshot[tpl_path.name] = keys
    try:
        _seed_keys_path(dst_path).write_text(
            json.dumps(snapshot, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    except OSError as e:
        log(f"  seed keys snapshot skipped ({tpl_path.name}: {e})")


def _drop_stale_seed_keys(tpl_path: Path, dst_path: Path, tpl: dict,
                          cur: dict) -> bool:
    """Delete top-level keys the seed owned last release and no longer ships.

    Only for ``_SEED_ENTRY_OWNED_FILES``, and only keys the *snapshot* says the
    seed shipped: a key the user created was never in it, which is what makes
    this safe on a file the user owns.  Mutates ``cur``; True if anything went.
    """
    if tpl_path.name not in _SEED_ENTRY_OWNED_FILES:
        return False
    dropped = False
    for key in _read_seed_keys(dst_path).get(tpl_path.name, []):
        if key in cur and key not in tpl:
            del cur[key]
            log(f"  {dst_path.name}: removed seed entry '{key}'")
            dropped = True
    return dropped


def _deep_merge_dict(tpl: dict, cur: dict) -> dict:
    """Recursive merge: add template keys missing in cur, never overwrite.

    - dict in both → recurse into children
    - list in both → de-duplicate merge (by dict identity or element equality)
    - scalar/list in cur only → keep cur (user wins)
    - key only in tpl → add from tpl

    A bare ``key:`` parses as ``None`` and is carried through untouched: HA
    itself rewrites every top-level ``None`` to ``{}`` while loading the config
    (homeassistant/config.py, load_yaml_config_file), so normalising it here
    would only make two equivalent files compare as different and force a
    pointless rewrite of the deployed copy.
    """
    result = dict(cur)
    for k, tv in tpl.items():
        if k not in result:
            result[k] = tv
        elif isinstance(tv, dict) and isinstance(result[k], dict):
            result[k] = _deep_merge_dict(tv, result[k])
        elif isinstance(tv, list) and isinstance(result[k], list):
            result[k] = _merge_lists(tv, result[k])
        # else: cur has scalar/list/None, leave as-is
    return result


def _dict_id_key(d: dict) -> tuple | None:
    """Return a best-effort identity key for a dict element in a list.

    Recognises common ID field patterns used by HA storage files:
      - issues:         (domain, issue_id)
      - entries/devices: id / entry_id / device_id
      - areas:          area_id / name
    Returns None if no known ID fields found — caller falls back to full-content compare.
    """
    if "domain" in d and "issue_id" in d:
        return ("domain", "issue_id", d["domain"], d["issue_id"])
    if "id" in d:
        return ("id", d["id"])
    if "entry_id" in d:
        return ("entry_id", d["entry_id"])
    if "device_id" in d:
        return ("device_id", d["device_id"])
    if "area_id" in d:
        return ("area_id", d["area_id"])
    return None


def _freeze(value):
    """Hashable full-content key for list de-duplication.

    YAML/JSON elements nest arbitrarily (an action's ``if: then: - service:``
    chain), so ``frozenset(d.items())`` raises TypeError on any dict or list
    value. Freeze recursively instead: dicts become key-sorted tuples, lists
    become tuples, scalars pass through.
    """
    if isinstance(value, dict):
        return ("dict", tuple(sorted(((k, _freeze(v)) for k, v in value.items()),
                                     key=lambda kv: str(kv[0]))))
    if isinstance(value, (list, tuple)):
        return ("list", tuple(_freeze(v) for v in value))
    try:
        hash(value)
    except TypeError:
        return ("repr", repr(value))
    return ("scalar", value)


def _merge_lists(tpl: list, cur: list) -> list:
    """Merge two lists: keep all cur items, append tpl items not already present.

    For lists of dicts with recognisable ID fields (domain+issue_id, id, etc.),
    de-duplicate by that identity key so user's entry wins over template.
    For scalar lists or unknown dict shapes, de-dup by full value/content.
    """
    if not cur:
        return list(tpl)
    if not tpl:
        return list(cur)

    # Detect if we're merging dicts with a known identity key
    first_cur = cur[0]
    if isinstance(first_cur, dict):
        id_key = _dict_id_key(first_cur)
        if id_key is not None:
            # Build set of existing identity keys from cur
            cur_keys = {_dict_id_key(c) for c in cur
                        if isinstance(c, dict) and _dict_id_key(c) is not None}
            merged = list(cur)
            for t_item in tpl:
                if isinstance(t_item, dict):
                    tk = _dict_id_key(t_item)
                    if tk is not None and tk not in cur_keys:
                        merged.append(t_item)
                        cur_keys.add(tk)
            return merged

    # Fallback: scalar lists or unknown dict shapes → full-content dedup
    merged = list(cur)
    cur_frozen = {_freeze(c) for c in cur}
    for t_item in tpl:
        frozen = _freeze(t_item)
        if frozen not in cur_frozen:
            merged.append(t_item)
            cur_frozen.add(frozen)
    return merged


# Whole values a release shipped as defects, keyed by their exact text.  The
# list merge only appends, so a line already on disk is never revisited: a
# defect that shipped once stays in every existing install for good — the
# deployed automations.yaml still carried the always-false speaker trigger
# long after the release that fixed it.
#
# Matching is per line and per whole value on purpose.  The same expression is
# legitimate inside `variables:`, where it feeds the action instead of driving
# a trigger, and a file-wide text replace would break that one too.
_KNOWN_VALUE_REPAIRS: tuple[tuple[str, str], ...] = (
    (
        "{{ states.notify | map(attribute='entity_id')"
        " | select('search', '_play_text_a_') | list }}",
        "{{ (states.notify | map(attribute='entity_id')"
        " | select('search', '_play_text_a_') | list) != "
        "(state_attr('input_select.homeant_voice_speaker', 'options')"
        " | reject('eq', 'unset') | list) }}",
    ),
)


def _repair_known_values(text: str) -> tuple[str, int]:
    """Rewrite whole YAML values that shipped broken.  Returns (text, count).

    Only a line whose entire value equals a known-bad string is touched, and
    its indentation is kept, so the line stays exactly where the user's file
    has it.  Comments, ordering and spacing elsewhere are left byte for byte:
    this file may be hand-written, and HA rewrites it from its own model when
    the user edits an automation.
    """
    lines: list[str] = []
    edits = 0
    for raw in text.splitlines(keepends=True):
        body = raw.rstrip("\r\n")
        ending = raw[len(body):]
        stripped = body.strip()
        for bad, good in _KNOWN_VALUE_REPAIRS:
            matched = False
            for quote in ('"', "'", ""):
                if stripped == f"value_template: {quote}{bad}{quote}":
                    indent = body[: len(body) - len(body.lstrip())]
                    body = f'{indent}value_template: "{good}"'
                    edits += 1
                    matched = True
                    break
            if matched:
                break
        lines.append(body + ending)
    return "".join(lines), edits


def _merge_list_root(tpl_path: Path, dst_path: Path, tpl: list, cur: list,
                     tpl_text: str, dst_text: str) -> bool:
    """Append the list elements a newer release added; keep everything else.

    ``automations.yaml`` (and anything else with a top-level list) has no keys to
    fill in, so the dict merge had nothing to say and returned False: the
    deployed copy kept exactly the content of the release that first created it,
    and every automation added later reached fresh installs only.  Neither side
    reported anything, which is what made it survive several releases.

    Two decisions worth naming:

    * append to the file, do not re-serialise it.  This is a file the user may
      have written by hand, and ``yaml.safe_dump`` would drop its comments; the
      new entries are dumped as list items and spliced on at the end, so every
      byte already on disk survives.  The composed text is parsed again before
      writing and dropped if it does not load.
    * identity comes from ``_merge_lists`` — ``id`` when present, content
      otherwise.  That is what makes a second run a no-op, which matters because
      an upgrade may deploy on every start.

    The first write leaves ``<name>.bak`` behind, once: on a later merge that
    copy no longer holds the user's original, so overwriting it would destroy
    the only pre-merge state there is.
    """
    merged = _merge_lists(tpl, cur)
    added = merged[len(cur):]

    import yaml

    # Repairs come first and are independent of `added`: the whole point is the
    # case where nothing is new, because the element is already there — only
    # its value is the one that shipped broken.
    text, repaired = _repair_known_values(dst_text)
    if repaired:
        try:
            yaml.safe_load(text)
        except yaml.YAMLError as e:
            log(f"  repair skipped (repaired yaml unparsable: {e})")
            text, repaired = dst_text, 0
    if not added and not repaired:
        return False

    if added:
        blocks = [
            yaml.safe_dump([item], allow_unicode=True, sort_keys=False,
                           default_flow_style=False).rstrip("\n")
            for item in added
        ]
        if text and not text.endswith("\n"):
            text += "\n"
        text += "\n".join(blocks) + "\n"

    try:
        check = yaml.safe_load(text)
    except yaml.YAMLError as e:
        log(f"  merge skipped (merged yaml unparsable: {e})")
        return False
    if not isinstance(check, list) or len(check) != len(cur) + len(added):
        log("  merge skipped (list did not grow as expected)")
        return False

    original = dst_path.read_bytes()
    bak = dst_path.with_name(dst_path.name + ".bak")
    try:
        if not bak.exists():
            bak.write_bytes(original)
        dst_path.write_text(text, encoding="utf-8")
    except OSError as e:
        log(f"  merge skipped (write failed: {e})")
        try:
            dst_path.write_bytes(original)   # do not leave a half-written file
        except OSError:
            pass
        return False
    return True


def _merge_file(tpl_path: Path, dst_path: Path) -> bool:
    """Merge template file into dst. Auto-detect format (.yaml / .json).

    Merge rules:
      - keys missing in dst are added from the template; existing values win
      - HA storage entries present in both adopt the template: on entry_id
        match the data dict is replaced; on a unique-domain match the whole
        entry is (id included), so the merge de-duplicates instead of
        appending — the sole overwrite path, for seed entries whose *values*
        changed (mcp_server) on an already-initialized install; skipped while
        hass is running (HA rewrites these files from memory on shutdown)
      - YAML carrying custom tags (!include & co.) is merged at text level by
        _merge_file_tags — safe_load cannot construct those tags
      - files in _SEED_ENTRY_REPLACE_FILES replace per top-level key instead
        (see the constants): seed-owned entries follow the template, a key the
        seed dropped is removed via .seed-keys.json, and deployed-only entries
        (never owned by the seed) survive
      - files in _SEED_ENTRY_OWNED_FILES get that same stale-key removal while
        keeping the add-only merge: configuration.yaml holds seed keys beside
        the user's own, so a template value must never replace one of theirs

    Returns True if dst was written (something new was merged in).
    """
    if not dst_path.exists():
        return False  # nothing to merge into (fresh files are copied, not merged)
    suffix = tpl_path.suffix.lower()
    is_yaml = suffix in (".yaml", ".yml")
    is_json = suffix == ".json" or suffix == "" \
        or ".storage" in (tpl_path.parent.name, dst_path.parent.name)
    if not (is_yaml or is_json):
        return False  # unknown format

    if is_yaml:
        import yaml
        tpl_text = tpl_path.read_text(encoding="utf-8")
        dst_text = dst_path.read_text(encoding="utf-8")
        try:
            tpl = yaml.safe_load(tpl_text) or {}
            cur = yaml.safe_load(dst_text) or {}
        except yaml.YAMLError:
            # Custom tags (!include / !secret / !include_dir_*) are not
            # constructible by safe_load. Skipping those files is what kept
            # deployed configs from ever picking up new keys — merge at text
            # level instead.
            return _merge_file_tags(tpl_text, dst_text, tpl_path, dst_path)
    else:
        # HA storage files are JSON: no suffix (auth) or dotted core.*
        # naming under .storage/ (core.config_entries)
        try:
            tpl = json.loads(tpl_path.read_text(encoding="utf-8"))
            cur = json.loads(dst_path.read_text(encoding="utf-8"))
        except Exception as e:
            log(f"  merge skipped (parse error: {e})")
            return False

    if isinstance(tpl, list) and isinstance(cur, list):
        # A list root has no keys to fill in — it needs element identity, which
        # is why the dict merge below could only ever say "nothing to do".
        if not is_yaml:
            return False   # no seed ships a JSON list root; nothing to merge
        return _merge_list_root(tpl_path, dst_path, tpl, cur, tpl_text, dst_text)

    if not isinstance(tpl, dict) or not isinstance(cur, dict):
        return False

    entries_synced = _sync_storage_entries(tpl, cur)
    # Keys the last release shipped but this one no longer does are a deletion,
    # not user content.  Without the snapshot they survive forever as zombie
    # entities; with it, only keys the seed never owned are preserved.  The
    # snapshot is beside dst so a source-tree `--reinstall` (which drops
    # .seed-state but not it) keeps working.
    pruned = _drop_stale_seed_keys(tpl_path, dst_path, tpl, cur)
    if tpl_path.name in _SEED_ENTRY_REPLACE_FILES:
        replaced = False
        for key, val in tpl.items():
            if key not in cur or cur[key] != val:
                cur[key] = val  # seed-owned entry: template wins over deployed
                log(f"  {dst_path.name}: seed entry '{key}' adopted")
                replaced = True
        if not replaced and not entries_synced and not pruned:
            return False  # deployed already matches the seed
        merged = cur
    else:
        merged = _deep_merge_dict(tpl, cur)
        if merged == cur and not entries_synced and not pruned:
            return False  # nothing new to add

    # Write back
    dst_path.parent.mkdir(parents=True, exist_ok=True)
    if is_yaml:
        if (tpl_path.name in _SEED_ENTRY_REPLACE_FILES
                and set(cur) <= set(tpl)):
            # Nothing deployed-only to preserve → adopt the seed file verbatim
            # so its comments and formatting survive (safe_dump drops both).
            dst_path.write_bytes(tpl_path.read_bytes())
            return True
        import yaml
        dst_path.write_text(
            yaml.safe_dump(merged, allow_unicode=True, sort_keys=False),
            encoding="utf-8",
        )
    else:
        dst_path.write_text(
            json.dumps(merged, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )
    return True


def _merge_file_tags(tpl_text: str, dst_text: str, tpl_path: Path,
                     dst_path: Path) -> bool:
    """Key-level merge for YAML carrying custom tags (!include / !secret ...).

    ``yaml.safe_load`` cannot construct custom tags, so include-bearing
    configs used to fall through as "parse error" and silently never picked
    up new template keys (a deployed configuration.yaml kept its old content
    forever). Re-serialising the loaded dict is not an option either: dumping
    would inline every ``!include`` target and destroy the wiring that lets
    the UI own scenes.yaml / automations.yaml.

    So only the *text* of each missing template key is spliced into dst
    (indentation-adjusted, nested mappings recursed into), leaving the rest
    of the file byte-identical. The result is re-composed before writing and
    dropped if the top-level keys still do not all show up.

    Removal is the same text-level surgery in the other direction: a top-level
    key the snapshot says the seed shipped, which this template no longer has,
    is cut out by line span.  Add-only was not enough — a retired integration
    kept its key (and stayed enabled) in every deployed copy.

    Returns True if dst was written.
    """
    import yaml

    try:
        tpl_root = yaml.compose(tpl_text, Loader=yaml.SafeLoader)
        dst_root = yaml.compose(dst_text, Loader=yaml.SafeLoader)
    except yaml.YAMLError as e:
        log(f"  merge skipped (parse error: {e})")
        return False

    if not isinstance(tpl_root, yaml.MappingNode):
        return False  # only mapping-shaped configs can be key-merged
    if dst_root is None:  # empty dst adopts the template verbatim
        dst_path.write_text(tpl_text, encoding="utf-8")
        return True
    if not isinstance(dst_root, yaml.MappingNode):
        return False

    edits: list[tuple[int, list[str]]] = []
    _collect_yaml_inserts(tpl_text.splitlines(), tpl_root, dst_root, 0, edits)

    removals: list[tuple[int, int, str]] = []
    if tpl_path.name in _SEED_ENTRY_OWNED_FILES:
        removals = _collect_yaml_removals(
            dst_root, _yaml_mapping_keys(tpl_root),
            _read_seed_keys(dst_path).get(tpl_path.name, []),
        )
    if not edits and not removals:
        return False  # dst already has every template key

    # One pass, last line first: a splice at a higher line number can never
    # shift an anchor below it.
    ops = ([(start, "del", end) for start, end, _ in removals]
           + [(line, "ins", block) for line, block in edits])
    merged = dst_text.splitlines()
    for line, kind, payload in sorted(ops, key=lambda op: op[0], reverse=True):
        if kind == "del":
            del merged[line:payload + 1]
        else:
            merged[line + 1:line + 1] = payload
    merged_text = "\n".join(merged) + "\n"

    try:
        check = yaml.compose(merged_text, Loader=yaml.SafeLoader)
    except yaml.YAMLError as e:
        log(f"  merge skipped (merged yaml unparsable: {e})")
        return False
    check_keys = _yaml_mapping_keys(check)
    if not _yaml_mapping_keys(tpl_root) <= check_keys:
        log("  merge skipped (keys still missing after splice)")
        return False
    stale = sorted(name for _, _, name in removals if name in check_keys)
    if stale:
        log(f"  merge skipped (seed key survived removal: {stale})")
        return False

    dst_path.parent.mkdir(parents=True, exist_ok=True)
    dst_path.write_text(merged_text, encoding="utf-8")
    return True


def _collect_yaml_inserts(tpl_lines: list[str], tpl_map, dst_map,
                          indent: int, edits: list) -> None:
    """Queue text insertions for template keys absent from dst_map.

    ``indent`` is the column dst_map's children sit at; template blocks are
    shifted by the difference so they land at the right depth.
    """
    import yaml

    dst_children: dict[str, object] = {}
    for k, v in dst_map.value:
        if isinstance(k, yaml.ScalarNode):
            dst_children.setdefault(k.value, v)

    missing = []
    nested = []
    for tk, tv in tpl_map.value:
        if not isinstance(tk, yaml.ScalarNode):
            continue
        dv = dst_children.get(tk.value)
        if dv is None:
            missing.append((tk, tv))
        elif (isinstance(tv, yaml.MappingNode) and not tv.flow_style
              and isinstance(dv, yaml.MappingNode) and not dv.flow_style):
            nested.append((tv, dv))

    if missing:
        anchor = _yaml_insert_anchor(dst_map)
        delta = indent - missing[0][0].start_mark.column
        if anchor is not None and delta >= 0:
            block: list[str] = []
            for tk, tv in missing:
                piece = _yaml_slice(tpl_lines, tk, tv, delta)
                if not piece:
                    continue
                if block and indent == 0:
                    block.append("")  # blank line between new top-level keys
                block += piece
            if block:
                if indent == 0:
                    block.insert(0, "")  # blank line before the new section
                edits.append((anchor, block))

    for tv, dv in nested:
        child_indent = _yaml_child_indent(dv)
        if child_indent is not None:
            _collect_yaml_inserts(tpl_lines, tv, dv, child_indent, edits)


def _yaml_insert_anchor(map_node) -> int | None:
    """Line index after which a new sibling key can be spliced in."""
    if not map_node.value or map_node.flow_style:
        return None  # empty or flow mapping: no block anchor
    key, value = map_node.value[-1]
    end = value.end_mark
    if end.column == 0 and end.line > key.start_mark.line:
        return end.line - 1  # end mark already points past the content
    return end.line


def _yaml_child_indent(map_node) -> int | None:
    """Column of map_node's children (None when it has none)."""
    if not map_node.value:
        return None
    return map_node.value[0][0].start_mark.column


def _yaml_slice(tpl_lines: list[str], key_node, val_node, delta: int) -> list[str]:
    """Raw text of one template key/value pair, shifted by ``delta`` columns."""
    start = key_node.start_mark.line
    end = val_node.end_mark.line
    if val_node.end_mark.column == 0 and end > start:
        end -= 1
    out: list[str] = []
    for line in tpl_lines[start:end + 1]:
        if not line.strip():
            out.append("")
        elif delta > 0:
            out.append(" " * delta + line)
        elif delta < 0:
            if line[:-delta].strip():
                return []  # cannot de-indent safely: skip this insertion
            out.append(line[-delta:])
        else:
            out.append(line)
    return out


def _yaml_node_last_line(node) -> int:
    """Last line index a node occupies.

    A block collection's end_mark sits at column 0 of the line *after* its last
    content line (same rule ``_yaml_insert_anchor`` relies on); a scalar ends on
    its own line.
    """
    end = node.end_mark
    if end.column == 0 and end.line > node.start_mark.line:
        return end.line - 1
    return end.line


def _collect_yaml_removals(dst_root, tpl_keys: set[str],
                           owned_keys) -> list[tuple[int, int, str]]:
    """Line spans of top-level keys the seed dropped, as (first, last, name).

    A key goes only when the snapshot says the seed shipped it *and* this
    template no longer has it — a key the user wrote was never in the snapshot,
    so it cannot land here.  The span covers the key's line through the last
    line of its value, so a nested block goes with it.
    """
    import yaml

    if not isinstance(dst_root, yaml.MappingNode):
        return []
    owned = set(owned_keys)
    spans: list[tuple[int, int, str]] = []
    for key_node, val_node in dst_root.value:
        if not isinstance(key_node, yaml.ScalarNode):
            continue
        name = key_node.value
        if name in tpl_keys or name not in owned:
            continue
        spans.append((key_node.start_mark.line,
                      _yaml_node_last_line(val_node), name))
    return spans


def _yaml_mapping_keys(node) -> set[str]:
    import yaml

    if not isinstance(node, yaml.MappingNode):
        return set()
    return {k.value for k, _ in node.value if isinstance(k, yaml.ScalarNode)}


def _sync_storage_entries(tpl: dict, cur: dict) -> bool:
    """Reconcile HA storage entries with the template (in place on cur).

    _deep_merge_dict never overwrites existing values, so an install whose
    storage entry predates a seed value change (mcp_server) would keep stale
    data forever. Runs before the merge, pairing template entries against the
    pre-merge runtime state:

      - entry_id match                  → runtime entry adopts the seed data
      - else unique domain on both sides → runtime entry adopts the seed entry
        wholesale (data + entry_id), so the merge de-duplicates by id instead
        of appending a second entry for the same domain

    Only safe while hass is not running: HA holds entries in memory and
    rewrites these files on shutdown.
    """
    tpl_data = tpl.get("data")
    cur_data = cur.get("data")
    if not isinstance(tpl_data, dict) or not isinstance(cur_data, dict):
        return False
    tpl_entries = [e for e in tpl_data.get("entries", []) if isinstance(e, dict)]
    cur_entries = cur_data.get("entries")
    if not tpl_entries or not isinstance(cur_entries, list):
        return False

    pairs = []
    for te in tpl_entries:
        hit = next((e for e in cur_entries
                    if isinstance(e, dict)
                    and e.get("entry_id") == te.get("entry_id")), None)
        if hit is None:
            same = [e for e in cur_entries
                    if isinstance(e, dict)
                    and e.get("domain") == te.get("domain")]
            if len(same) != 1:
                continue  # absent (merge deploys it) or ambiguous (leave alone)
            pairs.append((same[0], te, True))
        elif hit.get("data") != te.get("data"):
            pairs.append((hit, te, False))
    if not pairs:
        return False

    if _ha_instance() or _hass_via_service():
        # Rewriting a live instance's .storage is undone by its next flush, and
        # `_hass_via_service()` covers the case where the lock is gone and no
        # pid can be named: the home is up either way.
        return False
    for hit, te, wholesale in pairs:
        if wholesale:
            hit.clear()
            hit.update(te)
        else:
            hit["data"] = te.get("data", {})
    return True


def _deploy_config_files() -> None:
    """Walk config/ dir, copy or merge each file into HA_ROOT.

    Rules per file:
      - dst missing  → copy template
      - dst exists   → _merge_file (add missing keys; HA storage entries synced)
    """
    import shutil as _shutil

    if not _CONFIG_DIR.exists():
        return

    # Snapshot which domains are missing *before* copying.  A domain that is
    # already there is only merged -- _merge_file never rewrites a .py -- so
    # reporting it as "installed" would claim an update that did not happen.
    # This uses the same is_dir() test as _seed_ready(); a redeploy removes the
    # domains first, which is when all of them are genuinely new.
    cc_src = _CONFIG_DIR / "custom_components"
    cc_dst = HA_ROOT / "custom_components"
    new_domains = []
    if cc_src.is_dir():
        for d in sorted(cc_src.iterdir()):
            if d.is_dir() and not d.name.startswith("_") \
                    and not (cc_dst / d.name).is_dir():
                new_domains.append(d.name)

    # config/runtime/ is not HA configuration: it holds the Windows importer shim
    # that hass loads through PYTHONPATH=<program tree>/config/runtime, so a copy
    # under HA_ROOT would never be read.  It would also go stale forever, because
    # _merge_file never rewrites a .py -- the deployed copy had
    # already diverged from the tree it is supposed to mirror.
    runtime_dir = _CONFIG_DIR / "runtime"

    for tpl in _CONFIG_DIR.rglob("*"):
        if not tpl.is_file():
            continue
        if runtime_dir in tpl.parents:
            continue

        rel = tpl.relative_to(_CONFIG_DIR)
        dst = HA_ROOT / rel

        if not dst.exists():
            dst.parent.mkdir(parents=True, exist_ok=True)
            _shutil.copy(tpl, dst)
        else:
            _merge_file(tpl, dst)

    # Record what this release owns *after* merging, so the next release can
    # tell its removed keys apart from scripts the user added in HA's UI.
    # A fresh copy writes the snapshot too; there is nothing to remove yet.
    for name in _SEED_ENTRY_OWNED_FILES:
        tpl = _CONFIG_DIR / name
        dst = HA_ROOT / name
        if tpl.is_file() and dst.is_file():
            _write_seed_keys(tpl, dst)

    log(f"deploying config → {_home_tilde(HA_ROOT)}")
    # _install_custom_components() reports one line per vendored domain; mirror
    # that here so a redeploy that removed three domains shows three coming back
    # instead of one.
    for name in new_domains:
        log(f"installed custom_components/{name}")


# ── seed gate: deploy once per seed fingerprint ────────────────────────────

def _seed_digest() -> str | None:
    """sha256 over config/ — every path plus its bytes, in sorted order.

    The fingerprint is the *input* (what this release ships), never "when did we
    last run": a version bump that changes a seed file deploys, a bump that does
    not, does not.  Byte comparison also means an edit to a seed that ships the
    same content as the last release is not mistaken for a change.
    """
    import hashlib

    if not _CONFIG_DIR.is_dir():
        return None
    h = hashlib.sha256()
    for p in sorted(_CONFIG_DIR.rglob("*")):
        if not p.is_file() or "__pycache__" in p.parts or p.suffix == ".pyc":
            continue
        h.update(p.relative_to(_CONFIG_DIR).as_posix().encode("utf-8"))
        h.update(b"\0")
        h.update(p.read_bytes())
        h.update(b"\0")
    return h.hexdigest()


def _seed_marker() -> dict:
    """Read .seed-state as a dict; anything unreadable reads as "no marker"."""
    try:
        d = json.loads(SEED_MARKER.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _seed_ready() -> bool:
    """True when the deployed seed matches the one this release ships.

    Also checks that the integrations landed: they are copied into HA_ROOT by
    ``_deploy_config_files`` (from ``config/custom_components``) and
    ``_install_custom_components`` (from ``vendor/``), so the ``config/``
    fingerprint covers neither — it hashes what the release ships, not what the
    machine holds.  Deleting ``~/.homeant/custom_components/<domain>`` would
    otherwise leave the fingerprint intact while the integration silently
    stopped existing: the gate said "satisfied", ``_ensure_seed`` returned
    early, HA booted without it and every line of output read like success.

    Both sources are checked by the same loop on purpose.  Only the vendored one
    was guarded before, and that asymmetry is exactly how the shipped domains
    stayed missing — a hand-kept second list would drift the same way a second
    copy of any rule does.
    """
    seed = _seed_digest()
    if not seed or _seed_marker().get("seed") != seed:
        return False
    for cc_src in (
        PROJECT_ROOT / "vendor" / "ha_xiaomi_home" / "custom_components",
        _CONFIG_DIR / "custom_components",
    ):
        if not cc_src.is_dir():
            continue
        for d in cc_src.iterdir():
            if d.is_dir() and not d.name.startswith("_") \
                    and not (HA_ROOT / "custom_components" / d.name).is_dir():
                return False
    return True


def _seed_present() -> bool:
    """True when configuration.yaml — the seed's marker file — is on disk.

    Deliberately weaker than ``_seed_ready``: this answers "was this tree
    deleted", not "is the deployed copy current".  A new release changes the
    fingerprint, and treating that as "missing" would turn every `start` on a
    healthy running instance into a restart — the idempotency this command
    promises.  configuration.yaml is the marker because _ensure_seed always
    writes it and merely merges the rest.

    Both `status` (reports it) and `start` (recovers from it) ask this one
    question, so the two commands cannot disagree about the state of the tree.
    """
    return (HA_ROOT / "configuration.yaml").exists()


def _write_seed_marker() -> None:
    """Record the fingerprint of what was deployed.

    ``seed`` is the only field read back (by ``_seed_ready``), so the marker
    carries nothing else — a timestamp or a host name would be write-only.
    """
    SEED_MARKER.write_text(
        json.dumps({"seed": _seed_digest()}), encoding="utf-8")


def _install_custom_components() -> None:
    """Copy vendored integrations into HA_ROOT/custom_components.

    config/custom_components/ is deployed separately by _deploy_config_files();
    this one only covers what ships under vendor/.
    """
    import shutil as _shutil

    cc_src = PROJECT_ROOT / "vendor" / "ha_xiaomi_home" / "custom_components"
    cc_dst = HA_ROOT / "custom_components"
    if not cc_src.exists():
        return
    cc_dst.mkdir(parents=True, exist_ok=True)
    for domain in cc_src.iterdir():
        if domain.is_dir() and not domain.name.startswith("_"):
            _shutil.copytree(domain, cc_dst / domain.name, dirs_exist_ok=True)
            log(f"installed custom_components/{domain.name}")


def _ensure_seed() -> None:
    """Deploy the repo seed if — and only if — the fingerprint says so.

    Satisfied means nothing happens, which is what keeps a hand-edited
    ~/.homeant/configuration.yaml alive across runs.  The whole body is
    copy-or-merge, so a partial deploy can never roll anything back.
    """
    if _seed_ready():
        # Installs that predate the key snapshot never re-run a deploy on a
        # healthy machine.  Bootstrap it here so the *next* release that drops
        # a script has something to compare against.  Never called on the
        # deploy path: there _deploy_config_files writes it after merging.
        for name in _SEED_ENTRY_OWNED_FILES:
            tpl = _CONFIG_DIR / name
            dst = HA_ROOT / name
            # Per file, not per snapshot: every owned file shares one
            # .seed-keys.json, so testing whether that file exists would
            # bootstrap whichever name came first and skip the rest.
            if tpl.is_file() and dst.is_file() \
                    and name not in _read_seed_keys(dst):
                _write_seed_keys(tpl, dst)
        return
    HA_ROOT.mkdir(parents=True, exist_ok=True)
    if _CONFIG_DIR.exists():
        _deploy_config_files()
    _install_custom_components()
    _write_seed_marker()


# ── version check ──────────────────────────────────────────────────────────


def _vtuple(v: str) -> tuple:
    """'0.1.0' -> (0, 1, 0). Non-numeric segments collapse to 0."""
    parts = [int(p) if p.isdigit() else 0 for p in v.split(".")]
    return tuple((parts + [0, 0, 0])[:3])


def _local_version() -> str | None:
    try:
        text = (PROJECT_ROOT / "pyproject.toml").read_text(encoding="utf-8")
    except OSError:
        return None
    m = re.search(r'(?m)^\s*version\s*=\s*"([^"]+)"', text)
    return m.group(1) if m else None


def _remote_version() -> str | None:
    """Latest released version, read off the online installer on the release
    host.

    The stamp INSTALLER_URL points at doubles as the version manifest — see the
    comment on that constant. Any failure is non-fatal: start must never block
    on this.
    """
    try:
        import urllib.request as _ur
        with _ur.urlopen(INSTALLER_URL, timeout=CONNECT_TIMEOUT) as resp:
            body = resp.read().decode("utf-8", "replace")
    except Exception:
        return None
    m = re.search(VERSION_RE, body)
    return m.group(1) if m else None


def _ask_update(version: str) -> bool:
    """Y/n prompt. Never updates unattended (no tty / piped stdin)."""
    try:
        if not sys.stdin or not sys.stdin.isatty():
            return False
        ans = input(f"[homeant] install {version} now? [Y/n] ").strip().lower()
    except (EOFError, KeyboardInterrupt):
        print()
        return False
    return ans in ("", "y", "yes")


def _local_installer() -> list[str] | None:
    """The installer copy that lives in a source tree, if this is one.

    A source tree is the one checkout whose `--upgrade` must not mean "download
    the release over it": it holds work that exists nowhere else.  The online
    installer cannot tell a checkout from an unpacked release — both are
    "a HomeAnt tree" with a version — so it would replace it.  The copy inside
    the tree is unstamped, and unstamped is exactly what turns the same flag
    into the other half of its meaning: redeploy the shipped components in
    place (stop → replace → start), never touching the sources.

    `.git` is the discriminator: the release zip contains none, and a copy
    stripped of it is not a tree anybody edits.
    """
    if not (PROJECT_ROOT / ".git").exists():
        return None
    script = PROJECT_ROOT / "scripts" / ("install.ps1" if IS_WIN else "install.sh")
    if not script.exists():
        return None
    if IS_WIN:
        return ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass",
                "-File", str(script), "--upgrade"]
    return ["sh", str(script), "--upgrade"]


def _run_installer(message: str) -> int:
    """Hand the work to the installer; return the child's exit code.

    One channel, three callers, and only the sentence they print differs: a
    newer release, a venv that no longer matches uv.lock, and `start
    --reinstall` all need the installer's download → stop → replace → uv sync →
    `start` sequence. So the sentence is the argument and the reason is the
    caller's to say — the body cannot tell the three apart, and therefore
    cannot drift into behaving differently for one of them.

    Nothing of that sequence is duplicated here — a second implementation is how
    an upgrade ends up behaving unlike a fresh install. In a source tree the
    hand-over goes to the copy living in that tree instead (`_local_installer`):
    the flag is the same, and there it means "redeploy what this tree ships",
    not "download over it". That branch says so itself, which is why `message`
    is unused there: "handing over to the online installer" would be a lie.

    There is also no
    fallback to "just start what is in memory": by the time the installer
    fails, the files under our feet may already be the new ones, so the honest
    answer is its exit code.

    Four decisions, each one measured before it landed here:
      * No stdio capture: the download progress redraws itself with \\r, so
        the child must own the real terminal or every frame becomes a line.
      * stdin is never the terminal: Windows passes DEVNULL, unix passes the
        fetched script to `sh -s`, so nothing down there can compete with the
        user for keystrokes.
      * unix feeds the script on stdin instead of `curl | sh`: a pipeline
        discards curl's exit status, so a 404 body would run as an empty
        script and report success.
      * Windows lets PowerShell fetch it, because `.Content` is a byte[] for
        `application/octet-stream` — the text has to be decoded explicitly
        from RawContentStream. `scriptblock::Create` then parses it before a
        single line runs, and `-ExecutionPolicy Bypass` is pointless:
        in-memory evaluation is not subject to it.
    """
    local = _local_installer()
    if local is not None:
        # The same request, a different transport: the released installer would
        # unpack the release over work that exists only here, while this tree's
        # own copy reads the flag as "make the deployment match these files".
        log("source tree — redeploying this tree in place ...")
        try:
            return subprocess.run(local, cwd=str(PROJECT_ROOT),
                                  stdin=subprocess.DEVNULL).returncode
        except OSError as e:
            log_red(f"update: cannot run the in-tree installer — {e}")
            return 1

    log(message)

    if IS_WIN:
        inner = (
            "$ProgressPreference='SilentlyContinue';"
            f"$r=Invoke-WebRequest -UseBasicParsing -Uri '{INSTALLER_URL}' -TimeoutSec {CONNECT_TIMEOUT};"
            "$s=[Text.Encoding]::UTF8.GetString($r.RawContentStream.ToArray());"
            "& ([scriptblock]::Create($s)) --upgrade"
        )
        argv = ["powershell", "-NoProfile", "-Command", inner]
        body = None
    else:
        import urllib.request as _ur

        try:
            with _ur.urlopen(INSTALLER_URL, timeout=CONNECT_TIMEOUT) as resp:
                body = resp.read()
        except Exception as e:
            log_red(f"update: cannot fetch the installer — {e}")
            return 1
        # same two checks install.sh makes on the script it fetches: a non-2xx
        # status raises above, and an empty body would otherwise run as a
        # successful no-op
        if not body.strip():
            log_red("update: the installer came back empty")
            return 1
        argv = ["sh", "-s", "--", "--upgrade"]

    try:
        if body is None:                    # Windows: PowerShell fetches it
            return subprocess.run(
                argv, cwd=str(PROJECT_ROOT), stdin=subprocess.DEVNULL).returncode
        # unix: the text we just fetched *is* stdin for `sh -s`
        return subprocess.run(
            argv, input=body, cwd=str(PROJECT_ROOT)).returncode
    except OSError as e:
        log_red(f"update: cannot run the installer — {e}")
        return 1


def _cfg_values(text: str) -> dict[str, str]:
    """KEY -> value, using load_cfg()'s own rules (skip blank / #, strip both)."""
    out: dict[str, str] = {}
    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith("#") or "=" not in s:
            continue
        k, v = s.split("=", 1)
        out[k.strip()] = v.strip()
    return out


def _cfg_new_keys_block(template_text: str, have: dict[str, str]) -> str:
    """Template lines for the keys the live file lacks, comments included.

    A bare ``KEY=value`` would leave the user guessing what the key does, and
    the template already documents every key right above it, so carry the
    comment block over with the key. The closing comment before the *next*
    key belongs to that key, not this one, which is why the buffer is reset
    both on a known key and on the first unknown one.

    The header block at the top describes the two files as a pair, not any
    single key, so it is skipped: iterating starts at the first real key.
    """
    lines = template_text.splitlines()
    start = next((i for i, line in enumerate(lines)
                  if line.strip() and not line.strip().startswith("#")
                  and "=" in line), len(lines))
    out: list[str] = []
    pending: list[str] = []
    for line in lines[start:]:
        s = line.strip()
        if not s or s.startswith("#"):
            pending.append(line)
            continue
        key = s.split("=", 1)[0].strip()
        if key in have:
            pending.clear()
            continue
        out.extend(pending)
        out.append(line)
        pending.clear()
    return "\n".join(out).strip("\n")


def _reconcile_cfg() -> None:
    """Bring homeant.cfg up to date with the shipped template.

    Additive only — it never rewrites a value the user already set:

      ① no live cfg      → copy the template (fresh install)
      ② nothing missing  → return without touching the file, mtime included
      ③ keys missing     → append those keys at the end, comments and all

    Rule ② is what makes this safe to call on every `start`: a no-op run must
    not look like a change, or every reinstall would show a modified config.
    Rule ③ is what lets a version bump add a key without resetting USERNAME /
    PASSWORD / per-machine paths.
    """
    if not CFG_TEMPLATE.is_file():
        return                       # release without a template: nothing to do
    import shutil as _shutil

    if not CONFIG_FILE.is_file():
        try:
            _shutil.copyfile(CFG_TEMPLATE, CONFIG_FILE)
            # copyfile() gives the new file the process umask - 0644 on a stock
            # Linux - and this file holds PASSWORD in clear text.  Windows has no
            # mode bits to set here (only the read-only flag) and cannot deny the
            # owner, so a refusal is swallowed rather than turned into a dead
            # install: an unreadable config would be the worse failure.
            try:
                os.chmod(CONFIG_FILE, 0o600)
            except OSError:
                pass
        except OSError as e:
            log_red(f"config: cannot create {CONFIG_FILE.name} — {e}")
            return
        log(f"config created from {CFG_TEMPLATE.name}")
        return

    # Same rule on every start, not only at creation: an install that predates
    # this line still carries a 0644 config, and rule ② returns without touching
    # the file at all - so the mode has to be asserted here, before the early
    # returns, or those installs would never converge.
    try:
        os.chmod(CONFIG_FILE, 0o600)
    except OSError:
        pass

    tpl_text = CFG_TEMPLATE.read_text(encoding="utf-8", errors="replace")
    # newline="" on the read as well as the write: read_text() would fold CRLF
    # into LF in memory, so the check below could never see a "\r\n" and a
    # CRLF config would come out with every line rewritten.
    with CONFIG_FILE.open("r", encoding="utf-8-sig", errors="replace", newline="") as fh:
        text = fh.read()
    have = _cfg_values(text)
    missing = [k for k in _cfg_values(tpl_text) if k not in have]
    if not missing:
        return

    block = _cfg_new_keys_block(tpl_text, have)
    if not block:
        return
    # Keep the file's own line endings: writing "\n" into a CRLF file (or the
    # reverse) rewrites every existing line, which is exactly the "diff noise
    # on a no-op upgrade" this function is supposed to avoid.
    nl = "\r\n" if "\r\n" in text else "\n"
    if text and not text.endswith(("\n", "\r")):
        text += nl
    text += nl + f"# --- keys added by this version (from {CFG_TEMPLATE.name}) ---" + nl
    text += block.replace("\n", nl) + nl
    try:
        with CONFIG_FILE.open("w", encoding="utf-8", newline="") as fh:
            fh.write(text)
    except OSError as e:
        log_red(f"config: cannot append to {CONFIG_FILE.name} — {e}")
        return
    log(f"config: added {len(missing)} key(s) to {CONFIG_FILE.name}: "
        f"{', '.join(missing)}")


# ── random credentials (admin + mqtt) ───────────────────────────────────────
# One alphabet for both passwords, with the five characters that get misread
# when someone retypes a password off a screen or a printout removed: 0/O and
# 1/l/I.  That leaves 57 characters, and 57**16 is about 2**93 — far past what
# a login form or an 1883 port needs, and short enough to type.
PW_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"
PW_LEN = 16


def _gen_password() -> str:
    """A fresh 16-character password.  Never derived from anything else."""
    import secrets

    return "".join(secrets.choice(PW_ALPHABET) for _ in range(PW_LEN))


def _cfg_set(key: str, value: str) -> bool:
    """Rewrite exactly one ``KEY=value`` line in the live config.

    Single-key on purpose: ``_reconcile_cfg`` owns *adding* keys and must stay
    the only writer of the file's shape, while a generated password has to land
    in the line that already exists.  Rewriting the whole file from memory would
    reformat comments and reorder nothing into something.

    The write is a temp file plus ``os.replace`` in the same directory, so a
    failure leaves the old config intact instead of a half-written one — this
    file holds every credential the home has.  Line endings are read and written
    with ``newline=""``: folding CRLF into LF would rewrite every other line.

    False means "this key is not in the file" — not an error, and never a
    reason to append: appending is ``_reconcile_cfg``'s job, and a key that is
    missing here means the caller ran before it.
    """
    try:
        with CONFIG_FILE.open("r", encoding="utf-8-sig", errors="replace", newline="") as fh:
            text = fh.read()
    except OSError:
        return False

    # The trailing \r is captured rather than matched: `$` in MULTILINE sits
    # before the \n, so a bare `[^\r\n]*$` would never match a CRLF file (the
    # \r blocks it) and a greedy `.*` would eat the \r and turn every rewritten
    # line into a mixed-ending file.
    pattern = re.compile(rf"(?m)^{re.escape(key)}=([^\r\n]*)(\r?)$")
    if not pattern.search(text):
        return False
    new_text = pattern.sub(lambda m: f"{key}={value}{m.group(2)}", text, count=1)
    if new_text == text:
        CFG[key] = value           # already correct; keep memory in step anyway
        return True

    tmp = CONFIG_FILE.with_name(CONFIG_FILE.name + ".tmp")
    try:
        with tmp.open("w", encoding="utf-8", newline="") as fh:
            fh.write(new_text)
        try:
            os.chmod(tmp, 0o600)
        except OSError:
            pass                    # Windows has no mode bits; the file is ours
        os.replace(tmp, CONFIG_FILE)
    except OSError as e:
        log_red(f"config: cannot write {key} to {CONFIG_FILE.name} — {e}")
        with contextlib.suppress(OSError):
            tmp.unlink()
        return False

    # The config is read once at start-up into CFG; without this the caller that
    # just generated the value would keep reading the empty one until the next
    # process.
    CFG[key] = value
    return True


def _check_newer_version() -> str | None:
    """Detect-only: return the version the user agreed to install, else None.

    Nothing is written here — a check stays a check until the answer is yes.
    This is the one place we deliberately differ from the installers: they
    never compare versions (running them *is* the install), while an already
    installed tree has to notice the newer release itself.
    """
    local, remote = _local_version(), _remote_version()
    if not local or not remote or _vtuple(remote) <= _vtuple(local):
        return None
    log(f"new version available: {remote} (you have {local})")
    if not _ask_update(remote):
        # Declining is a normal answer, not a failure — just say so and move on.
        log(f"staying on {local}")
        return None
    return remote


def _home_tilde(path: Path) -> str:
    """``~/.homeant`` for a path under this user's home, absolute otherwise.

    Display only, and only where a human reads it.  The tree *is* the home of
    whoever ran the command — ``HA_ROOT = Path.home() / ".homeant"`` — so the
    tilde cannot be ambiguous on that line, and it matches what the READMEs
    show.  Paths that name something about to be deleted keep ``str()``: an
    irreversible action gets no shorthand.
    """
    home = Path.home()
    if path == home:
        return "~"
    with contextlib.suppress(ValueError):
        return f"~/{path.relative_to(home).as_posix()}"
    return str(path)


def _tilde_text(text: str) -> str:
    """``_home_tilde`` for paths already baked into a sentence.

    Some lines carry more than a path: a command line quoted by the SCM, an
    ``old -> new`` pair, a sentence naming two files.  Rewriting the home prefix
    inside the finished string keeps those readable without splitting them into
    fragments — and it is the same rule the single-path form follows, so no line
    shows ``/home/<someone>`` or ``C:\\Users\\<someone>`` while another shows
    ``~``.  Both spellings are replaced because the same path reaches this
    process either way (measured: Git Bash hands over forward slashes).
    """
    home = str(Path.home())
    if home in ("", "/", "\\"):
        # A root home would rewrite every separator in the sentence; there is no
        # shorthand for "/" that makes a line readable either.
        return text
    for spelling in (home, home.replace(os.sep, "/"), home.replace(os.sep, "\\")):
        text = text.replace(spelling, "~")
    return text


# ── ownership: the sudo leftovers ────────────────────────────────────────────
#
# `sudo homeant start` is the one mistake this layer cannot undo by itself.
# Every file such a run creates under HA_ROOT belongs to root, and the *next*
# run as the real user fails somewhere far from the cause: HA answering 500 from
# a .storage it cannot write, a log file it cannot reopen, a pidfile whose
# rewrite raises, an installed component frozen at its old bytes.  None of those
# messages names root, and each one looks like a different bug.
#
# So the question is asked at the entry, where the answer is one `chown` away.
# Read-only on purpose: a root-owned tree is perfectly usable by root, and
# silently chowning a directory is not this layer's call to make.

_OWNERSHIP_MAX_ENTRIES = 20000


def _entry_uid(path: Path) -> int | None:
    """uid owning ``path`` itself, or None when it cannot be read.

    ``lstat`` rather than ``stat``: a symlink created by root is root's,
    whatever it points at, and following it would name the wrong account for
    both the link and its target.
    """
    try:
        return path.lstat().st_uid
    except OSError:
        return None


def _current_ids() -> tuple[int, int, int] | None:
    """``(uid, euid, gid)``, or None where ownership is not a thing.

    One capability question, asked in one place: Windows has no comparable
    per-file owner to check — the files a SYSTEM service writes into a user's
    home inherit that directory's ACL, so the owner can still write them.
    """
    if not hasattr(os, "geteuid"):
        return None
    return os.getuid(), os.geteuid(), os.getgid()


def _uid_name(uid: int, *, number: bool = True) -> str:
    """``root (uid 0)``, or bare ``root`` when ``number`` is False.

    The number earns its place where the reader has to *pick* an account (the
    "run it as …" half of a root-on-a-user-tree verdict) and costs a comma
    everywhere else — a name alone already answers "whose files are these".
    """
    try:
        import pwd

        name = pwd.getpwuid(uid).pw_name
        return f"{name} (uid {uid})" if number else name
    except (ImportError, KeyError):
        # A uid with no passwd entry is normal for a container or a deleted
        # account; the number alone is still an actionable answer.
        return f"uid {uid}"


def _foreign_owners(root: Path, uid: int, owner, *,
                    max_entries: int = _OWNERSHIP_MAX_ENTRIES) -> tuple[int, bool, set[int]]:
    """Entries under ``root`` owned by anyone but ``uid``.

    ``(count, root_is_foreign, uids)``.  No paths are returned: the fix is one
    `chown` over the whole tree, so naming three entries would only invite the
    reader to check those three and stop.

    The walk is bounded because this runs on every `start` and `status`, and a
    poisoned tree can hold a hundred thousand files while the verdict ("this
    tree is not yours") is already established by the first one.

    ``owner`` is required rather than defaulted: a default would bind
    ``_entry_uid`` at definition time, so a test (or a future platform) that
    replaced it would silently keep the original.  Everything except that one
    call is policy, which is why this can be exercised on a box whose files all
    report the same owner.
    """
    count = 0
    uids: set[int] = set()
    seen = 0

    def visit(path: Path) -> None:
        nonlocal count, seen
        seen += 1
        got = owner(path)
        if got is None or got == uid:
            return
        count += 1
        uids.add(got)

    # The root itself first: a tree created by root is the plainest form of
    # this, and it is decided without walking anything.
    visit(root)
    if count:
        return count, True, uids

    for dirpath, dirnames, filenames in os.walk(root):
        parent = Path(dirpath)
        for name in dirnames + filenames:
            if seen >= max_entries:
                return count, False, uids
            visit(parent / name)
    return count, False, uids


def _ownership_problem() -> tuple[str, str] | None:
    """``(symptom, fix)`` when HA_ROOT holds entries this account cannot govern.

    Two different mistakes, two different fixes: a normal user looking at
    root's files needs a ``chown``, and root looking at a user's tree needs to
    stop being root — running it as root would work once and then leave exactly
    the same trail behind.  Windows has neither: the files a SYSTEM service
    writes into a user's home inherit that directory's ACL, so the owner can
    still write them.
    """
    ids = _current_ids()
    if ids is None or not HA_ROOT.is_dir():
        return None
    uid, euid, gid = ids
    count, root_foreign, uids = _foreign_owners(HA_ROOT, uid, _entry_uid)
    if not count:
        return None

    where = _home_tilde(HA_ROOT)
    names = ", ".join(_uid_name(u) for u in sorted(uids))
    # The tree, never a tally: the count needs a cap to stay cheap (and the cap
    # makes it a lie on a big tree), no entry path helps — the fix is one
    # `chown` over the whole directory — and the only question left is whose
    # files these are.
    plain = ", ".join(_uid_name(u, number=False) for u in sorted(uids))

    # The tree root itself is a different sentence: there is no "3 of these
    # files" to offer, and the reader needs to know the whole directory is out
    # of reach rather than one entry in it.
    if root_foreign:
        if euid == 0:
            return (f"{where} is owned by {names}, but this is running as root — "
                    f"everything written here would become root's",
                    f"drop the sudo and run it as {names}")
        return (f"{where} is owned by {names}, not by this account — nothing "
                f"under it can be written",
                f"sudo chown -R {uid}:{gid} {where}")

    if euid == 0:
        return (f"some entries under {where} are owned by {names} — running as "
                f"root would only add more of the same",
                f"drop the sudo and run it as {names}")
    return (f"{where} do not belong to this account — {plain}",
            f"sudo chown -R {uid}:{gid} {where}")


def _log_ownership(problem: tuple[str, str] | None, level: str) -> bool:
    """Print the ownership verdict, if there is one; True when it printed.

    One formatter for both callers, because the same sentence twice worded two
    ways is how a user learns to distrust both: `start` refuses with ``FAIL``,
    `status` reports with ``WARN``, and the fix is identical on both lines.
    """
    if not problem:
        return False
    log(f"{level}  home: {problem[0]}")
    log(f"      run: {problem[1]}")
    return True


def cmd_status(args) -> int:
    """Health check.  Normal lines carry no marker; a marker means trouble.

    Only FAIL / WARN are prefixed.  A passing check needs no badge — the
    absence of one is the pass signal — and that keeps every healthy line in
    the same plain ``key: value`` shape as the rest of the CLI's output.
    """
    checks = [
        ("HA_ROOT", HA_ROOT.exists(), _home_tilde(HA_ROOT)),
    ]
    all_ok = True
    for name, ok, path in checks:
        if not ok:
            all_ok = False
            log(f"FAIL  {name}: {path}")
        else:
            log(f"{name}: {path}")

    # configuration.yaml gets no success line — its path is implied by HA_ROOT
    # above — so only its absence is worth reporting.
    if HA_ROOT.exists() and not _seed_present():
        all_ok = False
        log(f"FAIL  configuration.yaml: missing under {_home_tilde(HA_ROOT)}")

    # A WARN, not a FAIL: the home may be serving perfectly right now, and only
    # the next write will notice.  Saying it here is what turns "HA answers 500
    # after the upgrade" into a line with the fix in it.
    _log_ownership(_ownership_problem(), "WARN")

    # Same instance detection as start/stop — one predicate, so the two commands
    # cannot tell different stories.  That used to happen: after HA_ROOT was
    # deleted while hass kept serving from memory, start found the process by
    # scanning and said "running" while status, left with a deleted pid file,
    # said "not running" and blamed a stranger for holding the port.
    #
    # Two questions.  The lock names the pid when
    # it can; when it cannot, the supervisor plus a bound port still prove an
    # instance of ours is up — and saying so is the only way to keep that case
    # from reading as "some stranger has 8123".
    listening = port_in_use(PORT)
    pid = _ha_instance() if listening else None
    if pid:
        log(f"hass: running (PID {pid})")
    elif listening and _hass_via_service():
        log("hass: running (via service)")
    else:
        all_ok = False
        if listening:
            log(f"FAIL  hass: not running — port {PORT} held by another process")
        else:
            # A live pid with no bound port is not "there is nothing here": it
            # is the instance `start` will — correctly — refuse to duplicate,
            # because hass needs ~10s of imports before it binds 8123.  Both
            # commands ask a different question (start: must I spawn one?
            # status: is it serving?), so the judgement stays as it is and
            # only the wording tells the two states apart.
            booting = _ha_instance()
            if booting:
                log(f"FAIL  hass: not running — PID {booting} is up but "
                    f"port {PORT} is not bound yet")
            else:
                log("FAIL  hass: not running")

    # The supervisor's state, and deliberately short: three states plus one
    # suffix.  The suffix says autostart is unambiguously off — a choice the
    # user made with `disable`, not a fault, so it is not a FAIL marker and it
    # does not touch the exit code.  `hass:` above answers "is the process
    # there" and nothing else: folding the two together would make "not
    # running" ambiguous between "never came back" and "came back and stopped".
    # Position matters as much as wording — "hass: not running" and "service:
    # not installed" have completely different fixes, so the cause sits directly
    # under the symptom.
    kind = _service_kind()
    autostart_off = " (autostart off)" if _autostart_state() is False else ""
    if kind == "service":
        if not _win_service_installed():
            log("service: not installed")
        else:
            # Three states, no more.  The SCM has no "failed" state — a service
            # that exited nonzero is simply stopped — and a pending transition
            # reports "stopped" because the line above already says whether hass
            # is answering.  Ownership is not checked here either: the parent
            # link that answers it on Linux needs /proc.
            log(f"service: {'running' if _win_service_state() == 'running' else 'stopped'}"
                f"{autostart_off}")
    elif kind == "launchd":
        if not UNIT_PATH.exists():
            log("service: not installed")
        else:
            state, main = _launchd_info()
            if state == "running":
                log(f"service: running{autostart_off}")
                # launchd names the wrapper's pid, not hass's, exactly like
                # MainPID — so the same parent-link test decides ownership.
                if pid and main and _parent_pid(pid) != main:
                    log(f"WARN  service: does not own hass (PID {pid})")
                    log_run(_cmd("stop"))
                    log_run(_cmd("start"), "then")
            else:
                # No "failed" state here: launchd just stops the job, and
                # KeepAlive has already retried it one ThrottleInterval later.
                # HA's own log lives in HA_ROOT — `homeant logs` is the
                # diagnostic path here; there is no journal to point at.
                log(f"service: stopped{autostart_off}")
    elif kind != "systemd-user" or not UNIT_PATH.exists():
        log("service: not installed")
    else:
        r = _systemctl("is-active", SERVICE_NAME)
        state = ((r.stdout or "").strip() if r is not None else "") or "inactive"
        if state == "active":
            log(f"service: running{autostart_off}")
            main = _service_main_pid()
            # MainPID is the wrapper, never hass, so ownership is decided by the
            # parent link; comparing the two pids directly would warn on every
            # healthy host.
            if pid and main and _parent_pid(pid) != main:
                log(f"WARN  service: does not own hass (PID {pid})")
                log_run(_cmd("stop"))
                log_run(_cmd("start"), "then")
        else:
            log(f"service: stopped{autostart_off}")
            if state == "failed":
                # "failed" is the unit's last result, not necessarily a failed
                # start: a stop that ends in a non-zero exit lands here too, so
                # the line names the state and points at the journal instead of
                # claiming which half went wrong.
                log("WARN  service: failed — journalctl --user -u homeant -n 20")

    # The broker is a second daemon this product owns, so it gets a line of its
    # own rather than a clause under hass.  Only one of its states is trouble
    # for us: a port served by another program means the user runs mosquitto or
    # similar, hass may be perfectly happy with it, and nothing here is broken.
    # No exit-code effect either, for the same reason `oauth:` has none — a
    # stopped home is supposed to have a stopped broker.
    mqtt_conf = _mqtt_conf()
    mqtt_port = mqtt_conf["port"]
    mqtt_pid = None
    mqtt_err = _mqtt_gate()
    if mqtt_err:
        log(f"FAIL  mqtt: {mqtt_err}")
    else:
        mqtt_pid = _mqtt_pid()
        if mqtt_pid:
            log(f"mqtt: running (PID {mqtt_pid}, port {mqtt_port})")
        elif _mqtt_accepts(mqtt_conf["listen"], mqtt_port, 0.5):
            # The holder is named when the kernel will tell us, and the verdict
            # is "not part of this home" rather than "another program": a
            # listener we cannot confirm is not the same thing as a stranger's.
            holders = sorted(_listener_pids(mqtt_port))
            who = f"PID {holders[0]}" if holders else "another program"
            log(f"WARN  mqtt: port {mqtt_port} is served by {who} — "
                f"not part of this home")
        elif pid:
            # hass is up without a broker.  Under a supervisor `start` can no
            # longer repair that in place: the only legitimate spawner
            # is the supervised process, and that one is precisely what is
            # already running.  Name the two commands that do work rather than
            # one that now refuses with a longer version of this same line.
            if kind in ("systemd-user", "service", "launchd"):
                log("WARN  mqtt: not running")
                log_run(_cmd("stop"))
                log_run(_cmd("start"), "then")
            else:
                log("WARN  mqtt: not running")
                log_run(_cmd("start"))
        else:
            log("mqtt: not running")

    # OAuth gets no success badge either, and deliberately no effect on the exit
    # code: it is the one stage that waits on a browser, so "not configured"
    # describes an install still in progress, not a broken one — `start` is what
    # resumes it.  Same predicate as the gate in _finish_setup (a live config
    # entry), read from disk, so the two commands cannot disagree and no probe
    # request is spent finding out.
    #
    # A flow that is still open is reported apart from a missing one, because
    # the storage file cannot tell them apart and the user's next move differs:
    # one wants the login page, the other only a form nobody is looking at.
    #
    # Where the flow is parked cannot be read from disk — data_entry_flow keeps
    # no store, and core.config_entries holds entries only — so the one way to
    # ask is `GET /api/config/config_entries/flow/{id}` (200 for a known id;
    # the list endpoint is POST-only).  That costs one loopback request, spent
    # only when the marker exists, and it never mints a token or logs in: the
    # cached LLAT is used as-is.  Every failure — no token, hass down, 404 after
    # a restart — falls back to the wording that is true either way, so the line
    # is never worse than the stat() it replaced.
    # The flag is kept: the MCP block below is gated on the same stage, so both
    # commands stay silent about MCP until setup is done.
    setup_pending = not _xiaomi_already_configured()
    if not setup_pending:
        log("oauth: xiaomi_home configured")
    else:
        if XIAOMI_FLOW_FILE.exists():
            state = _xiaomi_flow_state()
            if state == "authorizing":
                log("WARN  oauth: xiaomi_home waiting for authorization — it opens the login page")
            elif state == "advancing":
                log("WARN  oauth: xiaomi_home authorized, entry not created")
            elif state == "lost":
                log("WARN  oauth: xiaomi_home flow no longer exists — it begins a new one")
            else:
                log("WARN  oauth: xiaomi_home flow unfinished")
        else:
            log("WARN  oauth: xiaomi_home not configured")
        # All four states are resumed by the same command, so it is said once.
        log_run(_cmd("start"))

    if pid and listening:
        # MCP is gated by the OAuth stage, exactly as it is in _finish_setup: a
        # config pasted into a client before setup is finished points at an
        # integration that is not there yet, and status would be handing out
        # the last step of a sequence that has not started.  The oauth line
        # above already carries the command that resumes it, so nothing is lost
        # by staying quiet here — the two commands now tell one story.
        if not setup_pending:
            m_ok, m_msg = _mcp_diag()
            log(f"mcp: {m_msg}" if m_ok else f"WARN  mcp: {m_msg}")
            tok = _mcp_token(create=False)
            if tok:
                log("mcp config — paste into your MCP client:")
                print(_mcp_config_text(tok))
                # Endpoint probe reports only on failure.  "token valid" above
                # is already the answer to the question the reader came with,
                # so a success line just restates it; a *failing* probe is the
                # one fact the token check cannot see (route not registered
                # yet), so it keeps its line — and being a marker, it also
                # carries the WARN badge.
                why = _mcp_probe(tok, timeout=5)
                if why:
                    log(f"WARN  mcp endpoint: not answering — {why}")
        # The DNS line is its own [homeant] line, not part of the WARN block:
        # it reports where THIS host resolves MCP_HOSTNAME, and a client on
        # another machine may resolve the name differently.  No "this server's
        # IP" is guessed — probing the default route's source would pick a VPN
        # tunnel or a Hyper-V switch as easily as the NIC the client sits
        # behind (the dev box here has eight IPv4 addresses and two default
        # routes).  A hint, never a check.  The lookup itself blocks on mDNS
        # for seconds, so _dns_line ticks while it waits — otherwise the
        # whole status looks hung.
        _dns_line()
        # DLNA discovery needs the same token the MCP config above came from.
        # With setup still pending there is nothing to report, so stay quiet.
        # `status` scans and reports only — enrolling a renderer is `start`'s
        # job, so a read-only command never creates config entries.
        if not setup_pending and tok:
            _dlna_discover(tok, enrol=False)
        # Nothing in this line is a measurement.  Whether 8123 is *allowed*
        # needs root on every platform (ufw status, iptables -S), and a
        # non-root reading misleads in both directions — it alarms on an
        # allowed port and hides a blocked one.  Detecting which firewall is
        # installed (ufw, firewalld, none) only decided whether to show a
        # reminder; it never answered the question, so it does not get to print
        # a status either.  All platforms, all states, one line, phrased as the
        # action to take.
        #
        # No port line either: this line only runs inside
        # `if pid and listening`, and pid was derived from listening, so it
        # could only ever print "listening".  Whether HA is bound to all
        # interfaces needs the socket table, which is not read here.
        # Both ports on one line.  1883 is named only when our own broker is
        # the one serving it: an "allow" for a port somebody else runs would
        # send the user to open a hole for nothing.
        allowed = f"tcp/{PORT}"
        if mqtt_pid:
            allowed += f", tcp/{mqtt_port}"
        log(f"WARN  firewall not checked, please allow {allowed}")
    else:
        # These lines describe how to reach a running server, so they are skipped
        # when there is none — the FAIL line above already says why.  Skipped
        # too while setup is pending: one rule for the whole block, so a status
        # mid-setup never mentions MCP anywhere.
        if not setup_pending:
            log("WARN  mcp: hass not running")

    return 0 if all_ok else 1


def _login_rejected_hint() -> None:
    """Print the one FAIL line for a refused credential, split by what the stores say.

    HA answers ``invalid_auth`` both for "no such user" and for "wrong password"
    (deliberately — no enumeration), so the API cannot say which.  The files
    can, and the two causes have opposite fixes:

    * user missing from the password store → half provisioned; re-provisioning
      adds it from nothing, so nothing can be lost.
    * user present but the bcrypt does not match ``PASSWORD`` → the two sides
      have drifted.  ``PASSWORD`` in cfg is the declared authority, so the fix
      is to let the offline pass rewrite the store — which cannot be done while
      hass is running, hence the two-verb advice rather than a silent rewrite
      from here.
    """
    username = cf("USERNAME", "admin")
    if _provider_has_user(username):
        log_state("FAIL", _tilde_text(
            f"admin login rejected — the password in {PROVIDER_STORE.name} "
            f"does not match PASSWORD in {CONFIG_FILE}; that file is the "
            f"authority"))
        log_run(_cmd("stop"))
        log_run(_cmd("start"), "then")
    else:
        log_state("FAIL", f"admin login rejected — '{username}' is missing from "
                          f"{PROVIDER_STORE.name}")
        log_run(_cmd("stop"))
        log_run(_cmd("start"), "then")


def _dns_hint() -> str:
    """Where MCP_HOSTNAME resolves on this host — a status hint, nothing more.

    Display-only: it gates no check and changes no exit code, because a client
    on another host can resolve the same name differently (see the MCP
    constants note).  A name that does not resolve is itself worth seeing, so
    it prints as "unresolved" instead of dropping the line.
    """
    try:
        return socket.gethostbyname(MCP_HOSTNAME)
    except OSError:
        return "unresolved"


def _dns_line() -> None:
    """Print the dns status line, ticking one dot per wall-clock second.

    ``socket.gethostbyname()`` on a ``.local`` name blocks on mDNS (measured
    4.3 s on this box) and ``log()`` evaluates its argument before printing,
    so that wait used to be a silent console that read as a hang.  Resolve on
    a thread and tick per second — same cadence, and same "silence reads as a
    hang" rule, as ``_dlna_scan``.  An instant lookup prints no dot, so the
    line is byte-for-byte what ``log()`` emitted before (tests mock this path).
    """
    box: dict[str, str] = {}

    def _resolve() -> None:
        try:
            box["ip"] = _dns_hint()
        except Exception:  # gethostbyname is OSError in practice; never hang
            box["ip"] = "unresolved"

    worker = threading.Thread(target=_resolve, daemon=True)
    worker.start()
    log_partial(f"dns: {MCP_HOSTNAME}")
    next_dot = time.monotonic() + 1.0
    while worker.is_alive():
        worker.join(timeout=0.25)
        now = time.monotonic()
        while now >= next_dot:
            log_tick()
            next_dot += 1.0
    print(f" -> {box['ip']}", flush=True)
    _mirror_log(f"dns: {MCP_HOSTNAME} -> {box['ip']}")


def _finish_setup(mcp_cfg: str | None, mcp_fail: dict | None = None) -> int:
    """Run the post-start stages in order, each gating the next.

    The chain is OAuth → MCP, and every exit prints one of three words —
    ``SUCCESS`` (done), ``PENDING`` (waiting on a human step — re-running this
    command is the retry) or ``FAIL`` (broken) — while returning 0 or 1.  The
    word is for the reader; the code says only whether anything needs fixing,
    which is why PENDING returns 0.  A stage that is not satisfied returns
    without running the next one, and nothing is cached between runs, so the
    sequence resumes from the top every time and is idempotent by construction.

    1. **oauth** — xiaomi_home must have a config entry.  Never waited on: the
       run advances the flow as far as it goes, surfaces the URL, and returns
       pending.  MCP is NOT printed here — setup is not done.
    2. **mcp** — ``mcp_cfg`` was produced before this call but after the
       RUNNING gate: the token is minted early (the gate needs it), the probe
       runs only once the core is up.  Its stanza opens the final block and the
       config follows, so nothing scrolls past what users copy out.
    """
    if _xiaomi_already_configured():
        log("xiaomi_home already configured — skipping OAuth")
        # Any id remembered from an earlier run is spent: the entry exists, so
        # there is no flow left to resume.
        XIAOMI_FLOW_FILE.unlink(missing_ok=True)
    else:
        # ── stage 1: OAuth, never waited on ──────────────────────────────────
        state, oauth_url, why = _xiaomi_advance()
        if state == "waiting":
            if oauth_url:
                # The URL gets a bare line of its own because it is copied, and
                # a prefix would be pasted along with it.  The command is
                # treated the same way, for the same reason.
                log_state("PENDING", "open this URL in your browser to finish setup")
                print(f"  {oauth_url}", flush=True)
                # The block opens on a sentence, so "then:" has to carry the
                # cd itself — no "run:" line above it to have done that.
                log_run(_cmd("start"), "then", cd=True)
            else:
                log_state("PENDING", "finish OAuth in the browser")
                log_run(_cmd("start"), "then", cd=True)
            return 0
        if state == "rejected":
            # The only way to get here is a rejected login.  Which of the two
            # causes it is decides the fix, and it is not always the cfg — see
            # _login_rejected_hint.  Not a browser problem either way.
            _login_rejected_hint()
            return 1
        # `done` means HA itself returned a create_entry result — that is the
        # integration's own terminal answer, so nothing is re-checked here.
        # Re-reading core.config_entries cannot confirm it anyway: HA writes
        # that file through async_delay_save(SAVE_DELAY=1), so a fresh entry is
        # still in memory when this line runs, and the `state` field is never
        # persisted at all.  The only thing a disk check adds is a one-second
        # race against a file that is guaranteed to be stale.
        if state != "done":
            # The flow's own verdict goes on this line: "see the lines above"
            # made the reader hunt for a reason that was never printed.  It is
            # already a sentence, so it follows a full stop; the command is the
            # next line, never the tail of this one.
            log_state("FAIL", "xiaomi_home setup did not complete"
                              + (f". {why}" if why else ""))
            log_run(_cmd("start"))
            return 1
        log("xiaomi_home setup complete")

    # ── stage 2: MCP config, last ────────────────────────────────────────────
    if not mcp_cfg:
        # Different failures, different fixes: a rejected credential is a
        # missing user or an out-of-date cfg (see _login_rejected_hint); a
        # refused token mint means the login worked and the core is the one
        # saying no; an endpoint that does not answer means the token is fine
        # but the integration behind it is not serving.  Collapsing them into
        # one line would send half the users to the wrong file.
        kind = (mcp_fail or {}).get("kind")
        if kind == "login":
            _login_rejected_hint()
        elif kind == "llat":
            log_state("FAIL", "signed in, but the core refused to create the MCP token")
            log_run(_cmd("start"))
        elif kind == "endpoint":
            log_state("FAIL", (mcp_fail or {}).get("why") or "the MCP endpoint did not answer")
            log_run(_cmd("start"))
        else:
            log_state("FAIL", "no MCP token available")
            log_run(_cmd("start"))
        return 1
    log_state("SUCCESS", "mcp ready — paste this config into your client:")
    print(mcp_cfg, flush=True)
    return 0


def _run_foreground() -> int:
    """Run hass in the foreground and exit with its status.

    This is the contract handed to every supervisor — systemd, launchd, the
    Windows SCM, docker.  They own start-at-boot, restart-on-crash and log
    collection; all this layer does is keep hass attached to the same process
    tree and turn one stop signal into an orderly shutdown.

    Deliberately *not* the orchestrator: no release probe, no unit writing, no
    MCP token, no setup gates, no config reconcile.  Those belong to the plain
    ``start``, and repeating them here would run them again on every crash
    restart — and, on the network probe, would stall a reboot behind a timeout.
    The one exception is waiting for a local address (``_wait_for_ipv4``), which
    is a precondition of hass rather than of the install: it is bounded, silent
    when there is nothing to wait for, and it has to sit where every supervisor
    will run it.
    """
    # Inner layer.  This is the process that owns the broker and
    # hass, and it is the process a supervisor restarts.  If it dies without
    # running its shutdown path, the kernel closing this handle takes both
    # children down, so the restart begins from a clean slate instead of finding
    # 8123 and 1883 still held by the previous attempt.  Nested inside the
    # service host's job on Windows — measured on this box to work, and the
    # outer close still collects the inner members.  The handle lives in
    # _WIN_JOBS, not in a local: a local would die with this frame.
    #
    # Skipped under the SCM, where it is both redundant and harmful.  Redundant:
    # the service host has already armed the same job and this process inherits
    # it, so the kernel still collects hass and the broker if this process dies.
    # Harmful: assigning *itself* to a KILL_ON_JOB_CLOSE job overwrites this
    # process's own exit code with 0 — closing the last handle terminates the
    # members, and the member that is exiting gets its code rewritten as part of
    # that termination.  Measured on this machine with a bare `sys.exit(100)`:
    # 100 without the job, 0 with it.  The service host is the one reader of
    # that code, and 0 means "stopped on purpose", so the restart hass asks for
    # was being filed as a clean stop and the SCM's failure actions never fired.
    if os.environ.get("HOMEANT_UNDER_SERVICE") != "1":
        _win_job_arm("foreground")

    # Reported here, refused only in the plain `start`: this path is the one a
    # supervisor restarts, so turning the verdict into an exit would convert one
    # readable line into a crash loop.  The line still has somewhere to land —
    # the journal on Linux, the unified log on macOS, the event log on Windows —
    # and it is the only way the supervised case explains itself, because hass
    # is about to fail with a permission error that never mentions ownership.
    _log_ownership(_ownership_problem(), "WARN")

    HA_ROOT.mkdir(parents=True, exist_ok=True)

    # One instance per HA_ROOT.  A second hass fails its 8123 bind halfway
    # through start-up and leaves a half-written .storage behind, so refuse
    # before spawning — and say which of the two cases this is, because the
    # fixes differ.
    pid = _ha_instance()
    if pid:
        log_state("FAIL", f"hass already running (PID {pid}) — stop that instance first")
        log_run(_cmd("stop"))
        return 1
    if _hass_via_service():
        # Same refusal, different evidence: the supervisor owns an instance and
        # something answers on 8123, but the lock cannot name the pid.  Falling
        # through would let this foreground run fight it for the socket.
        log_state("FAIL", "hass is already running under the service — "
                          "stop that instance first")
        log_run(_cmd("stop"))
        return 1
    if port_in_use(PORT):
        log_state("FAIL", f"port {PORT} is already in use by another program — "
                          f"stop it first, a second instance would fail its bind")
        return 1

    hb = hass_bin()
    if hb is None:
        # Foreground mode never installs anything: the supervisor's restart
        # policy would turn a download into an invisible retry loop, and the
        # installer is the only thing allowed to replace a tree.
        log_state("FAIL", "hass is not installed in this tree — --foreground "
                          "never installs anything")
        log_run(_cmd("start"))
        return 1

    # Bounded wait for a local address: hass refuses to set up zeroconf without
    # one, and a supervisor's boot start runs before DHCP is done.  Here rather
    # than in the unit because systemd, launchd, the SCM and docker all pass
    # through this function, while the unit text is per-platform.
    _wait_for_ipv4()

    # The broker comes up before hass for the reason recorded as decision #8:
    # hass's mqtt entry asks for a connection the moment it loads, and a broker
    # that arrives afterwards leaves that entry retrying until it gives up as
    # setup_error — the user sees "retrying" on a fresh install.  It sits here
    # rather than in the unit text because systemd, launchd, the SCM and docker
    # all pass through this function, and here rather than only in the
    # orchestrator because a supervisor restart runs exactly this and never the
    # orchestrator again.
    mqtt = _mqtt_ensure_running(replace=True)
    if mqtt == "failed":
        return 1
    # The entry belongs to the config rather than to this process, so it is
    # written here as well as in `start`: a supervisor restart of a fresh
    # install would otherwise run for the life of the machine without one.
    # Add-only, and skipped while hass is up, so a restart loop adds nothing.
    if mqtt != "port-taken" and not _provision_mqtt_entry():
        return 1

    cmd = [str(hb), "--ignore-os-check", "--config", str(HA_ROOT)]
    # stdout/stderr are inherited on purpose: journald and `docker logs` want
    # hass's own lines, not ours relayed through a pipe.  No start_new_session
    # either — the supervisor's cgroup/job must be able to collect the whole
    # tree when it stops this process.
    try:
        child = subprocess.Popen(
            cmd, env=_hass_child_env(), creationflags=_no_console_flags())
    except OSError as e:
        log_state("FAIL", f"cannot start hass — {e}")
        return 1

    log(f"foreground: hass PID {child.pid} — send SIGTERM here to stop it")

    forward = {"signum": 0, "at": 0.0, "killed": False}

    def _on_signal(signum, _frame) -> None:
        """Forward the first stop signal; ignore the rest.

        A second Ctrl+C must not shorten hass's flush window — .storage is being
        rewritten at that moment, and `homeant stop` would have waited the full
        STOP_WAIT_SEC for exactly this reason.
        """
        if forward["signum"]:
            return
        forward["signum"] = signum
        forward["at"] = time.monotonic()
        log("foreground: stopping hass ...")
        try:
            if IS_WIN:
                # Windows hass has no console to receive Ctrl+C and no signal to
                # catch, so TerminateProcess is the only stop there is — the
                # same conclusion _stop_pid reached for /F.
                child.kill()
            else:
                child.send_signal(signal.SIGTERM)
        except OSError:
            pass        # already gone; wait() below reports how it went

    saved: dict = {}
    for name in ("SIGTERM", "SIGINT"):
        sig = getattr(signal, name, None)
        if sig is None:
            continue
        try:
            saved[sig] = signal.signal(sig, _on_signal)
        except (OSError, ValueError, RuntimeError):
            pass        # not the main thread, or the platform refuses this one

    try:
        while True:
            try:
                rc = child.wait(timeout=1.0)
                break
            except subprocess.TimeoutExpired:
                if (forward["signum"] and not forward["killed"]
                        and time.monotonic() - forward["at"] > STOP_WAIT_SEC):
                    forward["killed"] = True
                    log(f"foreground: hass ignored the stop signal for {STOP_WAIT_SEC}s — killing it")
                    with contextlib.suppress(OSError):
                        child.kill()
    finally:
        for sig, old in saved.items():
            with contextlib.suppress(OSError, ValueError, RuntimeError):
                signal.signal(sig, old)

    # Observation only — no behaviour change.  The value wait() handed back,
    # printed before the signal mapping below, so a real 0 and a 0 produced by
    # that mapping can be told apart.  This is the number the SCM never sees
    # directly, and the one that has disagreed with it on this machine.
    log(f"foreground: hass raw exit {rc}")
    if rc < 0:
        # Died by a signal: report the shell convention (128+n) rather than -n,
        # so the number a supervisor logs matches what an operator would see.
        rc = 128 + (-rc)
        if forward["signum"] and rc == 128 + int(forward["signum"]):
            # We were asked to stop, and hass went down on exactly the signal
            # we forwarded: a requested shutdown, not a crash.  All three
            # supervisors read 143 as a failure, and each verdict is wrong
            # here — systemd files it as Result=exit-code, which makes `status`
            # print "WARN service: failed" after every clean stop; launchd
            # counts it as an unsuccessful exit and KeepAlive revives the job
            # we were asked to stop; the SCM records a non-zero stop.  0 is the
            # one value they all agree means "stopped as asked".  A hass that
            # dies on a signal we did *not* send keeps 128+n, so
            # Restart=on-failure still revives a crash — that is the case this
            # mapping exists for.
            log("foreground: hass stopped on the signal we forwarded — exiting 0")
            rc = 0
    log(f"foreground: hass exited with {rc}")
    # What this run started is always ours to stop.  A broker that was already
    # up is left alone when hass merely died — the supervisor is about to
    # restart it, and tearing the listener down would cost every MQTT device a
    # reconnect for nothing.  But when the stop was *asked for*, the whole home
    # is going down: leaving the listener behind would contradict the rule that
    # the broker's lifecycle is hass's, and it is exactly how the orphan
    # kept surviving `systemctl stop`.  `_mqtt_stop` re-validates the pid first,
    # so a broker that belongs to someone else is never touched.
    if mqtt == "started" or (mqtt == "running" and forward["signum"]):
        _mqtt_stop()
    # Observation only — no behaviour change.  The last number this layer states
    # before the interpreter turns it into a process exit code; compare it with
    # the service host's "hass exited with" line to see whether the value
    # survived the boundary.
    log(f"foreground: returning rc={rc} (mqtt={mqtt}, "
        f"signum={forward['signum']})")
    return rc


def cmd_start(args) -> int:
    """Start hass, first bringing the install up to date.

    The single entry point: a fresh install, an upgrade and a plain "is it up?"
    all land here.  Every stage it runs is a gate, so a second invocation finds
    nothing left to do.
    """
    global SPAWNED_PID
    # Supervisor mode, first of all: the unit's ExecStart runs exactly this
    # command, and it must behave like a well-mannered child — no network
    # probe, no installer hand-off, no gates, and no exit until hass does.
    if getattr(args, "foreground", False):
        return _run_foreground()
    # The SCM host: same "be a well-mannered child" contract as --foreground,
    # one layer up, and equally free of gates, probes and setup stages.
    if getattr(args, "service_host", False):
        return _service_host_main()

    # Before anything else, and before anything is touched: a tree left behind
    # by `sudo start` fails at the first write instead, and that write never
    # happens here — it happens inside HA, or inside `_cfg_set`, or inside the
    # broker's pidfile, each with an error that does not mention ownership.
    # Refusing here costs one `chown`; refusing later costs a diagnosis.
    #
    # Deliberately after the two supervisor branches above: the unit and the SCM
    # host are long-lived children whose failure the user reads in a log, and
    # gating them would trade one confusing symptom for a crash loop.
    if _log_ownership(_ownership_problem(), "FAIL"):
        return 1

    # Version check comes first: a newer release may ship a different
    # dependency probe, so the old build must not be the one deciding whether
    # this host is usable. Detection is read-only — nothing is touched until
    # the user says yes.
    #
    # The two switches are mutually exclusive and override the default, which
    # is "check the release host":
    #   --no-upgrade  what the installer passes to its own tail. It has just
    #                 unpacked the newest release and synced the venv, so
    #                 probing the release host and handing back to the installer
    #                 are the two things that must not happen again; without it
    #                 the chain py → installer → py would only end when the
    #                 network did.
    #   --reinstall   the user asked for the release, not for a verdict about
    #                 it: skip the comparison and the prompt, hand over.
    if getattr(args, "reinstall", False):
        return _run_installer("re-installing from the online installer ...")
    newer = None if getattr(args, "no_upgrade", False) else _check_newer_version()
    if newer:
        return _run_installer(
            f"installing {newer} — handing over to the online installer ...")

    # Dependency gate. Repair is never done here: the installer is the only
    # thing that knows how to download, replace and sync, and a second in-tree
    # copy of that is how two paths drift apart.
    #
    # An unsatisfied gate is not an error to be confirmed — it is a statement
    # that this tree is not the released one: uv reports the environment as
    # outdated, or hass is missing outright. `start` is defined as "make this
    # host serve the release", so it converges instead of asking: hand-editing
    # uv.lock is a deliberate deviation, and a prompt would only ask the user
    # to re-decide something they already decided by editing the file. The one
    # exception is `--no-upgrade`: we just came from the installer and it is
    # still not fixed, so looping would only re-download the same bytes.
    why = _deps_why()
    if why:
        if getattr(args, "no_upgrade", False):
            log_state("FAIL", f"dependencies incomplete — {why}. "
                              f"Re-run the installer: {INSTALLER_URL}")
            return 1
        log(f"deps: {why}")
        return _run_installer(
            "dependencies incomplete — handing over to the online installer ...")

    HA_ROOT.mkdir(parents=True, exist_ok=True)

    # Which supervisor this host has decides the whole launch path, and it is
    # decided before anything is stopped: "hass running with no unit" needs a
    # hand-over stop, "unit owns hass" must not be stopped at all, and a stop
    # between the two verdicts would leave neither state.
    svc = _service_kind()

    # Privilege gate, at the entry and before anything is touched.  Keeping the
    # home alive across a reboot is the one thing this design cannot do
    # unprivileged, and finding that out *after* a successful start is how a
    # promise becomes a postscript.  Refuse up front, name the exact command,
    # and leave the tree exactly as it was — the user fixes it in one line and
    # re-runs.  There is no "warning" variant of this verdict on purpose: a
    # start that cannot survive a reboot is not a start this layer may report
    # as done, whatever loginctl's wording happens to be.
    if svc == "systemd-user" and not _linger_ensure():
        return 1

    # Windows has a gate of the same shape for a different reason: the
    # registration lives in HKLM, so creating it needs administrator rights, and
    # an unattended `start` can never answer a UAC dialog.  Say it before
    # anything is touched — the files are already in place at this point, and
    # re-running the same command from an elevated prompt is the whole fix.
    if svc == "service" and not _service_registered() and not _is_admin():
        # The FAIL line already names the condition, so the hint is only the
        # plain relative command — the one thing to paste once elevated.  A
        # trailing "(from an elevated prompt)" would be copied along with the
        # command and break it, so it stays out of the run: line.  An absolute
        # path or a Start-Process incantation is harder to retype than to
        # remember, and this process still cannot elevate itself without
        # blocking on a prompt, which the design forbids everywhere.
        log_state("FAIL", "this needs an administrator prompt")
        log_run(_cmd("start"))
        return 1

    # An elevated `start` is the only moment this user can reach the SCM, so
    # spend it on the one setting an upgrade cannot reach.  A service registered
    # by an earlier build has the failure *actions* but not the flag that makes a
    # non-zero exit count as a failure, so a dead hass is never restarted.
    #
    # It sits before the "already running" branch on purpose: repairing a live
    # install is exactly how a user meets it, and that branch returns before
    # _win_service_ensure ever runs (measured on the real machine: an elevated
    # `start` on a running home printed nothing at all).  Guarded by _is_admin()
    # so the unprivileged path still makes zero SCM calls.
    if svc == "service" and _is_admin():
        _win_ensure_crash_recovery()

    # Windows counterpart of the autostart gate above, for a platform where the
    # change needs a right this prompt may not hold.  Two facts decide it: the
    # registry says the service is demanded-only (free to read), and this prompt
    # is not elevated.  Failing here is the point — bringing hass up first and
    # then admitting autostart stays off would be the half-success that makes
    # `start` and `disable` disagree about what "done" means.  A missing value
    # means "could not read", not "needs fixing", so it never blocks a start.
    if svc == "service" and _win_service_installed():
        start_type = _win_reg_value("Start")
        if start_type not in (None, "2"):
            if not _is_admin():
                log_state("FAIL", "the service is set to start on demand — "
                                  "this needs an administrator prompt")
                log_run(_cmd("start"))
                return 1
            if not _win_service_set_start(True):
                return 1

    # Autostart is part of what this verb promises: `start` means "serve the
    # release, and keep serving it after a reboot", and `disable` is the only
    # way out of that.  It therefore belongs *before* the "already running"
    # branch below, which returns early: a home left disabled but still running
    # would otherwise answer "already running", return, and never get its
    # autostart back — silently breaking this verb's own contract.  The cost is
    # one `systemctl is-enabled` per start, spent only when a unit exists.
    if svc == "systemd-user" and UNIT_PATH.exists() and not _service_enable():
        # Nothing was started or stopped here: a home that is already running
        # keeps running, it just will not come back at the next boot.
        return 1

    # macOS counterpart of the gate above.  launchd's `disable` is a mask, so a
    # label left disabled cannot be bootstrapped at all — it answers with a bare
    # "5: Input/output error".  Clearing the record here means
    # the cold path below finds a loadable label, and the running path (which
    # returns early) still restores the setting it is responsible for.
    if svc == "launchd" and UNIT_PATH.exists() and not _launchd_set_enabled(True):
        return 1

    # Firewall exceptions are part of what `start` means: the home must be
    # reachable from the LAN, and every gate above has already established the
    # privilege this may need (elevated on Windows, sudo-capable on Linux).
    # It sits before the "already running" branch so an idempotent re-start
    # still repairs a missing rule, and it never blocks start on failure —
    # `status` keeps its "please allow" line as the fallback.
    _firewall_ensure()

    # `start` is idempotent: a running hass already *is* the state we were asked
    # for, so stopping it would only interrupt the user.  Hand-edited config
    # therefore needs an explicit stop + start, not a bare `start`.
    #
    # Two witnesses for "running", with no process scan: the
    # lock names the pid, and when the lock cannot (deleted while hass keeps
    # serving from memory) the supervisor plus a bound port still prove that an
    # instance of ours is up — the service cannot be alive with its hass dead,
    # and 8123 is the only port this home ever binds.
    pid = _ha_instance()
    running = bool(pid) or _hass_via_service()
    if pid:
        log(f"hass already running (PID {pid})")
    elif running:
        log("hass already running (via service)")

    # A hass started by a build that had no service still answers on 8123, so
    # starting the supervisor would fail its bind while this process reported
    # "already running" and returned — the tree would stay one version behind
    # forever.  Stop it, then let the cold path bring it up the new way.
    #
    # This cannot be dropped: an audit found that removing it
    # makes a pre-service tree unable to ever register (the idempotent branch
    # above returns first).  `_stop_own_hass` reaches its pid branch here by
    # definition — the condition itself says nothing is registered.
    if running and svc in ("systemd-user", "service", "launchd") and not _service_registered():
        manager = {"systemd-user": "systemd", "service": "the Windows service",
                   "launchd": "launchd"}[svc]
        log(f"hass running outside the service manager — "
            f"moving it under {manager}")
        if not _stop_own_hass():
            log_state("FAIL", "the running hass did not exit — "
                              "cannot hand it over to the service manager")
            return 1
        pid = None
        running = False

    # A hass still running out of a HA_ROOT that lost its configuration.yaml is
    # answering from memory alone: .storage writes fail, so every stage below
    # would report a success that evaporates on the next boot.  That is not the
    # state `start` was asked for, so it recovers instead of reporting — stop,
    # fall through, and let the cold path deploy the seed again.  Same predicate
    # `status` uses for its FAIL line: one fact, so the two cannot disagree.
    #
    # The stop goes to the supervisor when there is one: killing its child
    # directly is indistinguishable from a crash, and the SCM/systemd would
    # restart the home about ten seconds later — in the middle of this redeploy
    # (measured on Windows: exit code 1066 plus the failure actions).
    if running and not _seed_present():
        log(f"hass running without configuration.yaml under "
            f"{_home_tilde(HA_ROOT)} — redeploying")
        if not _stop_own_hass():
            # Deploying under a live hass would be undone by its own shutdown
            # flush, so this path stops rather than tries.
            log_state("FAIL", "the running hass did not exit — "
                              "cannot redeploy its configuration under it")
            return 1
        pid = None
        running = False

    if running:
        # The setup stages are still owed, and this rerun is exactly how a first
        # install resumes: the user just finished OAuth in a browser.  Returning
        # `status` here would answer a question
        # nobody asked and never move the chain forward.
        #
        # "Already running" can also mean "started 3 seconds ago", so the same
        # ordering as the cold path applies: token first, gate, then the probe.
        mcp_fail: dict = {}
        tok = _mcp_token(fail=mcp_fail)
        if mcp_fail.get("kind") == "login" and not _provider_has_user(cf("USERNAME", "admin")):
            # Half provisioned: .storage/auth has the owner but the password
            # store has no such user, so *no* password can ever match and
            # editing the cfg is a dead end.  Provisioning needs hass stopped,
            # so fall through to the cold path — it re-provisions and spawns in
            # the same pass, which also bounds the recovery to one attempt (the
            # cold path never returns here).
            log("admin user missing from the password store — re-provisioning")
            if not _stop_own_hass():
                log_state("FAIL", "the running hass did not exit — cannot re-provision "
                                  "its admin account under a running instance")
                return 1
            pid = None
            running = False
        else:
            _wait_for_ha_running()
            # hass stays up either way — this pass never restarts it — so a
            # stopped broker is the one thing still worth fixing here. Reporting
            # success over a home whose devices have all gone offline is exactly
            # the half state the broker exists to avoid, and both calls below
            # are idempotent: a healthy broker is only re-confirmed, and hass
            # keeps its PID either way.
            if svc in ("systemd-user", "service", "launchd"):
                # This pass ends right after the return below, so spawning
                # here would hand the broker to a process that is about to die
                # — the very orphan this change removes.  Re-check only, and
                # report the half state rather than success over a home whose
                # devices have all gone offline.
                if _mqtt_pid() is None:
                    log_state("FAIL", "mqtt broker is not running — the service owns it")
                    log_run(_cmd("stop"))
                    log_run(_cmd("start"), "then")
                    return 1
            elif _mqtt_ensure_running() == "failed":
                return 1
            rc = _finish_setup(_ensure_mcp_ready(mcp_fail, tok=tok), mcp_fail)
            if rc == 0:
                # Same dns line as status, in the same slot before the scan:
                # config, dns, dlna.  setup is done, so the resolver is live.
                _dns_line()
                _dlna_discover(tok)
            return rc

    # No hass of ours is running at this point, so a listening 8123 belongs to
    # somebody else: the boot below would fail its bind, while the readiness
    # loop cheerfully reported "ready in 0.4s" because all it asks is whether
    # *something* answers on the socket.  The installer refuses the same case
    # before it downloads anything; this is the same verdict for the
    # `start`-only path, and it runs before the seed and the auth provisioning
    # touch anything.
    if port_in_use(PORT):
        log_state("FAIL", f"port {PORT} is already in use by another program — "
                          f"stop that one")
        log_run(_cmd("start"))
        return 1

    # Deploy the repo seed while hass is down (copy-or-merge per file; storage
    # entry sync refuses while hass is running).  Skipped outright when the
    # seed fingerprint already matches — see _ensure_seed.
    _ensure_seed()

    # Only the admin credential is prepared here, inside _ensure_auth_offline.
    # The broker's own account is not: it is generated once when the mqtt entry
    # is created (_provision_mqtt_entry) and read from that entry on every
    # connection, so there is nothing of ours to keep in step.
    _ensure_auth_offline()

    # Provision the owner into .storage/auth while hass is down — HA has no
    # runtime API for "create user with password".
    _ensure_auth_offline()

    # Broker before any start source below is asked to launch hass, so the
    # listener is accepting by the time the mqtt entry first loads.
    # What matters is *who* spawns it: under a supervisor this command is a
    # short-lived CLI, and a broker whose parent exits has no owner — that is
    # the orphan which keeps 1883 bound after `stop`, and the reason `stop`
    # had to guess with a pid file that names a trampoline.  The supervisor
    # runs `start --foreground`, which does the same ensure *before* it spawns
    # hass, so skipping the spawn here moves ownership onto a process that
    # lives exactly as long as the home.  The gate still runs: a broken cfg
    # must fail before anything is launched.
    if svc in ("systemd-user", "service", "launchd"):
        err = _mqtt_gate()
        if err:
            log_state("FAIL", err)
            return 1
        mqtt_state = "supervised"
    else:
        mqtt_state = _mqtt_ensure_running(replace=True)
        if mqtt_state == "failed":
            return 1

    # The entry has to exist before hass starts, or the integration is left
    # waiting for somebody to add it by hand.  Skipped when the port belongs to
    # a broker we did not start: its credentials are not ours, and an entry
    # pointing there with our password would fail setup instead of working.
    if mqtt_state != "port-taken" and not _provision_mqtt_entry():
        return 1

    hb = hass_bin()
    assert hb is not None
    cmd = [str(hb), "--ignore-os-check", "--config", str(HA_ROOT)]

    if svc == "none":
        # Containers and bare hosts: nothing to register with, and inventing a
        # supervisor is what this design refuses to do.  Say the one thing that
        # is actionable and carry on the old way.  Printed before the progress
        # line, which is a partial line waiting for its first dot.
        log("no service manager here — supervise it yourself:")
        log_run(_cmd("start") + " --foreground")

    t_boot = time.monotonic()

    if svc == "systemd-user":
        # From here the unit is the only start source: install, enable, start,
        # then wait for HTTP exactly as the spawned case does.  Popen here would
        # put two owners on one port — and systemd would then keep racing us.
        child_pid = _service_up()
        if not child_pid:
            return 1
        alive = _service_active
    elif svc == "service":
        # The SCM is the only start source on Windows, for the same reason, and
        # the gate above guaranteed there is a registration to start (or the
        # rights to create one).  `_win_service_ensure` usually has nothing to
        # do: ImagePath and the profile value already point at this tree.
        if not _win_service_ensure():
            return 1
        if not _win_service_start():
            _win_reap()
            return 1
        # The SCM reports no MainPID — hass writes its own lock, and the ready
        # branch below reads the pid from there, exactly as `status` does.
        child_pid = 0
        alive = lambda: _win_service_state() == "running"  # noqa: E731
    elif svc == "launchd":
        # Same rule as systemd: once the plist exists, launchd is the only
        # start source, and a Popen here would put two owners on one port.
        # launchd does report a pid, but it is the wrapper's — the log line
        # below wants hass's, which the ready branch reads from the lock.
        child_pid = _service_up_launchd()
        if not child_pid:
            return 1
        alive = _launchd_active
    else:
        # No supervisor at all (containers and bare hosts).  The detached spawn
        # is the last resort on purpose: two start sources on one port is the
        # failure this whole section exists to prevent, so it only runs where
        # there is nothing to register with.
        p = subprocess.Popen(
            cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            env=_hass_child_env(),
            start_new_session=True, creationflags=_no_console_flags(),
        )
        child_pid = p.pid
        # Only a child *this* process launched may be killed by its atexit hook.
        # In service mode SPAWNED_PID deliberately stays 0: hass belongs to the
        # supervisor, and killing it on our way out would look like a crash and
        # trigger the restart policy.
        SPAWNED_PID = child_pid
        if callable(globals().get("_mark_we_started_hass")):
            _mark_we_started_hass()  # type: ignore[name-defined]  # noqa: F821  (monkey-patched by _register_cleanup)
        alive = lambda: pid_exists(child_pid)  # noqa: E731

    # The progress line opens *after* the start verb, not before it: registering
    # the service prints "service installed: …" exactly once, and that line used
    # to land inside this half-finished one — `starting hass [homeant] service
    # installed: homeant`, dots on a line of their own.  Anything the supervisor
    # has to say about itself belongs above the wait, not in the middle of it.
    log_partial("starting hass ")

    # wait for HA ready - one dot per second, same cadence as the installer's
    # extract ticker: a cold start takes tens of seconds and a silent console
    # reads as a hang.  "Ready" means answering HTTP, not just holding the port:
    # 0.5s (or much more, cold) passes between the socket being bound and the
    # server accepting, and anything we send in that gap is dropped.
    #
    # The ceiling is 5 minutes, not 1, because a cold start is only fast on a
    # local filesystem.  Measured on a tree mounted over a slow filesystem:
    # the first boot after a fresh extract needed 86s to answer HTTP, the same
    # tree warm needed 8s - the difference is the first read of ~19k source
    # files through that mount, not anything wrong with HA.  A 60s ceiling
    # killed that boot 26 seconds before it finished, and reported it as
    # "did not come up".  Only the clock got longer: a dead process still
    # breaks out on the next tick, so a genuinely broken boot is reported just
    # as fast as before.
    for _ in range(SERVICE_START_TIMEOUT):
        log_tick()
        time.sleep(1)
        if alive() and _hass_serving():
            print(flush=True)
            if not child_pid:
                # Only the Windows service path lands here: the SCM reports no
                # MainPID, so the pid comes from HA's own lock file — the same
                # record `status` reads.  Zero means it was not written yet;
                # "service" then names the owner honestly instead of "PID 0".
                child_pid = _ha_instance() or 0
            who = f"PID {child_pid}" if child_pid else "service"
            log(f"hass started ({who}, ready in {time.monotonic() - t_boot:.1f}s)")
            # Two separate moments, in this order:
            #
            # 1. Mint/cache the MCP token BEFORE the RUNNING gate: the gate
            #    authenticates with it, so on a fresh install (no .mcp-token
            #    yet) it would otherwise bail out immediately with "core state
            #    probe skipped" — dead exactly when it matters most.
            # 2. Probe the endpoint only AFTER the gate.  "Answering HTTP" and
            #    "integrations loaded" are seconds apart — measured on this
            #    machine: port ready 4.1s, core RUNNING 11.4s — and mcp_server's
            #    /api/mcp route exists only once its config entry is set up.
            #    Probing in that gap 404s, and since the verdict is frozen into
            #    mcp_fail it survives the gate and is printed as the final
            #    answer a minute later.
            mcp_fail: dict = {}
            tok = _mcp_token(fail=mcp_fail)
            _wait_for_ha_running(t0=t_boot)
            rc = _finish_setup(_ensure_mcp_ready(mcp_fail, tok=tok), mcp_fail)
            if rc == 0:
                # Same dns line as status, in the same slot before the scan:
                # config, dns, dlna.  setup is done, so the resolver is live.
                _dns_line()
                _dlna_discover(tok)
            return rc
        if not alive():
            break
    print(flush=True)
    log_state("FAIL", f"hass did not come up — check {HASS_LOG}")
    if svc == "systemd-user":
        # Restart=on-failure would retry every 10s from here, invisibly, while
        # the port stays free and nothing explains why.
        _service_reap()
    elif svc == "service":
        # Same reason: the SCM's failure actions would keep restarting a home
        # that cannot boot, and the evidence is in the event log.
        _win_reap()
    elif svc == "launchd":
        # KeepAlive{SuccessfulExit=false} retries every ThrottleInterval, and
        # the unified log is the only place the why was written.
        _launchd_reap()
    return 1


def _win_graceful_stop(pid: int, timeout: float = 30.0) -> str:
    """Ask HA to shut itself down over HTTP.  "gone" / "timeout" / "unavailable".

    This is a different door into the same shutdown, not a contradiction of the
    note below: hass has no console (``DETACHED_PROCESS``), so a *signal* has
    nowhere to go — but ``homeassistant.stop`` is a service call the core
    handles itself, and it runs the same four stages a supervisor's SIGTERM
    would: shutdown jobs, integrations, final write, close.

    The token is the cached MCP one, read straight from disk: a stop must never
    mint credentials, and probing it first would add a round trip to every stop
    — a rejected token shows up as a non-200 on the call that matters.  No
    cache means this path is not available, and the caller falls back to force.

    The loopback literal matches ``MCP_PROBE_BASE`` and the other local
    probes: it skips the resolver and the address-list walk (see
    ``port_in_use`` for the ~2s cost of a refused second attempt on Windows).
    Measured 2026-11-14: ``::1``, ``localhost`` and ``127.0.0.1`` all answer
    :8123 in under 0.03s here, so this is determinism, not an IPv6 workaround.
    """
    try:
        tok = MCP_TOKEN_FILE.read_text(encoding="utf-8").strip()
    except OSError:
        return "unavailable"
    if not tok:
        return "unavailable"
    try:
        status, _ = _http_post(
            f"http://127.0.0.1:{PORT}/api/services/homeassistant/stop",
            json_body={}, headers={"Authorization": f"Bearer {tok}"},
            timeout=5.0,
        )
    except Exception as e:
        log(f"graceful stop: request failed ({e})")
        return "unavailable"
    if status != 200:
        log(f"graceful stop: HTTP {status} — falling back to force")
        return "unavailable"
    t0 = time.monotonic()
    deadline = t0 + timeout
    while time.monotonic() < deadline:
        if not pid_exists(pid):
            # How long the core actually took is the only number that says
            # whether the window is sized right: this is one call, so the
            # elapsed time is the core's shutdown duration, not a sampling
            # artefact.  1-2 s once the core is
            # RUNNING; the single 30 s outlier came from a stop that landed
            # while the core was still starting.
            log(f"graceful stop: gone after {time.monotonic() - t0:.1f}s")
            return "gone"
        time.sleep(0.25)
    return "timeout"


def _stop_pid(pid: int) -> bool:
    """Kill the hass at `pid`; True once it is provably gone.

    Windows has two ways to end a home and the order matters:

    * **ask first** — ``_win_graceful_stop`` calls ``homeassistant.stop``, so
      the core flushes .storage and closes its own connections instead of
      dying mid-write.  Bounded at 30 s; a failure here costs nothing but the
      fallback.
    * **then force** — ``taskkill /F /T`` from the first attempt.  ``/T``
      without ``/F`` cannot touch a detached console process (measured: exit
      128, "can only be terminated forcefully"), so the old nice-then-force
      dance burned a guaranteed 10s on every stop.

    What has *not* changed is the signal story: hass is started with
    ``DETACHED_PROCESS``, so it has no console to receive Ctrl+C and there is
    no graceful *signal* to send.  That sentence is about signals only; the
    HTTP call above is the graceful path, and both are true at once.

    POSIX: SIGTERM the process *group* when the pid leads one.  `start` uses
    start_new_session=True, so pid == pgid, and this is exactly what install.sh
    does with `kill -TERM -$pid` — signalling only the leader would leave the
    workers holding the venv.  A hass started some other way may share the
    caller's group, and signalling *that* would take the user's shell down with
    it, hence the pgid == pid test.

    The return value matters: SIGKILL is asynchronous, and the caller may be
    about to rewrite .storage/auth or .storage/core.config_entries.  A dying
    hass flushes its own stores on the way out, so "sent the signal" is not
    "safe to write" — both platforms therefore wait for the process to actually
    disappear before reporting success.
    """
    log(f"stopping hass (PID {pid}) ...")
    if IS_WIN:
        outcome = _win_graceful_stop(pid)
        if outcome == "gone":
            log("hass stopped gracefully")
            return True
        if outcome == "timeout":
            log("WARN graceful stop timed out — killing hass")
        r = subprocess.run(["taskkill", "/PID", str(pid), "/F", "/T"],
                           capture_output=True, creationflags=_no_console_flags())
        if r.returncode != 0:
            # Same refusal the broker meets: taskkill treats the tree as one
            # unit, so a single member this token may not end makes it abandon
            # the parent too — and it reports that as 128, the code it also
            # uses for a pid that is already gone.  Ending the pid we were
            # asked about directly recovers every case the walk gave up on.
            _win_terminate(pid)
        for _ in range(20):
            if not pid_exists(pid):
                return True
            time.sleep(0.5)
        return False
    try:
        pgid = os.getpgid(pid)
    except ProcessLookupError:
        pgid = None
    signal_fn = os.killpg if pgid == pid else os.kill
    target = pgid if pgid == pid else pid
    try:
        signal_fn(target, signal.SIGTERM)
    except (ProcessLookupError, PermissionError):
        pass
    for _ in range(60):
        if not pid_exists(pid):
            return True
        time.sleep(0.5)
    try:
        signal_fn(target, signal.SIGKILL)
    except (ProcessLookupError, PermissionError):
        pass
    # SIGKILL cannot be ignored, but the process still needs scheduling time to
    # die; without this wait the very next write races its exit flush.
    for _ in range(20):
        if not pid_exists(pid):
            return True
        time.sleep(0.5)
    return False


def cmd_stop(args) -> int:
    """Stop the home.  Registration and autostart both stay as they are.

    One verb, spelled the same way on every platform, because the underlying
    operation is the same one everywhere: end the process.  ``systemctl stop``,
    ``launchctl bootout`` and ``SERVICE_CONTROL_STOP`` differ in name only, and
    each is the *single* word its supervisor has for it.

    ``disable`` is deliberately not part of it.  Autostart is a property of the
    registration, not of this run, and the three platforms cannot agree on who
    may change it: `systemctl --user disable` and `launchctl disable` are
    unprivileged, while changing a Windows service's start type needs
    ``SERVICE_CHANGE_CONFIG`` — the same right that would let its holder repoint
    the binary somewhere else (measured 11-07: ``OpenService`` with that mask →
    access denied for a plain user, and install grants ``IU`` only ``RP``/``WP``
    for exactly this reason).  Disabling here would therefore mean doing it on
    two platforms and quietly not doing it on the third — one flag, three
    behaviours.  So it happens in neither: ``uninstall`` removes the
    registration, and a removed registration does not come back.

    Consequence, stated plainly rather than discovered later: a stopped home
    that is still installed starts again at the next boot or GUI login.

    Measured 11-05: leaving the unit enabled does *not* bring the process back
    by itself either — ``Restart=on-failure`` reacts to unexpected exits, and a
    stop request is an expected one — so there is nothing to undo here and no
    ordering trick to play.

    Linger is left untouched too: it says whether the user's manager survives a
    logout, which has nothing to do with this home.

    An unregistered tree — and any host with no supervisor at all — keeps the
    old path exactly: find the process, kill it, wait for it to be gone.
    """
    # Asked *before* the stop, because afterwards the answer is gone: every
    # supervisor returns the same success whether it stopped a live home or
    # there was nothing to stop, so `service_stopped` alone cannot tell the two
    # apart — an idle `stop` printed "hass stopped" on all
    # three platforms, which reads as "something was running and I ended it".
    was_running = bool(_ha_instance()) or _supervisor_running()
    if _service_kind() == "systemd-user" and UNIT_PATH.exists():
        r = _systemctl("stop", SERVICE_NAME)
        if r is None or r.returncode != 0:
            # Silence here would read as "stopped" while systemd keeps the
            # home alive behind us — the one outcome this must never fake.
            chatter = ((r.stderr or "") + (r.stdout or "")).strip() if r else ""
            why = (chatter.splitlines()[-1] if chatter
                   else f"systemctl exited {r.returncode}" if r
                   else "systemctl is unavailable")
            log_state("FAIL", f"cannot stop the service — {why}")
            return 1
    elif _service_kind() == "service" and _win_service_installed():
        # Same one verb as Linux.  Start-at-boot was set once at install and is
        # left alone here — see the docstring for why it cannot be otherwise.
        if not _win_service_stop():
            return 1
    elif _service_kind() == "launchd" and UNIT_PATH.exists():
        # Same one verb again: `bootout` unloads the job and leaves the plist in
        # place.  `launchctl disable` exists and is unprivileged, but it is not
        # used here on purpose — the contract is identical on all three
        # platforms, and "stays stopped across a reboot" belongs to `uninstall`.
        if not _launchd_bootout():
            return 1

    # Asked *after* the supervisor, and by the same predicate start and status
    # use: a hass the unit never owned (a bare `start` from before this tree was
    # registered) is still ours to stop.
    pid = _ha_instance()
    if not pid:
        log("hass stopped" if was_running else "hass not running")
        # The broker can outlive a hass that died on its own, and a stop that
        # left 1883 answering would be half a stop: the home is gone but its
        # MQTT endpoint still is not.
        return 0 if _mqtt_stop() else 1

    if not _stop_pid(pid):
        # Which of the two answers applies is ours to decide, not the reader's:
        # this window either holds the right to end the process or it does not,
        # and "if it belongs to the service …" made the caller work that out.
        # A hass the service left behind runs as LocalSystem, so an ordinary
        # prompt is refused outright — measured: rc=255, "access denied".
        if IS_WIN and not _is_admin():
            log_state("FAIL", f"hass (PID {pid}) is still running — "
                              f"run as administrator")
            log("      run: .\\homeant stop")
        else:
            log_state("FAIL", f"hass (PID {pid}) is still running — "
                              f"it may be stuck in shutdown; try again or kill it by hand")
        return 1
    log("hass stopped")
    # After hass, never before: hass rewrites .storage on its way out and an
    # MQTT broker still answering during those seconds costs nothing.
    return 0 if _mqtt_stop() else 1


def cmd_disable(args) -> int:
    """Turn off start-at-boot.  The running home is not touched.

    The mirror image of what `start` does to autostart, and one of only two
    verbs that change it (`uninstall` is the other, by removing the
    registration).  `stop` deliberately does not, on every platform and for the
    same reason: it ends a process and nothing else.

    Calling `start` afterwards turns autostart back on.  That is the documented
    price of keeping `start` as the single "make this host serve" verb, so the
    help text says it instead of letting it be discovered.

    A host with no registration has nothing to disable.  That is a failure
    rather than a quiet no-op: the only reason to run this verb is to change a
    boot setting, so answering "done" when there is none would be a lie.
    """
    kind = _service_kind()
    if kind == "systemd-user":
        if not UNIT_PATH.exists():
            log_state("FAIL", "nothing is registered yet")
            log_run(_cmd("start"))
            return 1
        if not _service_disable():
            return 1
        log("autostart off")
        return 0
    if kind == "service":
        if not _win_service_installed():
            log_state("FAIL", "nothing is registered yet")
            log_run(_cmd("start"))
            return 1
        if not _win_service_set_start(False):
            return 1
        log("autostart off")
        return 0
    if kind == "launchd":
        if not UNIT_PATH.exists():
            log_state("FAIL", "nothing is registered yet")
            log_run(_cmd("start"))
            return 1
        if not _launchd_set_enabled(False):
            return 1
        log("autostart off")
        return 0
    log_state("FAIL", "nothing is registered yet")
    log_run(_cmd("start"))
    return 1


# ── uninstall ────────────────────────────────────────────────────────────────

def _service_unregister() -> tuple[bool, str | None]:
    """Stop the supervisor and delete its registration.

    Returns ``(ok, what was removed)``.  ``ok`` is False only when the service
    is still standing: deleting the data directory under a running home is how
    the stores get written back from memory after they are already gone.
    """
    kind = _service_kind()
    if kind == "systemd-user":
        if not UNIT_PATH.exists():
            return True, None
        # Two verbs here, and this is the only place that uses the first one.
        # `stop` alone deliberately leaves autostart enabled (see cmd_stop);
        # uninstall is the verb that means "do not come back", so it is also
        # the one that clears the autostart symlink.  Both must succeed before
        # the unit file goes, otherwise the supervisor is still watching a
        # directory we are about to empty.
        for verb in ("disable", "stop"):
            r = _systemctl(verb, SERVICE_NAME)
            if r is None or r.returncode != 0:
                chatter = ((r.stderr or "") + (r.stdout or "")).strip() if r else ""
                why = (chatter.splitlines()[-1] if chatter
                       else f"systemctl exited {r.returncode}" if r
                       else "systemctl is unavailable")
                log_state("FAIL", f"cannot {verb} the service — {why}")
                return False, None
        UNIT_PATH.unlink(missing_ok=True)
        _systemctl("daemon-reload")
        return True, f"service unit removed: {UNIT_PATH}"
    if kind == "service":
        # pywin32 speaks SCM directly.  The old version shelled out to `sc.exe`
        # and swallowed a missing binary as "nothing registered" — which made a
        # refused deletion look like success.  Every failure below is real, and
        # uninstall keeps the data when one of them happens.
        return _win_service_unregister()
    if kind == "launchd":
        had_plist = UNIT_PATH.exists()
        # bootout first: deleting a plist under a loaded job leaves launchd
        # running a definition that is no longer on disk, and uninstall is about
        # to empty the directory that job serves.
        if had_plist:
            if not _launchd_bootout():
                return False, None
            UNIT_PATH.unlink(missing_ok=True)
        # `launchctl disable` writes a record into the GUI domain that outlives
        # the plist: a leftover "disabled" label is a mask the
        # next `start` cannot bootstrap through, and its enable gate skips the
        # repair precisely when the plist is gone.  Clearing the ledger belongs
        # to removing the registration; it is a no-op when no record exists.
        ledger_disabled = _autostart_state() is False
        if ledger_disabled and not _launchd_set_enabled(True):
            return False, None
        notes = [f"service plist removed: {UNIT_PATH}"] if had_plist else []
        if ledger_disabled:
            notes.append("launchd disabled record cleared")
        return True, "; ".join(notes) or None
    return True, None


def _uninstall_guard() -> str | None:
    """Why deleting HA_ROOT must be refused, or None when it is safe.

    Typing ``uninstall`` is the decision, so none of this asks a question.  The
    checks exist for a *wrong* HA_ROOT — a bug, a hand-edited path, a symlink
    planted where the data dir should be — and each one is cheaper than the
    deletion it prevents.
    """
    if HA_ROOT.is_symlink():
        return f"refusing to delete {_home_tilde(HA_ROOT)} — it is a symbolic link"
    if not HA_ROOT.is_dir():
        return f"refusing to delete {_home_tilde(HA_ROOT)} — it is not a directory"
    resolved = HA_ROOT.resolve()
    if resolved.name != ".homeant":
        return (f"refusing to delete {_home_tilde(resolved)} — its last component "
                f"is not '.homeant'")
    for wrong in (Path.home().resolve(), PROJECT_ROOT.resolve(),
                  Path(resolved.anchor)):
        if resolved == wrong:
            return (f"refusing to delete {_home_tilde(resolved)} — "
                    f"that is {_home_tilde(wrong)}")
    return None


def _tree_size(path: Path) -> tuple[int, int]:
    """(entry count, bytes) of a directory, counting links as links."""
    files = 0
    total = 0
    for dirpath, _dirnames, filenames in os.walk(path, followlinks=False):
        for name in filenames:
            files += 1
            try:
                total += os.lstat(os.path.join(dirpath, name)).st_size
            except OSError:
                pass            # vanished mid-walk; the count is documentary
    return files, total


def _discard(path: Path) -> bool:
    """Delete ``path`` outright: no trash, no prompt, no second copy.

    Typing `uninstall` is the decision, and the expected outcome is a direct
    delete.  The data directory is the only thing ever passed
    here; the program tree is deliberately left in place.
    """
    try:
        shutil.rmtree(path)
    except OSError as e:
        log_state("FAIL", f"cannot remove {_home_tilde(path)} — {e}")
        return False
    return not path.exists()


def cmd_uninstall(args) -> int:
    """Remove the service registration and the data dir.

    Order is the whole safety story: the supervisor goes first (so nothing
    restarts it), then any hass the supervisor never owned (so nothing flushes
    its stores into a directory that is being emptied), and only then the files.
    The source tree is never touched — it is where this script lives, and this
    is a portable install.  Every file this project creates lives in HA_ROOT,
    so removing that one directory is the whole cleanup.

    There is no --keep-data and no prompt: typing this verb is the decision.
    Keeping the data is what `stop` is for.  The delete is outright — no
    Recycle Bin — and `status` / a second `uninstall` deliberately keep their
    current behaviour.
    """
    ok, removed = _service_unregister()
    if not ok:
        return 1
    notes = [removed] if removed else []

    # One last process check after the service is gone: a hass started by hand
    # (or by a build from before this tree was registered) is invisible to the
    # supervisor but writes to HA_ROOT all the same.
    pid = _ha_instance()
    if pid:
        if not _stop_pid(pid):
            log_state("FAIL", f"hass (PID {pid}) is still running — it may be "
                              f"flushing its stores; nothing was deleted")
            return 1
        notes.append(f"stopped hass (PID {pid})")

    if not HA_ROOT.exists():
        for note in notes:
            log(note)
        log("data already gone" if notes else "nothing to uninstall")
        return 0

    why = _uninstall_guard()
    if why:
        log_state("FAIL", why)
        return 1

    files, size = _tree_size(HA_ROOT)
    # Printed before the deletion, and phrased as a record rather than a
    # question: after it runs, this line is the only account of what was there.
    log(f"removing {HA_ROOT} ({files} files, {size / 1e6:.1f} MB)")
    if not _discard(HA_ROOT):
        return 1
    for note in notes:
        log(note)
    log("data removed")
    return 0


def cmd_logs(args) -> int:
    if not HASS_LOG.exists():
        log(f"no hass log at {HASS_LOG}")
        return 1
    log(f"streaming {HASS_LOG} (Ctrl+C to exit)")
    try:
        with open(HASS_LOG, "r", encoding="utf-8", errors="replace") as f:
            f.seek(0, 2)
            while True:
                line = f.readline()
                if not line:
                    time.sleep(0.2)
                    continue
                sys.stdout.write(line)
                sys.stdout.flush()
    except KeyboardInterrupt:
        print()
        return 0


# ── auth: silent onboarding → access_token ───────────────────────────────────

def _http_post(url: str, json_body: dict | None = None,
               form_body: dict | None = None,
               headers: dict | None = None, timeout: float = 10.0
               ) -> tuple[int, dict]:
    """Tiny urllib wrapper: POST JSON or form, return (status, parsed_json)."""
    import urllib.request as _ur
    import urllib.parse as _up

    hdrs = dict(headers) if headers else {}
    if json_body is not None:
        data = json.dumps(json_body).encode("utf-8")
        hdrs.setdefault("Content-Type", "application/json")
    elif form_body is not None:
        data = _up.urlencode(form_body).encode("utf-8")
        hdrs.setdefault("Content-Type", "application/x-www-form-urlencoded")
    else:
        data = b""
    req = _ur.Request(url, data=data, headers=hdrs, method="POST")
    try:
        with _ur.urlopen(req, timeout=timeout) as resp:
            body = resp.read().decode("utf-8")
            return resp.status, json.loads(body) if body else {}
    except _ur.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        try:
            return e.code, json.loads(body) if body else {}
        except json.JSONDecodeError:
            return e.code, {"raw": body}


def _http_get(url: str, headers: dict | None = None,
              timeout: float = 10.0) -> tuple[int, dict]:
    """Tiny urllib wrapper: GET, return (status, parsed_json)."""
    import urllib.request as _ur
    hdrs = dict(headers) if headers else {}
    req = _ur.Request(url, headers=hdrs, method="GET")
    try:
        with _ur.urlopen(req, timeout=timeout) as resp:
            body = resp.read().decode("utf-8")
            return resp.status, json.loads(body) if body else {}
    except _ur.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        try:
            return e.code, json.loads(body) if body else {}
        except json.JSONDecodeError:
            return e.code, {"raw": body}


# ── DLNA renderer discovery + enrolment (D25) ──────────────────────────────
#
# Idle preparation for the `homeant_dlna` component: find MediaRenderers on the
# LAN and hand each LOCATION to HA's own dlna_dmr config flow, so the agent gets
# a media_player entity without a single UI click.  Every network fact comes
# from the scan — no device name / model / IP is hardcoded (jiqia D25).
#
# The three pure parsers below take recorded bytes, not sockets, so the gate can
# test the wire format offline.  Only `_dlna_enrol` touches the network.

_DLNA_SEARCH = (
    "M-SEARCH * HTTP/1.1\r\n"
    "HOST: 239.255.255.250:1900\r\n"
    'MAN: "ssdp:discover"\r\n'
    "MX: 2\r\n"
    "ST: urn:schemas-upnp-org:device:MediaRenderer:1\r\n"
    "\r\n"
)
_DLNA_MCAST = ("239.255.255.250", 1900)


def _dlna_locations(responses: list[bytes]) -> dict[str, str]:
    """LOCATION -> source IP from raw SSDP datagrams; ignore non-renderers.

    A datagram counts only if it carries the MediaRenderer search target (ST or
    USN), which keeps a router's IGD reply from being enrolled as a speaker.
    """
    out: dict[str, str] = {}
    for raw in responses:
        text = raw.decode("utf-8", "replace")
        head = "\n".join(line.strip() for line in text.splitlines())
        if "MediaRenderer:1" not in head and "MediaRenderer:2" not in head \
                and "MediaRenderer:3" not in head:
            continue
        m = re.search(r"(?im)^LOCATION:\s*(\S+)", text)
        if not m:
            continue
        from urllib.parse import urlparse as _urlparse
        url = m.group(1).strip()
        host = _urlparse(url).hostname or ""
        out[url] = host
    return out


def _dlna_device_info(xml_text: str) -> dict[str, str] | None:
    """friendlyName / UDN / deviceType from a UPnP description document.

    Returns None unless this is actually a MediaRenderer, so a coincidental
    LOCATION pointing at some other UPnP device is not enrolled.
    """
    def tag(name: str) -> str:
        m = re.search(rf"<{name}>(.*?)</{name}>", xml_text, re.S | re.I)
        return m.group(1).strip() if m else ""

    dtype = tag("deviceType")
    if "MediaRenderer" not in dtype:
        return None
    return {
        "friendly_name": tag("friendlyName"),
        "udn": tag("UDN"),
        "device_type": dtype,
    }


def _dlna_scan(window: float = 5.0, attempts: int = 1,
               progress: bool = False) -> dict[str, str]:
    """One M-SEARCH, listen for a fixed window, keep every reply.  Never raises.

    The old two tries covered a multi-homed box sending from a virtual adapter
    (measured 11-19): pinning IP_MULTICAST_IF to the routed LAN address fixed
    the misses, and five consecutive single-try scans then all found the
    renderer.  `progress` draws dots so a foreground `start`/`status` shows the
    wait; `attempts` stays a parameter for tests, not as a second default send.
    """
    import socket

    replies: list[bytes] = []
    out_ip = _route_source_ip()
    if progress:
        print("[homeant] dlna: scanning", end="", flush=True)
    next_dot = time.monotonic() + 1.0
    for _ in range(attempts):
        deadline = time.monotonic() + window
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        if out_ip:
            # Multi-homed Windows boxes default to a virtual/tunnel adapter;
            # pin the multicast source to the LAN interface the kernel routes
            # public traffic through, or the renderer never sees M-SEARCH.
            sock.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_IF,
                            socket.inet_aton(out_ip))
        try:
            sock.sendto(_DLNA_SEARCH.encode("ascii"), _DLNA_MCAST)
            while True:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                # Short reads: tick by wall clock even when nobody answers.
                # A full-window recv timeout used to skip every dot in the
                # exact case the dots are for — no renderer on the LAN.
                sock.settimeout(min(remaining, 0.25))
                try:
                    data, _addr = sock.recvfrom(4096)
                except socket.timeout:
                    pass
                else:
                    replies.append(data)
                if progress:
                    now = time.monotonic()
                    while now >= next_dot:
                        print(".", end="", flush=True)
                        next_dot += 1.0
        except OSError:
            pass
        finally:
            sock.close()
    if progress:
        print(" done", flush=True)
    return _dlna_locations(replies)


def _dlna_existing_udns(token: str, ha_url: str) -> set[str]:
    """UDNs already enrolled, so a second `start` does not duplicate entries."""
    try:
        st, body = _http_get(
            f"{ha_url}/api/config/config_entries",
            headers={"Authorization": f"Bearer {token}"}, timeout=10,
        )
    except Exception:
        return set()
    if st != 200 or not isinstance(body, list):
        return set()
    found: set[str] = set()
    for entry in body:
        if not isinstance(entry, dict) or entry.get("domain") != "dlna_dmr":
            continue
        udn = (entry.get("data") or {}).get("udn")
        if udn:
            found.add(str(udn))
    return found


def _dlna_enrol_one(token: str, ha_url: str, location: str) -> str:
    """Drive dlna_dmr's config flow to create_entry.  Returns a verdict word.

    The manual path is used on purpose: it does not read the ssdp cache (which
    is empty because we ship no `ssdp:` line), and the integration connects to
    the device itself to learn the UDN.  On any failure the in-progress flow is
    DELETEd so a retry does not pile up hung flows.
    """
    headers = {"Authorization": f"Bearer {token}"}
    status, flow = _http_post(
        f"{ha_url}/api/config/config_entries/flow",
        json_body={"handler": "dlna_dmr"}, headers=headers, timeout=15,
    )
    if status != 200 or "flow_id" not in flow:
        return "flow-start-failed"
    flow_id = flow["flow_id"]
    try:
        # The user step falls through to `manual` when the ssdp cache is empty.
        step = flow.get("step_id")
        if step == "user":
            status, flow = _http_post(
                f"{ha_url}/api/config/config_entries/flow/{flow_id}",
                json_body={}, headers=headers, timeout=15,
            )
            step = flow.get("step_id")
        if step != "manual":
            return f"unexpected-step:{step}"
        status, flow = _http_post(
            f"{ha_url}/api/config/config_entries/flow/{flow_id}",
            json_body={"url": location}, headers=headers, timeout=20,
        )
        return "ok" if flow.get("type") == "create_entry" else "not-created"
    finally:
        # A created entry's flow is already gone; DELETE then 404s, which is
        # harmless.  A half-flow is removed so the next run starts clean.
        try:
            import urllib.request as _ur
            req = _ur.Request(
                f"{ha_url}/api/config/config_entries/flow/{flow_id}",
                headers=headers, method="DELETE",
            )
            with _no_proxy_opener().open(req, timeout=10) as _resp:
                pass
        except Exception:
            pass


def _no_proxy_opener():
    """urllib opener that ignores HTTP(S)_PROXY — LAN calls must not detour."""
    import urllib.request as _ur
    return _ur.build_opener(_ur.ProxyHandler({}))


def _dlna_default_speaker(token: str, ha_url: str) -> str:
    """Read HA's chosen default from its input helpers; '' when unset."""
    empties = ("unset", "unknown", "unavailable", "none", "")
    try:
        st, ent = _http_get(
            f"{ha_url}/api/states/input_select.homeant_dlna_speaker",
            headers={"Authorization": f"Bearer {token}"}, timeout=5,
        )
        if st == 200 and ent.get("state") not in empties:
            return str(ent["state"])
        st, ent = _http_get(
            f"{ha_url}/api/states/input_text.homeant_dlna_speaker",
            headers={"Authorization": f"Bearer {token}"}, timeout=5,
        )
        if st == 200 and ent.get("state") not in empties:
            return str(ent["state"])
    except Exception:
        pass
    return ""


def _dlna_entity_id(token: str, ha_url: str, name: str) -> str:
    """Find the media_player entity HA made for a named renderer, best effort."""
    if not name:
        return ""
    try:
        st, states = _http_get(
            f"{ha_url}/api/states",
            headers={"Authorization": f"Bearer {token}"}, timeout=10,
        )
    except Exception:
        return ""
    if st != 200 or not isinstance(states, list):
        return ""
    for ent in states:
        if not isinstance(ent, dict):
            continue
        eid = str(ent.get("entity_id") or "")
        if not eid.startswith("media_player."):
            continue
        attrs = ent.get("attributes") or {}
        if str(attrs.get("friendly_name") or "") == name:
            return eid
    return ""


def _dlna_set_default(token: str, ha_url: str, entity: str) -> bool:
    """Set HA's default speaker through its own script, never by poking state."""
    try:
        st, _body = _http_post(
            f"{ha_url}/api/services/script/homeant_dlna_select",
            json_body={"speaker": entity},
            headers={"Authorization": f"Bearer {token}"}, timeout=10,
        )
        return st in (200, 201)
    except Exception:
        return False


def _dlna_discover(token: str, progress: bool = True,
                   enrol: bool = True) -> None:
    """Scan and print every MediaRenderer; create entries only when asked to.

    `start` enrols (`enrol=True`) because a fresh install has no entries yet.
    `status` does not (`enrol=False`): it is a read-only diagnostic, so it must
    neither create config entries nor change the default speaker.  A renderer
    whose line carries no entity suffix is simply not enrolled yet — that is
    the fact `status` is here to show, not something to fix on the spot.
    Both show dots while waiting, and enrolment stays idempotent either way:
    HA's dlna_dmr flow keys entries by UDN.
    """
    ha_url = f"http://127.0.0.1:{PORT}"
    locations = _dlna_scan(progress=progress)
    if not locations:
        log("dlna: no renderer answered — enable DLNA in the app")
        return
    # `status` skips this read on purpose: it is only needed to decide whether
    # to enrol, and a diagnostic should not spend a request on a write path.
    known = _dlna_existing_udns(token, ha_url) if enrol else set()
    seen: set[str] = set()
    found: list[tuple[str, str, str]] = []
    for location, ip in locations.items():
        # The description gives us the name and UDN; the integration re-fetches
        # it itself when its config flow connects to the device.
        try:
            import urllib.request as _ur
            req = _ur.Request(location, headers={"Accept": "text/xml"})
            with _no_proxy_opener().open(req, timeout=5) as resp:
                info = _dlna_device_info(resp.read().decode("utf-8", "replace"))
        except Exception:
            info = None
        if info is None:
            continue
        udn = info.get("udn") or location
        if udn in seen:
            continue
        seen.add(udn)
        if enrol and udn not in known \
                and _dlna_enrol_one(token, ha_url, location) == "ok":
            known.add(udn)
        name = info.get("friendly_name") or udn
        entity = _dlna_entity_id(token, ha_url, name)
        found.append((name, ip, entity))
        log(f"dlna: {name} @ {ip}"
            + (f" ({entity})" if entity else ""))
    default = _dlna_default_speaker(token, ha_url)
    # One renderer and no choice yet: make it the default through HA's own
    # script.  An existing choice is never overwritten, and `status` never
    # writes at all — it only reports what the helpers already hold.
    if enrol and not default and len(found) == 1 and found[0][2]:
        only = found[0][2]
        if _dlna_set_default(token, ha_url, only):
            default = only
            log(f"dlna: only one renderer — set default to {only}")
    log(f"dlna: default speaker {default}" if default
        else "dlna: none selected — call HomeAntDLNASelect to choose one")


def _login(username: str, password: str) -> str | None:
    """HA login flow → Bearer access_token (the user must already exist).

    The owner is provisioned offline by `_ensure_auth_offline()` while hass is
    stopped, so a plain login flow is all we need here: no
    POST /api/onboarding/users (that view is not even registered once the
    onboarding `user` step is marked done).
    """
    ha_url = f"http://127.0.0.1:{PORT}"
    # IndieAuth identity is a different concern from the dial address:
    # components/auth/indieauth.py requires client_id and redirect_uri to share
    # a netloc, and client_id is written into the persisted refresh token, so
    # re-keying it here would orphan tokens minted by older runs.  Nothing
    # dials this string — keeping the browser-facing name costs nothing and
    # leaves the OAuth callback stable.
    oauth_origin = f"http://localhost:{PORT}"
    client_id = oauth_origin + "/"
    redirect = f"{oauth_origin}/?auth_callback=1"

    status, body = _http_post(
        f"{ha_url}/auth/login_flow",
        json_body={"handler": ["homeassistant", None],
                   "client_id": client_id, "redirect_uri": redirect},
    )
    if status != 200:
        log(f"login_flow create failed: HTTP {status}")
        return None
    flow_id = body.get("flow_id")

    status2, body2 = _http_post(
        f"{ha_url}/auth/login_flow/{flow_id}",
        json_body={"client_id": client_id,
                   "username": username, "password": password},
    )
    # No raw-body dump here.  It printed HA's whole login-flow dict (flow_id,
    # data_schema, ...) and every word of it is noise to whoever is standing at
    # the console: the only fact they can act on is that the credential was
    # refused, and the caller states that in one line.
    if body2.get("type") != "create_entry":
        return None
    flow_code = body2.get("result")

    status3, body3 = _http_post(
        f"{ha_url}/auth/token",
        form_body={"grant_type": "authorization_code", "code": flow_code,
                   "client_id": client_id, "redirect_uri": redirect},
    )
    if status3 != 200:
        log(f"token exchange failed: HTTP {status3}")
        return None
    return body3.get("access_token")


def _get_access_token() -> str | None:
    """Admin bearer — only needed for the config flow."""
    return _login(cf("USERNAME", "admin"), cf("PASSWORD", "homeant"))


# ── xiaomi_home: silent config flow → OAuth URL ─────────────────────────────

def _xiaomi_already_configured() -> bool:
    """True only when a *live* xiaomi_home entry exists in core.config_entries.

    A disabled entry does not count: HA never loads it, so the integration is
    not actually working and the OAuth stage below still has to run.  Treating
    it as configured would print the MCP config and call the install done while
    xiaomi_home sits there doing nothing.
    """
    ce = HA_ROOT / ".storage" / "core.config_entries"
    if not ce.exists():
        return False
    try:
        data = json.loads(ce.read_text(encoding="utf-8"))
        return any(e.get("domain") == "xiaomi_home" and not e.get("disabled_by")
                   for e in data.get("data", {}).get("entries", []))
    except Exception:
        return False


def _xiaomi_step_payload(step_id: str) -> dict | None:
    """Hardcoded step payloads — we know exactly what xiaomi_home asks."""
    if step_id == "eula":
        return {"eula": cf("XIAOMI_EULA", True)}

    if step_id == "auth_config":
        return {
            "cloud_server": cf("XIAOMI_CLOUD_SERVER", "cn"),
            "integration_language": cf("XIAOMI_LANGUAGE", "zh-Hans"),
            "network_detect_config": cf("XIAOMI_NETWORK_DETECT", True),
        }

    if step_id == "network_detect_config":
        return {
            "network_detect_addr": "",
            "check_network_deps": True,
        }

    return None


# The flow a previous run left waiting: only its id is remembered, so the next
# run resumes that flow instead of starting a second one (see _xiaomi_live_flow).
XIAOMI_FLOW_FILE = HA_ROOT / ".xiaomi-flow"

# Every HTTP call touching that flow makes HA load the integration and probe the
# Xiaomi cloud, so 180s instead of the 10s `_http_post` default: a warm instance
# answers in ~7s, a cold one needs well over 10s, and the resulting TimeoutError
# is not an HTTPError — it used to escape `_http_post` and kill the run outright.
XIAOMI_FLOW_TIMEOUT = 180


def _xiaomi_flow_get(
    flow_id: str, token: str, timeout: float = 10.0
) -> tuple[int, dict | None]:
    """One flow by id: (HTTP status, the flow when hass still knows it).

    ``0`` means the request never got a usable answer — hass is not listening,
    or what answered spoke something other than JSON.  The two callers need
    that told apart differently (`start` rewrites the marker, `status` only
    reports), so this returns the status instead of a bare None and never
    touches the marker itself.
    """
    try:
        status, flow = _http_get(
            f"http://127.0.0.1:{PORT}/api/config/config_entries/flow/{flow_id}",
            headers={"Authorization": f"Bearer {token}"},
            timeout=timeout,
        )
    except (OSError, ValueError):
        return 0, None
    if status != 200 or not isinstance(flow, dict) or "flow_id" not in flow:
        return status, None
    return status, flow


def _xiaomi_live_flow(token: str) -> dict | None:
    """The flow a previous run left behind, if this hass still knows about it.

    Only the id is remembered, because HA offers no way to list in-progress
    flows: ``GET /api/config/config_entries/flow`` answers 405 (that path is
    POST-only) and there is no REST equivalent of the websocket list command.

    A pending flow does NOT survive a hass restart, so a 404 here is normal
    rather than exceptional — a stop + start spends its own flow every time.
    The id therefore only ever resolves when the service was left running,
    which is precisely the case this exists for.
    """
    try:
        flow_id = XIAOMI_FLOW_FILE.read_text(encoding="utf-8").strip()
    except OSError:
        return None
    if not flow_id:
        return None
    _, flow = _xiaomi_flow_get(flow_id, token)
    if flow is None:
        # Unreachable hass (status 0) lands here too: an id that cannot be
        # resolved is spent either way, and the next run starts a fresh flow.
        XIAOMI_FLOW_FILE.unlink(missing_ok=True)
        return None
    return flow


def _xiaomi_flow_state() -> str:
    """Where the flow in ``.xiaomi-flow`` is parked — read-only, best effort.

    ``"authorizing"`` — still on the OAuth step, the browser has not come back.
    ``"advancing"`` — the callback landed and hass moved the flow on to the
    ``homes_select`` form by itself, so only `start` answering it is missing.
    ``"lost"`` — hass does not know the id (restarted since), which makes the
    login page the user may still have open a dead end.
    ``"unknown"`` — no cached token, hass not listening, or a refusal: the
    caller falls back to the wording that covers both halves.

    The cached LLAT is used as-is — no login, no mint, no `_token_ok` probe —
    because a stale token only costs one 401 and the fallback line.  The short
    timeout keeps `status` from hanging on a wedged instance; the endpoint is a
    memory lookup, so a healthy one answers instantly.
    """
    try:
        flow_id = XIAOMI_FLOW_FILE.read_text(encoding="utf-8").strip()
        token = MCP_TOKEN_FILE.read_text(encoding="utf-8").strip()
    except OSError:
        return "unknown"
    if not flow_id or not token:
        return "unknown"
    status, flow = _xiaomi_flow_get(flow_id, token, timeout=3)
    if status == 404:
        return "lost"
    if flow is None:
        return "unknown"
    step = flow.get("step_id")
    if step == "oauth":
        return "authorizing"
    return "advancing" if step else "unknown"


def _oauth_pending_url(flow: dict) -> str | None:
    """The OAuth URL a flow is parked on, or None if there is not one."""
    placeholders = flow.get("description_placeholders") or {}
    m = re.search(r'href="([^"]+)"', placeholders.get("link_left", ""))
    return m.group(1) if m else None


def _xiaomi_answer(flow: dict) -> dict | None:
    """The payload that answers the step ``flow`` is parked on, or None."""
    step_id = flow.get("step_id")

    pre_oauth = _xiaomi_step_payload(step_id)
    if pre_oauth is not None:
        return pre_oauth

    if step_id == "homes_select":
        # Pick every home the account exposes.
        schema = flow.get("data_schema") or {}
        homes_opts: object = []
        if isinstance(schema, list):
            for field in schema:
                if isinstance(field, dict) and field.get("name") == "home_infos":
                    homes_opts = field.get("default") or field.get("options") or []
                    break
        elif isinstance(schema, dict):
            hi = (schema.get("properties") or {}).get("home_infos", {})
            homes_opts = hi.get("default") or hi.get("options") or []

        if isinstance(homes_opts, dict):
            selected = list(homes_opts.keys())
        elif isinstance(homes_opts, list):
            selected = [h[0] if isinstance(h, (list, tuple)) else h for h in homes_opts]
        elif homes_opts:
            selected = list(homes_opts)
        else:
            selected = []
        return {"home_infos": selected, "area_name_rule": "room",
                "advanced_options": False}

    if step_id == "advanced_options":
        return {"advanced_options": False}

    return None


def _xiaomi_start_flow(token: str) -> dict | None:
    """Create a xiaomi_home config flow; returns its first state.

    The POST makes HA load the integration and probe the Xiaomi cloud, which is
    why it gets XIAOMI_FLOW_TIMEOUT rather than the 10s default — see the note
    there for what happens when a timeout shorter than the load is used.
    """
    status, flow = _http_post(
        f"http://127.0.0.1:{PORT}/api/config/config_entries/flow",
        json_body={"handler": "xiaomi_home"},
        headers={"Authorization": f"Bearer {token}"},
        timeout=XIAOMI_FLOW_TIMEOUT,
    )
    if status != 200 or "flow_id" not in flow:
        log(f"flow start failed: HTTP {status}")
        return None
    log("xiaomi_home: config flow started")
    return flow


# The one sentence a refusal produces.  Deliberately not a diagnosis and not a
# pointer at a log: every refusal seen so far was ours — a shim loop, a venv
# missing the integration's own requirements, a Windows root store short of the
# chain's anchor — and all three are fixed here rather than handed back to the
# reader.  The command that retries goes on its own line below (log_run), not on
# the end of this sentence.
_XIAOMI_REFUSED = "the Xiaomi integration refused the answer homeant sent it"


def _xiaomi_walk(token: str, flow: dict) -> tuple[str, str | None, str | None]:
    """Answer steps until the flow finishes or needs a human.

    Returns ``("done" | "waiting" | "failed", oauth_url, why)``.  ``waiting`` is
    not a timeout: the flow is parked on the OAuth step and only a browser can
    move it, so the caller reports pending and the next run resumes from right
    here.  ``why`` is a sentence with the fix in it, or None — the caller puts
    it on the FAIL line so the reader never has to hunt for it in the log.
    """
    ha_url = f"http://127.0.0.1:{PORT}"
    headers = {"Authorization": f"Bearer {token}"}
    flow_id = flow["flow_id"]

    for _ in range(20):
        ftype = flow.get("type")
        step_id = flow.get("step_id")

        if ftype == "create_entry":
            log("xiaomi_home: config entry created")
            return "done", None, None
        if ftype == "abort":
            reason = flow.get("errors") or flow.get("abort_reason") or "unknown"
            log(f"xiaomi_home: flow aborted — {reason}")
            return "failed", None, (
                "the integration aborted its setup before the end")
        if step_id == "oauth":
            url = _oauth_pending_url(flow)
            if not url:
                log("xiaomi_home: no OAuth URL found")
                return "failed", None, (
                    "the flow reached the login step but produced no URL to "
                    "open")
            return "waiting", url, None

        payload = _xiaomi_answer(flow)
        if payload is None:
            log(f"xiaomi_home: unknown step '{step_id}' — aborting")
            return "failed", None, (
                "the flow asked for a step this tool does not answer")

        # Same timeout as flow creation: answering a step can also reach the
        # Xiaomi cloud (the miot login).
        status, flow = _http_post(
            f"{ha_url}/api/config/config_entries/flow/{flow_id}",
            json_body=payload, headers=headers,
            timeout=XIAOMI_FLOW_TIMEOUT,
        )
        if status != 200:
            log(f"xiaomi_home: step '{step_id}' rejected — HTTP {status}")
            return "failed", None, (
                f"the core rejected that step (HTTP {status})")

        # A form that comes back carrying a *non-empty* `errors` value is the
        # integration refusing the answer; re-posting it cannot succeed, so stop
        # and report.  An *empty* value is not a verdict: every form is shown
        # with `errors={'base': ''}` the first time, and a step that advances
        # hands back the next form the same way — reading that as a refusal
        # aborted setup on the very first answer.
        refused = next(
            (str(v) for v in (flow.get("errors") or {}).values() if str(v)), "")
        if refused:
            return "failed", None, _XIAOMI_REFUSED

    log("xiaomi_home: flow did not settle after 20 steps")
    return "failed", None, "the flow did not finish within 20 steps"


def _open_oauth_url(url: str) -> bool:
    """Give the flow's OAuth URL to a browser, if one can be reached.

    Returns True when the caller still has to print the URL:
      * headless Linux — no DISPLAY/WAYLAND, so a launch attempt would only
        hand the URL to a console browser and steal the terminal (see
        has_desktop).
      * anything else — a ``webbrowser.open`` that returned False (no browser
        installed / X11 forwarding that leads nowhere).

    False means the browser took it and there is nothing left to show.  The
    URL is never lost either way.
    """
    if not has_desktop():
        return True
    if webbrowser.open(url):
        log("opened browser → OAuth login")
        return False
    return True


def _xiaomi_advance() -> tuple[str, str | None, str | None]:
    """Move xiaomi_home setup as far as one run can, without ever waiting.

    Returns ``(state, url, why)``: ``state`` is ``"done"``, ``"waiting"``,
    ``"rejected"`` or ``"failed"`` — the caller turns each into one of the three
    printed states — ``url`` is the OAuth link to print, or None when it was
    already handed to a browser, and ``why`` is the sentence to put on a FAIL
    line, or None when the caller's own branch already explains it.

    Polling for the OAuth callback (the old shape, up to 600s) bought nothing:
    the user may take as long as they like between opening the URL and
    finishing the login.  So instead of waiting, each
    run picks up the flow the previous one left behind — the browser comes back
    to that flow's webhook — and advances it wherever it stopped: ``homes_select``
    and ``advanced_options`` are answered here, no human needed.  Only when there
    is no live flow does a new one get started.  Re-running IS the retry.
    """
    token = _get_access_token()
    if not token:
        # "rejected": the offline provisioning above is supposed to guarantee a
        # working credential, so a rejected login means the cfg is wrong — the
        # caller turns it into a FAIL naming the file.  `_login` already logged
        # HA's own reason, and nothing asks the user to open the web UI.
        return "rejected", None, None
    try:
        # A flow left pending by an earlier run owns the webhook the user's
        # browser is going to hit, so it is resumed first — a second flow would
        # never receive that callback and the entry would never appear.
        flow = _xiaomi_live_flow(token)
        if flow is not None:
            log("xiaomi_home: resuming the flow from the previous run")
        else:
            flow = _xiaomi_start_flow(token)
            if flow is None:
                return "failed", None, (
                    "the integration did not start a setup flow")
            XIAOMI_FLOW_FILE.write_text(flow["flow_id"], encoding="utf-8")

        state, url, why = _xiaomi_walk(token, flow)
        if state == "waiting":
            # The browser gets first refusal; printing is the fallback, not the
            # other way round.  Whatever it hands back unconsumed is the
            # caller's to show after its own PENDING line.
            if url and not _open_oauth_url(url):
                url = None
            return state, url, None
        # done or failed — either way the id is spent, and keeping it would
        # make the next run chase a flow that will never move again.
        XIAOMI_FLOW_FILE.unlink(missing_ok=True)
        return state, None, why
    finally:
        # The admin bearer ends here: revoke this login's refresh token so no
        # admin credential outlives the run, while every other token of the
        # account stays intact — the browser session must survive.
        _ws_purge_normal(token)






# ── MCP: auth provisioning + token cache (zero-dep) ─────────────────────────

MCP_TOKEN_FILE = HA_ROOT / ".mcp-token"
LLAT_CLIENT_NAME = "HomeAnt"
LLAT_LIFESPAN_DAYS = 3650
# Two constants, two jobs — deliberately not derived from one another, and the
# names say which side each one serves.
#
# MCP_PROBE_BASE is what this tool itself probes (token check, core RUNNING
# gate, MCP endpoint probe).  It stays loopback on purpose, for two reasons:
# the facts under test are server-side (is the route registered, does the
# token answer), and loopback is the one address that is always present —
# homeant_mdns publishes the .local records only once the core reports
# RUNNING, so resolving a hostname here would depend on the thing it awaits.
# Whether this box can resolve MCP_HOSTNAME says nothing about clients and is
# deliberately never tested.
#
# MCP_CLIENT_URL is what the user pastes into a client.  It uses MCP_HOSTNAME
# — the short alias homeant_mdns advertises — and resolving it is the
# client's job: Windows/macOS do it natively, a Linux client needs
# libnss-mdns or the server's LAN IP.  None of that can be verified from the
# server side.
MCP_PROBE_BASE = f"http://127.0.0.1:{PORT}"
MCP_CLIENT_URL = f"http://{MCP_HOSTNAME}:{PORT}/api/mcp"

# ── offline auth provisioning (hass stopped) ────────────────────────────────
# HA exposes no public "create user + password" API, so the owner account is
# produced the way HA's own onboarding view does it
# (components/onboarding/views.py: add_auth -> create_user -> link_user), but
# with hass stopped and the stores written in one go.
#
# The owner is the only account we create: it signs in for the Xiaomi OAuth
# flow *and* owns the MCP token.  A second non-admin user bought nothing —
# `auth/long_lived_access_token` mints for whoever is calling, so the extra
# account only sat there while a second credential pair had to be kept in the
# config file for it.
#
# Safety: append-only (never rewrites an existing user/credential); the stores
# are Store(atomic_writes=True); .bak copies are restored on failure.  Worst
# case is a credential without a user — the next login creates it
# (recoverable).  The owner entry itself is never modified.

AUTH_STORE = HA_ROOT / ".storage" / "auth"
PROVIDER_STORE = HA_ROOT / ".storage" / "auth_provider.homeassistant"
ONBOARDING_STORE = HA_ROOT / ".storage" / "onboarding"
OWNER_NAME = "HomeAnt"


def _auth_doc() -> dict:
    """Parsed ``.storage/auth`` → its ``data`` mapping, or ``{}``.

    Never raises: every caller is a gate, and a gate that cannot read its own
    evidence has to answer "not satisfied" rather than take the process down.
    """
    try:
        return json.loads(AUTH_STORE.read_text(encoding="utf-8")).get("data") or {}
    except (OSError, json.JSONDecodeError, AttributeError):
        return {}


def _admin_state() -> dict:
    """Where the cfg USERNAME credential sits → ``{owner, linked, holder}``.

    Read from the same JSON as every other probe, so an install whose owner
    account has no way to sign in is visible *before* hass starts.  That state
    used to be indistinguishable from "configured", which is how every run
    ended up asking the user to add the integration by hand.

    ``holder`` names a *non-owner* user the username is already bound to: we
    refuse to take that account over rather than hand admin rights to whoever
    happens to own the name.
    """
    data = _auth_doc()
    users = {u.get("id"): u for u in (data.get("users") or [])}
    owner_id = next((uid for uid, u in users.items() if u.get("is_owner")), None)
    state = {"owner": owner_id is not None, "linked": False, "holder": None}
    username = cf("USERNAME", "admin")
    for c in (data.get("credentials") or []):
        if (c.get("data") or {}).get("username") != username:
            continue
        uid = c.get("user_id")
        if uid and uid == owner_id:
            state["linked"] = True
        elif uid in users:
            state["holder"] = users[uid].get("name")
        break
    return state


def _provider_has_user(username: str) -> bool:
    """True when ``username`` exists in the store that holds the passwords.

    ``.storage/auth`` only lists users and credential links; the bcrypt secret
    lives in ``.storage/auth_provider.homeassistant``.  An install where the
    first exists but the second does not is *half provisioned*: every gate reads
    "configured", provisioning gets skipped, and the login then fails with
    ``invalid_auth`` — which HA returns both for an unknown user and for a wrong
    password, so the two causes cannot be told apart from the API alone.

    Unreadable store answers False: a gate that cannot read its own evidence has
    to say "not satisfied" rather than take the process down.
    """
    try:
        doc = json.loads(PROVIDER_STORE.read_text(encoding="utf-8"))
        users = (doc.get("data") or {}).get("users") or []
    except (OSError, json.JSONDecodeError, AttributeError):
        return False
    return any((u or {}).get("username") == username for u in users)


def _admin_pw_agrees(username: str, password: str) -> bool | None:
    """Does ``password`` match what ``PROVIDER_STORE`` holds for ``username``?

    Read straight off the store, because the answer is needed *before* hass can
    be asked: HA answers ``invalid_auth`` both for "no such user" and for "wrong
    password", and the reset has to be decided while hass is still stopped.

    Tri-state on purpose — ``True`` / ``False`` / ``None`` (store unreadable,
    user unknown, hash malformed).  ``None`` must never trigger a reset: a gate
    that cannot read its own evidence abstains rather than overwrite a password.

    Mirrors ``Data.validate_login`` in HA 2026.11.1: usernames compare
    ``strip().casefold()``, the stored value is *base64 of the bcrypt hash*, and
    the password is cut to 72 bytes because bcrypt 5 raises past that length.
    """
    try:
        doc = json.loads(PROVIDER_STORE.read_text(encoding="utf-8"))
        users = (doc.get("data") or {}).get("users") or []
    except (OSError, json.JSONDecodeError, AttributeError):
        return None
    want = username.strip().casefold()
    stored = None
    for user in users:
        user = user or {}
        if str(user.get("username", "")).strip().casefold() == want:
            stored = user.get("password")
            break
    if not stored:
        return None
    try:
        # Imported here, not at module scope: bcrypt is only needed by the one
        # call that has an owner account to check, and `--help` must stay cheap.
        import base64

        import bcrypt
        return bcrypt.checkpw(password.encode()[:72], base64.b64decode(stored))
    except Exception:  # noqa: BLE001 — bad base64/hash or missing bcrypt: abstain
        return None


def _admin_ready() -> bool:
    """True when cfg USERNAME can sign in as the owner.

    All three stores must agree, not just two: ``.storage/auth`` carries the
    owner plus the credential link, while the bcrypt secret lives in
    ``.storage/auth_provider.homeassistant``.  Checking only the former made a
    half-provisioned install look ready — provisioning was skipped and every
    later login failed.

    Structure only — owner, credential link, and a row in the password store.
    Whether the stored secret still equals ``PASSWORD`` is a separate question
    (`_admin_pw_agrees`), asked by the caller that can act on the answer: this
    predicate is also what `status` and the MCP gate read, and those must not
    start a password rewrite as a side effect.
    """
    if not _provider_has_user(cf("USERNAME", "admin")):
        return False
    state = _admin_state()
    return bool(state["owner"] and state["linked"])


# Mirrors homeassistant.components.onboarding.const.STEPS (HA 2026.10.1:
# user / core_config / integration / analytics).  ALL of them must be marked
# done for HA to treat onboarding as finished — only then does the onboarding
# component's async_setup early-return and deregister /api/onboarding, which
# is what lets the browser skip the wizard and land on the dashboard.  Marking
# just `user` (old behavior) left the other three pending, so /api/onboarding
# kept returning 200 and the frontend got stuck re-checking status instead of
# auto-configuring.
ONBOARDING_STEPS = ("user", "core_config", "integration", "analytics")

# Shape HA's OnboardingStorage persists; keep the major version in sync with
# homeassistant.components.onboarding (STORAGE_VERSION / STORAGE_KEY).
_ONBOARDING_STORE_VERSION = 4
_ONBOARDING_STORE_MINOR = 1


def _mark_onboarding_user_done() -> None:
    """Mark every onboarding step done once an owner exists.

    The repo seed deliberately leaves the onboarding store untouched so a
    *failed* provisioning still leaves the browser onboarding wizard usable
    (HA registers /api/onboarding/users only for steps that are not done).
    Once an owner does exist we mark all steps done — otherwise the wizard
    would either offer to create a second admin account or, with only `user`
    done, get stuck re-checking status instead of redirecting to the dashboard.
    """
    if not AUTH_STORE.exists():
        return
    try:
        doc = json.loads(ONBOARDING_STORE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        doc = None
    if doc is None:
        # Fresh install: HA has not persisted the onboarding store yet, so
        # create it pre-completed.  If we skip this, HA derives
        # {"done":["user"]} on first start and the wizard/stuck-state stays
        # active.
        doc = {
            "version": _ONBOARDING_STORE_VERSION,
            "minor_version": _ONBOARDING_STORE_MINOR,
            "key": "onboarding",
            "data": {"done": list(ONBOARDING_STEPS)},
        }
        tmp = ONBOARDING_STORE.with_name(ONBOARDING_STORE.name + ".tmp")
        tmp.write_text(json.dumps(doc, indent=2), encoding="utf-8")
        os.replace(tmp, ONBOARDING_STORE)
        log("onboarding: created store with all steps done")
        return
    done = doc.setdefault("data", {}).setdefault("done", [])
    added = [s for s in ONBOARDING_STEPS if s not in done]
    if not added:
        return
    done.extend(added)
    tmp = ONBOARDING_STORE.with_name(ONBOARDING_STORE.name + ".tmp")
    tmp.write_text(json.dumps(doc, indent=2), encoding="utf-8")
    os.replace(tmp, ONBOARDING_STORE)
    log(f"onboarding: marked steps done: {', '.join(added)}")


def _provision_auth() -> bool:
    """Run HA's auth stack in-process (hass stopped) and create the owner."""
    import asyncio
    import logging

    from homeassistant import runner
    from homeassistant.auth import auth_manager_from_config
    from homeassistant.auth.const import GROUP_ID_ADMIN
    from homeassistant.auth.providers.homeassistant import InvalidAuth
    from homeassistant.config_entries import ConfigEntries
    from homeassistant.core import HomeAssistant
    from homeassistant.helpers import device_registry as _dr, entity_registry as _er

    admin_name = cf("USERNAME", "admin")
    admin_pw = cf("PASSWORD")
    if not admin_pw:
        # `_ensure_auth_offline` refuses an empty cfg before getting here, so
        # this is a backstop: a default would mean provisioning a password
        # nobody chose, on the one account that can do everything.
        log_state("FAIL", f"PASSWORD is empty in {CONFIG_FILE.name} — "
                          f"refusing to provision the owner")
        return False

    async def _ensure_credential(hass, provider, username: str, password: str) -> None:
        """Make cfg's value the one that actually works.

        The provider can only *add* a password, never align one — so a cfg
        edited after the account existed (or a password changed in the HA UI)
        left the two sides permanently out of step, and every later login failed
        with a message that names both sides but can fix neither.  ``cfg`` is
        the declared authority for this credential, so a mismatch is reset here
        rather than reported.  Only a *verified* mismatch is reset: anything the
        check cannot decide is left alone.

        Adding and resetting leave the same state — the account now uses the
        value in cfg — but they are not the same news: an account created just
        now is the expected first run, while a reset means something had
        drifted.  Only the second one warns.  The value itself is never echoed
        — it is in cfg, one `grep PASSWORD=` away, and a journal line is the
        wrong place for a secret.

        ``hass`` is passed in because this is defined outside ``_run``: the
        instance only exists inside it, and reaching for the name by closure
        would raise at the first mismatch (measured 12:44 — the whole provision
        pass then failed, and the restore-copy silently undid nothing).
        """
        known = {(u or {}).get("username")
                 for u in (provider.data.users if provider.data else [])}
        if username in known:
            try:
                await hass.async_add_executor_job(
                    provider.data.validate_login, username, password)
                return                   # cfg and the stored hash already agree
            except InvalidAuth:
                pass
            await provider.async_change_password(username, password)
            # Only a *drift* is worth a warning: the account already existed and
            # its password was moved.  The value itself is never echoed.
            log(f"WARN  password for '{username}' was reset to the value in "
                f"{CONFIG_FILE.name}")
        else:
            # First run on this box: there is nothing to reset, and a WARN on a
            # brand-new install reads as if something went wrong.  The caller
            # prints the one line that matters ("auth: created owner ...").
            await provider.async_add_auth(username, password)

    async def _run() -> bool:
        hass = HomeAssistant(str(HA_ROOT))
        hass.config_entries = ConfigEntries(hass, {})
        await hass.config_entries.async_initialize()
        _dr.async_setup(hass)
        await asyncio.gather(_dr.async_load(hass), _er.async_load(hass))
        hass.auth = await auth_manager_from_config(
            hass, [{"type": "homeassistant"}], [])
        provider = hass.auth.auth_providers[0]
        await provider.async_initialize()

        users = await hass.auth.async_get_users()
        owner = next((u for u in users if u.is_owner), None)

        # Unconditional, not only when the owner is new: an owner can exist with
        # no password on this provider at all — provisioned by an earlier build,
        # or created through the browser wizard — and that is exactly the state
        # in which every later run failed to log in and handed the job back to
        # the user.  It adds when the row is missing and aligns it to cfg when
        # the stored hash no longer matches; a row that already agrees is not
        # touched.
        await _ensure_credential(hass, provider, admin_name, admin_pw)
        admin_cred = await provider.async_get_or_create_credentials(
            {"username": admin_name})
        if owner is None:
            owner = await hass.auth.async_create_user(
                OWNER_NAME, group_ids=[GROUP_ID_ADMIN])
            await hass.auth.async_link_user(owner, admin_cred)
            log(f"auth: created owner {admin_name}"
                + ("" if owner.is_owner else " (WARNING: is_owner=False)"))
        else:
            # No-op when the credential already belongs to this owner.  A raise
            # for a *different* holder is unreachable from here: the only caller
            # refuses that case out of the JSON before this function is entered.
            await hass.auth.async_link_user(owner, admin_cred)

        # hass was never started, so async_stop() early-returns on
        # CoreState.not_running and never fires FINAL_WRITE — the delayed
        # auth-store save would be lost.  Fire it by hand and let every Store
        # with a pending write flush (that is exactly what it is for).
        from homeassistant.const import EVENT_HOMEASSISTANT_FINAL_WRITE

        hass.bus.async_fire_internal(EVENT_HOMEASSISTANT_FINAL_WRITE)
        await hass.async_block_till_done()
        # Default logger prints a wall of shutdown noise; keep it quiet.
        logging.getLogger("homeassistant.core").setLevel(logging.WARNING)
        await hass.async_stop(force=True)
        return True

    try:
        return asyncio.run(_run(), loop_factory=runner.create_event_loop)
    except TypeError:               # loop_factory kwarg needs py>=3.12
        return asyncio.run(_run())


def _ensure_admin_password() -> None:
    """Make sure ``PASSWORD`` in cfg holds a value; cfg is the only authority.

    Writes and says nothing.  The one line that reports this belongs to the pass
    that actually applies the value (`_ensure_credential`), and it never repeats
    the password — printing here as well produced three lines for one event
    ("cfg was empty", "here is the password", "the account was reset to it"),
    which reads like three problems.

    Two cases, and both write when cfg has none:

      ① cfg empty, account absent  → generate 16 chars, write back
      ② cfg empty, account present → generate anyway.  An account carrying a
         password set in the HA UI is *not* a reason to leave cfg empty: the
         MQTT credential already works this way (its files are rebuilt from cfg
         on every start), and a cfg that stays empty while the store holds a
         secret has no way to say what the password is.  The UI value therefore
         gets replaced by the generated one on the next provisioning pass.

    A cfg that already has a value is left untouched by this function; whether
    the stored hash still matches it is decided in `_ensure_auth_offline`, where
    the reset can actually be performed (and where hass is known to be stopped).
    """
    if cf("PASSWORD"):
        return

    pw = _gen_password()
    if not _cfg_set("PASSWORD", pw):
        log_state("FAIL", f"cannot save the generated admin password to "
                          f"{CONFIG_FILE.name} — set PASSWORD= by hand")
        return
    return pw


# ── MQTT broker (amqtt) ──────────────────────────────────────────────────────
#
# The broker is a child of this product, not a service of the OS: every
# platform would need its own registration, and the lifecycle it has to obey is
# hass's, not the boot's.  `homeant start` brings it up before hass, `homeant
# stop` takes it down after hass, and everything else lives under HA_ROOT and is
# rewritten on every start:
#
#   mqtt.yaml      broker config (regenerated: the listener may have changed)
#   .mqtt.pid      who we started (only proof of "ours" before a kill)
#
# The account the broker accepts is not a file of ours any more: it is HA's own
# mqtt config entry, read by config/runtime/homeant_mqtt_auth.py at connection
# time.  That is what lets the user change it in the UI — HA's reconfigure form
# connects with the new credentials *before* saving, which a start-up snapshot
# would always refuse.
#
# No log file: the broker's streams go to devnull like every other line this
# layer does not own.  A broker that fails to start names the command to run by
# hand instead, which is where its reason is actually readable.
#
# A broker the user installed themselves is never touched: the pid is validated
# against a command line that carries both "amqtt" and *our* config path before
# any signal is sent, and nothing is ever matched by process name.

MQTT_DEFAULT_PORT = 1883
# Username of the account `start` provisions into the mqtt config entry.  Not a
# cfg key: it is not a secret, it is not per-machine, and the entry is where it
# is edited from now on.
MQTT_ENTRY_USER = "mqtt"
# How long the listener gets to accept before the start is called failed.  The
# measured cold start is under a second; this is a ceiling for a slow disk, not
# a target — amqtt either binds quickly or dies with a traceback we then show.
MQTT_ACCEPT_TIMEOUT = 10.0


def _mqtt_paths() -> dict[str, Path]:
    """Derived per call, not module-level: tests rebase HA_ROOT."""
    return {
        "conf": HA_ROOT / "mqtt.yaml",
        "pid": HA_ROOT / ".mqtt.pid",
    }


def _mqtt_conf() -> dict:
    """The two cfg keys, typed and stripped; defaults mirror the template."""
    return {
        "listen": str(cf("MQTT_LISTEN", "0.0.0.0") or "").strip(),
        "port": cf("MQTT_PORT", MQTT_DEFAULT_PORT),
    }


def _mqtt_is_loopback(host: str) -> bool:
    return host in ("127.0.0.1", "localhost", "::1")


def _mqtt_gate() -> str | None:
    """Reject a listener the plugin or the transport cannot serve.

    The old shape of this gate was "refuse a non-loopback bind without
    credentials", because amqtt is happy to start with no authentication plugin
    at all and then lets in anything that reaches 1883.  That state cannot exist
    any more: `_mqtt_conf_text` always mounts the authentication plugin, and that
    plugin answers False for every connection it cannot verify — an amqtt
    listener with no plugin loaded refuses every session too (`broker.py`
    `_authenticate` returns False when no plugin answered).  What is left to
    check here is the shape of the two values, which a hand-edited cfg can still
    get wrong.
    """
    c = _mqtt_conf()
    if not isinstance(c["port"], int) or not 0 < c["port"] < 65536:
        return f"MQTT_PORT '{cf('MQTT_PORT')}' is not a valid TCP port"
    if ":" in c["listen"]:
        # `bind` below is a plain host:port pair; IPv6 would need brackets, and
        # nothing here has ever used that form.  Say so instead of shipping a
        # half-supported one.
        return (f"MQTT_LISTEN '{c['listen']}' must be an IPv4 address "
                f"(no port, no IPv6)")
    return None


def _mqtt_conf_text() -> str:
    """The broker YAML exactly as cfg implies it.

    One source for the bytes: the file is written from this and compared
    against this, so "already up to date" can never mean something different
    from "what we would write".  Deterministic on purpose — no timestamp, no
    absolute path, no random salt — which is what makes the comparison
    meaningful across restarts *and* what lets this file ship unchanged to
    another machine: ``storage_dir`` is relative to HA_ROOT, which the broker
    child is told about through HOMEANT_HA_ROOT.
    """
    c = _mqtt_conf()
    return (
        "# Generated by homeant from homeant.cfg on every start — do not edit.\n"
        "listeners:\n"
        "  default:\n"
        "    type: tcp\n"
        f"    bind: {c['listen']}:{c['port']}\n"
        "plugins:\n"
        # Underscore, not the dash spelling amqtt's docs use elsewhere: dacite
        # matches keys against the plugin's dataclass fields with strict=True,
        # and a dash is an unexpected field (measured: PluginLoadError).
        "  homeant_mqtt_auth.HomeAntAuthPlugin:\n"
        "    storage_dir: .storage\n"
        "  amqtt.plugins.sys.broker.BrokerSysPlugin:\n"
        "    sys_interval: 20\n"
    )


def _mqtt_write_conf() -> bool:
    """Write the broker YAML: one listener, file auth, $SYS every 20s."""
    p = _mqtt_paths()["conf"]
    text = _mqtt_conf_text()
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text, encoding="utf-8")
    except OSError as e:
        log_state("FAIL", f"cannot write {p.name} — {e}")
        return False
    return True


def _mqtt_derived_why() -> str:
    """Why the file the broker reads is out of step; '' when it is not.

    "The process is alive" is a weaker claim than "it serves what cfg says":
    mqtt.yaml is derived from cfg and amqtt reads it exactly once at start-up,
    so a broker left over from another release — or from a cfg edited since —
    keeps serving the old listener for the rest of its life.  Comparing what
    would be written against what is on disk is what tells the two apart, and it
    is the same rule hass's own half uses: skip the work while the fingerprint
    matches, act only when it stops matching.

    The credentials deliberately do not appear here: they live in HA's mqtt
    entry and the plugin reads them per connection, so a password change needs
    no broker restart at all.
    """
    try:
        on_disk = _mqtt_paths()["conf"].read_text(encoding="utf-8")
    except OSError:
        return "mqtt.yaml is missing"
    if on_disk != _mqtt_conf_text():
        return "mqtt.yaml differs from cfg"
    return ""


def _mqtt_pid_raw() -> int | None:
    """The number in .mqtt.pid, without any claim about what it now names.

    Only the first whitespace-separated field is the pid: the file also carries
    the process's creation time (see ``_mqtt_pid_stamp``), and a file written by
    a build that predates that column still reads correctly here.
    """
    try:
        return int(_mqtt_paths()["pid"].read_text(encoding="utf-8").split()[0])
    except (OSError, ValueError, IndexError):
        return None


def _mqtt_pid_stamp() -> float | None:
    """Creation time recorded next to the pid, or None when the file has none.

    This is the PID-reuse guard that costs no privilege.  A number in a file
    proves nothing after a reboot; a number plus the moment that process was
    created proves it is still the same process, because a recycled pid always
    carries a later creation time.  Files written by an older build carry no
    stamp — those are still checked against the listener topology below, just
    without this extra lock on the number.
    """
    try:
        fields = _mqtt_paths()["pid"].read_text(encoding="utf-8").split()
    except OSError:
        return None
    if len(fields) < 2:
        return None
    try:
        return float(fields[1])
    except ValueError:
        return None


def _proc_cmdline(pid: int) -> str:
    """Best-effort command line of `pid`; '' when it cannot be read.

    Windows goes through psutil, which is already in this tree as an amqtt
    dependency and asks the kernel rather than starting a helper program.  The
    obvious helper, ``wmic``, is deprecated and — measured on this machine — on
    the security policy's program blacklist, where an attempt to launch it gets
    the whole process tree torn down.  A helper that may refuse to start is not
    something a kill path can be built on.
    """
    if IS_WIN:
        try:
            import psutil
        except ImportError:
            return ""
        try:
            return " ".join(psutil.Process(pid).cmdline())
        except (psutil.Error, OSError):
            return ""
    try:
        raw = Path(f"/proc/{pid}/cmdline").read_bytes()
        return raw.replace(b"\x00", b" ").decode("utf-8", "replace")
    except OSError:
        pass
    # macOS has no /proc; ps is the one portable answer left.
    try:
        r = subprocess.run(["ps", "-p", str(pid), "-o", "args="],
                           capture_output=True, text=True, timeout=5)
        return (r.stdout or "").strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def _proc_identity(pid: int) -> tuple[str, float] | None:
    """Image name and creation time of ``pid``, or None when unreadable.

    These two facts are why ownership can still be decided from a plain user's
    prompt.  Measured 11-16 on Windows under a restricted token, with the target
    owned by LocalSystem: ``cmdline`` raises AccessDenied while ``name``,
    ``ppid``, ``create_time``, ``children`` and ``net_connections`` all read
    fine.  ``create_time`` is psutil's own documented answer to PID reuse, and
    unlike a command line it needs no elevation.
    """
    try:
        import psutil
    except ImportError:
        return None
    try:
        p = psutil.Process(pid)
        return p.name(), p.create_time()
    except (psutil.Error, OSError):
        return None


def _descendant_pids(pid: int) -> set[int]:
    """``pid`` plus every live descendant; empty when the tree is unreadable."""
    try:
        import psutil
    except ImportError:
        return set()
    try:
        p = psutil.Process(pid)
        return {pid} | {c.pid for c in p.children(recursive=True)}
    except (psutil.Error, OSError):
        return set()


def _listener_pids(port: int) -> set[int]:
    """PIDs holding a LISTEN socket on ``port``; empty when unknowable.

    psutil reads the kernel's socket table directly, so another account's
    process costs no extra privilege here (measured 11-16 under a restricted
    token: 1883 resolved to the SYSTEM python that owns it).
    """
    try:
        import psutil
    except ImportError:
        return set()
    found: set[int] = set()
    try:
        conns = psutil.net_connections(kind="inet")
    except (psutil.Error, OSError):
        return set()
    for c in conns:
        if c.laddr and c.laddr.port == port and c.pid:
            found.add(c.pid)
    return found


def _ancestor_of(pid: int, anchor: int) -> bool:
    """True when ``anchor`` is ``pid`` itself or one of its ancestors.

    Only parent links are read, never command lines, because that is the half
    of the process table a restricted token can still see.  The walk stops at
    pid 1/0 or after a bounded number of steps, so a corrupt chain cannot turn
    this into a loop.
    """
    seen = 0
    cur = pid
    while cur and cur > 0 and seen < 64:
        if cur == anchor:
            return True
        parent = _parent_pid(cur)
        if not parent or parent == cur:
            return False
        cur = parent
        seen += 1
    return False


def _service_anchor_pid() -> int:
    """PID of the supervisor process itself, or 0.

    POSIX asks systemd; Windows asks the SCM, whose answer names the process the
    service host created — the one process on this host that provably came from
    our service, and therefore a trustworthy root for an ownership walk.

    pywin32 first, ``sc.exe`` only as a fallback: this machine's policy refuses
    to start ``sc`` (measured 11-16), and a query that has to spawn a helper can
    be blocked by a policy this product has no say in.  Both forms need only
    ``SERVICE_QUERY_STATUS``, which an interactive user already holds.
    """
    if IS_WIN:
        if not _win_service_installed():
            return 0
        try:
            import win32service
        except ImportError:
            win32service = None
        if win32service is not None:
            try:
                hscm, hs = _win_open_service(
                    win32service, win32service.SERVICE_QUERY_STATUS)
            except Exception:
                return 0
            try:
                return int(win32service.QueryServiceStatusEx(hs)["ProcessId"])
            except Exception:
                return 0
            finally:
                win32service.CloseServiceHandle(hs)
                win32service.CloseServiceHandle(hscm)
        try:
            r = subprocess.run(["sc.exe", "queryex", SERVICE_NAME],
                               capture_output=True, text=True,
                               encoding=locale.getpreferredencoding(False),
                               errors="ignore",
                               creationflags=_no_console_flags())
        except (OSError, subprocess.SubprocessError):
            return 0
        m = re.search(r"PID\s*:\s*(\d+)", r.stdout or "")
        return int(m.group(1)) if m else 0
    return _service_main_pid()


def _broker_is_ours(pid: int, port: int) -> bool:
    """Strongest available proof that ``pid`` is the broker this home started.

    Three tiers, strongest first:

    1. **Command line** — ``amqtt`` plus *our* mqtt.yaml.  What POSIX and an
       elevated prompt always get, and still the best evidence there is: when
       it is readable and does not match, the answer is no, full stop.
    2. **Identity plus topology** — for a Windows service, where the broker runs
       as LocalSystem and a plain user cannot read its command line.  The image
       must be python, the creation time must match the stamp in the pid file
       (so a recycled number is refused), and this pid or a descendant must
       hold the listener port.
    3. Anything less is a no.

    Tier 2 is deliberately narrow: a pid that survived a reboot, happens to be
    python, and holds 1883 *while also* matching a recorded creation time is
    this broker and nothing else on a home LAN.
    """
    conf = _mqtt_paths()["conf"].as_posix().lower()
    cmd = _proc_cmdline(pid).replace("\\", "/").lower()
    if cmd:
        return "amqtt" in cmd and conf in cmd

    ident = _proc_identity(pid)
    if ident is None:
        return False
    name, created = ident
    if not name.lower().startswith("python"):
        return False
    stamp = _mqtt_pid_stamp()
    if stamp is not None and abs(created - stamp) > 0.05:
        return False
    tree = _descendant_pids(pid)
    return bool(tree) and bool(tree & _listener_pids(port))


def _mqtt_pid_by_topology() -> int | None:
    """The listener found through parent links, for when no command line reads.

    Only candidates whose image is python *and* whose ancestor chain reaches a
    pid this home already trusts are adopted: the number in the pid file, or the
    process the service manager reports for our unit.  Nothing else can have
    started a python inside our own tree, and no stranger's process can carry
    our supervisor as an ancestor — which is what makes this a proof of
    ownership rather than a guess.
    """
    port = _mqtt_conf()["port"]
    raw = _mqtt_pid_raw()
    anchors = {a for a in (raw, _service_anchor_pid()) if a and a > 0}
    if not anchors:
        return None
    for pid in _listener_pids(port):
        ident = _proc_identity(pid)
        if ident is None or not ident[0].lower().startswith("python"):
            continue
        stamp = _mqtt_pid_stamp()
        if pid == raw and stamp is not None and abs(ident[1] - stamp) > 0.05:
            # The file's own number is the listener but was created at a
            # different moment: it was recycled, and adopting it here would
            # undo the check `_broker_is_ours` just made.
            continue
        if any(_ancestor_of(pid, a) for a in anchors):
            return pid
    return None


def _mqtt_pid_scan() -> int | None:
    """Our broker found by its command line, for when the pid file names nothing.

    The pid file is written by whoever spawned the broker, so it can be empty
    or stale while the listener it started is still ours: a reboot wipes the
    process, and the unit's own start rewrites the file a moment later — a CLI
    that read it in between finds a number that carries nothing.  The listener
    is unambiguous, though: an ``amqtt`` command line naming *our* mqtt.yaml
    can only be the one we spawned, because that path is ours alone.

    Read-only.  The caller decides whether to adopt the pid (write it back) or
    kill the process; nothing here touches either.
    """
    conf = _mqtt_paths()["conf"].as_posix().lower()

    def ours(pid: int) -> bool:
        cmd = _proc_cmdline(pid).replace("\\", "/").lower()
        return "amqtt" in cmd and conf in cmd

    if IS_WIN:
        try:
            import psutil
        except ImportError:
            return None
        try:
            procs = psutil.process_iter()
        except (psutil.Error, OSError):
            return None
        for proc in procs:
            try:
                if ours(proc.pid):
                    return proc.pid
            except (psutil.Error, OSError):
                continue        # exited between listing and reading
        # Nothing matched by command line.  Under a Windows service that is the
        # normal outcome for an unelevated prompt, not evidence of absence: the
        # broker runs as LocalSystem, so its command line is unreadable while
        # its place in our process tree is not.
        return _mqtt_pid_by_topology()

    try:
        entries = os.listdir("/proc")
    except OSError:
        return None
    me = os.getpid()
    for name in entries:
        if not name.isdigit():
            continue
        pid = int(name)
        if pid == me:
            continue
        if ours(pid):
            return pid
    return _mqtt_pid_by_topology()


def _mqtt_pid() -> int | None:
    """PID of *our* broker, or None.

    The file says who we spawned; ``_broker_is_ours`` says whether that number
    still carries the same process.  The file outlives its process (crash,
    reboot, pid reuse), and killing whatever inherited the number is exactly
    the mistake decision #9 forbids.  That is why the evidence is layered rather
    than assumed: a readable command line decides on its own, and when it cannot
    be read — a Windows service running as LocalSystem, seen from a plain user's
    prompt — a recorded creation time plus the listener topology decides
    instead.  Neither layer guesses, and neither needs an administrator.

    A file that names nothing falls back to a scan, because the broker can
    outlive its own bookkeeping: a reboot empties the file while a supervisor's
    start rewrites it a moment later, and a caller that read it in between would
    otherwise mistake our own listener for a stranger's.  The scan is held to
    the same tests as the file — a command line naming ``amqtt`` plus *our*
    config path, or a python listener under our own supervisor — so it can only
    ever find the process this product started.
    """
    pid = _mqtt_pid_raw()
    if pid and pid > 0 and pid_exists(pid) and _broker_is_ours(pid, _mqtt_conf()["port"]):
        return pid

    # The file cannot name it, but the listener may still be ours.  Reporting
    # "another program" here is not merely a wrong log line: `status` repeats
    # it, and `start` skips the MQTT entry provisioning that only runs when the
    # broker is ours.  Adopting the pid repairs the file as well, so the next
    # command takes the fast path.
    found = _mqtt_pid_scan()
    if found:
        _mqtt_pid_write(found)
        log(f"broker already running (PID {found}) — {_mqtt_paths()['pid'].name} repaired")
        return found
    return None


def _mqtt_pid_write(pid: int) -> None:
    """Record who owns the listener, plus when that process came to exist.

    The creation time is the second column so a number that outlives its process
    cannot later be mistaken for the same process: a recycled pid always carries
    a later creation time (see ``_broker_is_ours``).  Written best-effort — an
    identity that cannot be read leaves the single-column shape, which the
    reader still accepts.
    """
    p = _mqtt_paths()["pid"]
    ident = _proc_identity(pid)
    text = f"{pid} {ident[1]:.6f}\n" if ident else f"{pid}\n"
    try:
        p.write_text(text, encoding="utf-8")
        os.chmod(p, 0o600)
    except OSError as e:
        # Not fatal: the broker is up and usable, but the next stop has to find
        # it another way, so say it rather than hide it.
        log(f"WARN  cannot write {p.name} ({e}) — 'homeant stop' may miss the broker")


def _mqtt_accepts(host: str, port: int, timeout: float = 1.0) -> bool:
    """True when something accepts TCP on the listener's port.

    A wildcard bind is probed through loopback — that is the same question
    `port_in_use` asks, and the only address guaranteed to work for any
    listener this product configures.
    """
    target = "127.0.0.1" if host in ("", "0.0.0.0") else host
    try:
        with socket.create_connection((target, port), timeout=timeout):
            return True
    except OSError:
        return False


def _mqtt_ensure_running(replace: bool = False) -> str:
    """Bring the broker up.  Returns running | started | port-taken | failed.

    `started` means *this* call spawned it and therefore owns stopping it;
    `running` means somebody already does (an earlier foreground run, or this
    same command's earlier phase) and must not be second-guessed.  The two are
    kept apart because a supervisor restarting `start --foreground` every ten
    seconds must not accumulate brokers.

    `replace` permits a restart; it does not ask for one.  A caller on its way
    to bringing hass up passes True, and the broker is restarted only when the
    file it reads no longer says what cfg says — mqtt.yaml is derived and amqtt
    reads it exactly once at start-up, so a broker left over from another
    release, or from a cfg edited since, would otherwise keep serving the old
    listener for the rest of its life.  On an untouched box there is no
    difference, so nothing is stopped and the caller gets `running` — the same
    "act only when the fingerprint stops matching" rule hass's own startup
    follows.  The caller that finds hass already running leaves it False: there
    the broker is only re-confirmed, because bouncing it would drop every MQTT
    device over a change hass has not been told about.

    `port-taken` is not a failure of ours: a user may have installed mosquitto,
    and hass can use it.  Everything else that goes wrong is `failed`, and the
    caller refuses to bring hass up — a home advertised with MQTT but serving
    none is the half state this product does not report.
    """
    err = _mqtt_gate()
    if err:
        log_state("FAIL", err)
        return "failed"

    c = _mqtt_conf()
    paths = _mqtt_paths()

    pid = _mqtt_pid()
    replaced = False
    if pid:
        if not replace:
            log(f"broker already running (PID {pid})")
            return "running"
        stale = _mqtt_derived_why()
        if not stale:
            # Same verdict `start` reaches for hass: nothing changed, so
            # nothing is done.  A plain `start` on an upgraded box lands here —
            # cfg is untouched by an upgrade and the YAML is deterministic, so
            # the old broker is serving exactly what the new one would.
            log(f"broker already running (PID {pid}) — "
                f"mqtt.yaml matches {CONFIG_FILE.name}")
            return "running"
        # Only a real difference gets a restart: the release that changed how
        # these files are generated, or a cfg edited by hand.  Same shape as
        # the hass half of an upgrade — stop, then let the normal start path
        # below write the files and spawn a fresh process.  A refusal here is a
        # FAIL, not a reused broker: a pid file naming something that is not
        # our broker must never be second-guessed.
        log(f"replacing broker (PID {pid}) — {stale}")
        if not _mqtt_stop():
            return "failed"
        replaced = True

    # Skipped only in the pass that just took our own broker down.  The
    # listener still seen answering there can be that very socket on its way
    # out — it stays visible for a while past the process — and reading it as
    # "another program" would leave a home
    # with hass up and no broker at all, which is worse than the reuse this
    # whole path replaced.  If it *is* somebody else, the spawn below dies on
    # EADDRINUSE and the wait loop reports that honestly: it asks whether the
    # child is still alive before it asks whether anything accepts.
    if not replaced and _mqtt_accepts(c["listen"], c["port"]):
        log(f"WARN  port {c['port']} is already in use by another program — "
            f"leaving it alone; MQTT stays on whatever serves it")
        return "port-taken"

    if not _mqtt_write_conf():
        return "failed"

    py = _python_bin()
    if py is None:
        log_state("FAIL", "no interpreter in this tree")
        log_run(_installer_cmd())
        return "failed"

    cmd = [str(py), "-m", "amqtt.scripts.broker_script", "-c", str(paths["conf"])]

    t0 = time.monotonic()
    try:
        # Both streams are discarded: this is a second daemon, it writes no log
        # file of ours, and the failure it explains best — a refused protocol
        # level — is answered with a CONNACK, so hass reports it as "Unable to
        # connect to the MQTT broker: Unacceptable protocol version".  What
        # only the broker knows is *which* level it saw; that is recoverable by
        # running the command the failure path prints.
        #
        # start_new_session puts it in its own group, so the hass tree's
        # SIGTERM (installer, systemd, Ctrl+C) does not reach it — its lifetime
        # is this command's decision, not the terminal's.
        #
        # env carries PYTHONPATH (so amqtt can import our authentication plugin)
        # and HOMEANT_HA_ROOT (so that plugin resolves mqtt.yaml's relative
        # storage_dir without an absolute path ever being written down).
        child = subprocess.Popen(
            cmd, cwd=str(HA_ROOT), stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            start_new_session=True, creationflags=_no_console_flags(),
            env=_broker_child_env())
    except OSError as e:
        log_state("FAIL", f"cannot start the MQTT broker — {e}")
        return "failed"

    deadline = t0 + MQTT_ACCEPT_TIMEOUT
    while time.monotonic() < deadline:
        # The child first: "something accepts on this port" is not the same
        # question as "our broker is up".  A child that died on EADDRINUSE
        # leaves the port answering to whoever got there first, and reading
        # that as our own start would write a pid file for a dead process and
        # report success to the caller.
        if child.poll() is not None:
            break
        if _mqtt_accepts(c["listen"], c["port"]):
            _mqtt_pid_write(child.pid)
            log(f"broker started ({c['listen']}:{c['port']}, PID {child.pid}, "
                f"ready in {time.monotonic() - t0:.1f}s)")
            return "started"
        time.sleep(0.2)

    rc = child.poll()
    why = (f"exited with {rc}" if rc is not None
           else f"did not accept on {c['port']} within {MQTT_ACCEPT_TIMEOUT:.0f}s")
    # Its output went to devnull, so name the one command that still explains
    # it: the same invocation in the foreground, where the reason is visible.
    log_state("FAIL", f"the MQTT broker {why}")
    log(f"      run it by hand to see why: {py} -m amqtt.scripts.broker_script "
        f"-c {paths['conf']}")
    if child.poll() is None:
        with contextlib.suppress(OSError):
            child.kill()
    return "failed"


def _win_terminate(pid: int) -> bool:
    """End *pid* itself; False only when this token is refused the right to.

    ``taskkill /F /T`` walks the tree and gives up as a unit.  Measured on a
    real broker: the pid we track (the parent) had ``PROCESS_TERMINATE``, one of
    its children did not, and taskkill refused the parent too — exit 128, the
    same code it uses for a pid that is already gone, so the stop loop waited
    out its window and reported a hang that never existed.  The direct call
    succeeds where the tree walk bailed out.

    ``ERROR_ACCESS_DENIED`` (5) is the one answer that means "not from this
    window, however often you retry".  A pid that vanished meanwhile reports 87
    and counts as done — the caller only cares that it is no longer running.
    """
    if not IS_WIN:
        return True
    try:
        import ctypes
        k = ctypes.WinDLL("kernel32", use_last_error=True)
        ctypes.set_last_error(0)
        h = k.OpenProcess(0x0001, False, pid)    # PROCESS_TERMINATE
        if not h:
            return ctypes.get_last_error() != 5
        try:
            ctypes.set_last_error(0)
            if k.TerminateProcess(h, 1):
                return True
            return ctypes.get_last_error() != 5
        finally:
            k.CloseHandle(h)
    except (AttributeError, OSError):
        return False


def _mqtt_stop(verbose: bool = True) -> bool:
    """Stop the broker we started; True when none of ours is left running.

    Called after hass, never before: hass flushes .storage on its way out, and
    an MQTT broker still answering costs nothing during those seconds.  A
    stale pid file is removed silently; a pid file naming something that is
    *not* our broker is a refusal — nothing is killed and the file is left as
    evidence for the reader.
    """
    paths = _mqtt_paths()
    raw = _mqtt_pid_raw()
    pid = _mqtt_pid()
    if pid is None:
        if raw and pid_exists(raw):
            # "could not be confirmed" rather than "is not ours": the evidence
            # can be unreadable (a service-owned process, seen from a plain
            # prompt), which is a refusal to act, not a verdict about identity.
            log_state("FAIL", f"{paths['pid'].name} names PID {raw}, which is alive "
                              f"but could not be confirmed as our broker — not "
                              f"touching it")
            return False
        if raw:
            with contextlib.suppress(OSError):
                paths["pid"].unlink()
        if verbose:
            log("broker not running")
        return True

    log(f"stopping broker (PID {pid}) ...")
    denied = False
    if IS_WIN:
        # Same conclusion as _stop_pid: a console-less python child has no way
        # to receive Ctrl+C, so TerminateProcess is the only stop there is.  The
        # broker holds no state worth flushing — retained messages are in
        # memory and hass republishes them on reconnect.
        r = subprocess.run(["taskkill", "/PID", str(pid), "/F", "/T"],
                           capture_output=True, creationflags=_no_console_flags())
        # Not the exit code — see _win_terminate for why it cannot tell a
        # refusal from a pid that is already gone, and why the pid we track can
        # still be killable when the tree walk was refused.  Only a refusal of
        # the direct call means a different window is needed, and saying that
        # beats "it may be stuck", which sends the reader hunting a wedged
        # process that is not there.
        denied = r.returncode != 0 and not _win_terminate(pid)
    else:
        try:
            pgid = os.getpgid(pid)
        except ProcessLookupError:
            pgid = None
        signal_fn = os.killpg if pgid == pid else os.kill
        with contextlib.suppress(ProcessLookupError, PermissionError):
            signal_fn(pgid if pgid == pid else pid, signal.SIGTERM)

    # A refused kill is not a hang: nothing was delivered, so waiting out the
    # stop window would only delay the sentence that helps.  Checking liveness
    # once more keeps the other half of a partial tree-kill honest.
    if denied and pid_exists(pid):
        # The verdict is ours: the kernel already said this token may not end
        # the process, so there is nothing for the reader to work out.
        if not _is_admin():
            log_state("FAIL", f"cannot stop the broker (PID {pid}) — "
                              f"run as administrator")
            log("      run: .\\homeant stop")
        else:
            log_state("FAIL", f"cannot stop the broker (PID {pid}) — access denied")
        return False

    for _ in range(50):
        _reap_child(pid)
        if not pid_exists(pid):
            with contextlib.suppress(OSError):
                paths["pid"].unlink()
            if verbose:
                log(f"broker stopped (PID {pid})")
            return True
        time.sleep(0.2)

    if not IS_WIN:
        try:
            pgid = os.getpgid(pid)
        except ProcessLookupError:
            pgid = None
        signal_fn = os.killpg if pgid == pid else os.kill
        with contextlib.suppress(ProcessLookupError, PermissionError):
            signal_fn(pgid if pgid == pid else pid, signal.SIGKILL)
        for _ in range(25):
            _reap_child(pid)
            if not pid_exists(pid):
                with contextlib.suppress(OSError):
                    paths["pid"].unlink()
                if verbose:
                    log(f"broker stopped (PID {pid})")
                return True
            time.sleep(0.2)

    log_state("FAIL", f"the broker (PID {pid}) is still running — "
                      f"it may be stuck; try again or kill it by hand")
    return False


# ── mqtt config entry ────────────────────────────────────────────────────────
#
# A live broker is only half of "MQTT works": hass also needs a config entry
# pointing at it.  HA has no runtime API for creating one — entries live in
# memory while hass runs and are flushed on shutdown — so the entry is built as
# data and appended to core.config_entries while hass is stopped, exactly like
# the owner account.
#
# The fragment comes from HA's own ConfigEntry.as_dict() instead of being
# spelled out here: that object owns the field list (16 fields today) and the
# version pair HA uses to decide how to read an entry back, so an upstream
# addition shows up without this file changing.
#
# Add-only.  An existing mqtt entry is never touched: it may point at a broker
# the user runs elsewhere, and rewriting it would silently move their devices.

MQTT_ENTRY_DOMAIN = "mqtt"
# From the mqtt integration's FlowHandler: VERSION = 2, MINOR_VERSION = 1.
MQTT_ENTRY_VERSION = 2
MQTT_ENTRY_MINOR_VERSION = 1


def _has_mqtt_entry() -> bool:
    """True when core.config_entries already holds an mqtt entry."""
    ce = HA_ROOT / ".storage" / "core.config_entries"
    if not ce.exists():
        return False
    try:
        data = json.loads(ce.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    return any(e.get("domain") == MQTT_ENTRY_DOMAIN
               for e in data.get("data", {}).get("entries", []))


def _mqtt_entry_data() -> dict:
    """The broker settings HA's own setup form would have collected.

    Called only when an entry is about to be created, and that is the only time
    a password is generated: afterwards the entry is the truth — the broker's
    plugin reads it per connection — which is exactly what makes it changeable
    from the UI.  The host follows the listener: a broker bound to one LAN
    address does not answer on loopback, and pointing hass at 127.0.0.1 there
    would leave the entry stuck in setup_retry.
    """
    c = _mqtt_conf()
    host = "127.0.0.1" if c["listen"] in ("", "0.0.0.0") else c["listen"]
    return {
        "broker": host,
        "port": c["port"],
        # amqtt 0.12.1 speaks MQTT 3.1.1 only — measured: a v5 CONNECT is
        # rejected with "Invalid protocol from ...: 5" and the session never
        # opens.  This therefore must not follow the integration's own default
        # of PROTOCOL_5 the way a hand-made entry would.
        "protocol": "3.1.1",
        "username": MQTT_ENTRY_USER,
        "password": _gen_password(),
        "other_settings": {},
    }


def _provision_mqtt_entry() -> bool:
    """Append the mqtt entry to core.config_entries.  hass must be stopped."""
    if _ha_instance() or _hass_via_service():
        # hass holds entries in memory and flushes them on shutdown, so a file
        # written under a live instance is simply overwritten later.  This is
        # not a failure: the usual caller on this path is a supervisor restart
        # of a home that is already running and already has its entry.
        return True
    if _has_mqtt_entry():
        return True

    from types import MappingProxyType

    from homeassistant.config_entries import ConfigEntry

    entry_data = _mqtt_entry_data()
    try:
        fragment = ConfigEntry(
            data=entry_data,
            discovery_keys=MappingProxyType({}),
            domain=MQTT_ENTRY_DOMAIN,
            minor_version=MQTT_ENTRY_MINOR_VERSION,
            options={},
            source="user",
            subentries_data=[],
            title="HomeAnt broker",
            unique_id=None,
            version=MQTT_ENTRY_VERSION,
        ).as_dict()
    except Exception as e:                       # noqa: BLE001
        # Reported rather than swallowed: the shape of an entry is HA's, so a
        # failure here means the integration moved and this needs a look.
        log_state("FAIL", f"cannot build the mqtt config entry ({e})")
        return False

    ce = HA_ROOT / ".storage" / "core.config_entries"
    try:
        doc = json.loads(ce.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        log_state("FAIL", f"cannot read {ce.name} to add the mqtt entry ({e})")
        return False

    doc.setdefault("data", {}).setdefault("entries", []).append(
        json.loads(json.dumps(fragment, default=str)))
    tmp = ce.with_name(ce.name + ".tmp")
    try:
        tmp.write_text(json.dumps(doc, indent=2, ensure_ascii=False),
                       encoding="utf-8")
        os.replace(tmp, ce)
    except OSError as e:
        log_state("FAIL", f"cannot write {ce.name} ({e})")
        with contextlib.suppress(OSError):
            tmp.unlink()
        return False

    # No credential echo: a password on a console line ends up in a scrollback
    # buffer and a journal file.  The value lives in the entry, and the MQTT
    # integration's reconfigure form is where it gets changed.
    log("mqtt: config entry created")
    return True


def _ensure_auth_offline() -> bool:
    """Provision the owner account into .storage/auth — hass stopped."""
    # Two separate reasons, reported separately: "hass is running" is a fact
    # about our pid, while a busy port only means *somebody* holds 8123 (a
    # dllhost.exe squatting there once made this line blame hass, which sent
    # the reader after a process that was never started).
    if _ha_instance() or _hass_via_service():
        log("auth provision skipped: hass is running")
        return False
    if port_in_use(PORT):
        log(f"auth provision skipped: port {PORT} is held by another process")
        return False
    PROVIDER_STORE.parent.mkdir(parents=True, exist_ok=True)

    # Before the gate below and before any provider write: whatever value ends
    # up in cfg is what gets provisioned, and what every later login reads.
    # Nothing is said here — the one line belongs to `_ensure_credential`.
    _ensure_admin_password()
    if not cf("PASSWORD"):
        # Nothing usable to provision: `_ensure_admin_password` already printed
        # why it could not write one, and a default here would be a password
        # nobody chose.
        return False

    # Refused before anything is written: the username is already bound to a
    # non-owner account, and linking the owner to it would either steal that
    # account or hand admin rights to whoever registered the name first.
    taken = _admin_state()["holder"]
    if taken:
        log_red(f"auth: USERNAME '{cf('USERNAME', 'admin')}' already belongs to "
                f"the non-owner user '{taken}' — not taking it over; set another "
                f"USERNAME in homeant.cfg")
        return False

    # Two questions, because `_admin_ready` only looks at structure (owner,
    # credential link): a structurally complete install whose stored password
    # no longer matches cfg still has to reach the reset path.  The cheap local
    # check decides whether the heavy in-process bootstrap runs at all; the
    # reset itself is decided by HA's own validator inside `_provision_auth`,
    # and only a verified mismatch is rewritten.
    if _admin_ready() and _admin_pw_agrees(
            cf("USERNAME", "admin"), cf("PASSWORD")) is True:
        _mark_onboarding_user_done()
        return True

    import shutil as _shutil
    backups = []
    for p in (AUTH_STORE, PROVIDER_STORE, ONBOARDING_STORE):
        if p.exists():
            b = p.with_name(p.name + ".bak")
            try:
                _shutil.copy2(p, b)
                backups.append((b, p))
            except OSError as e:
                log(f"auth backup failed ({p.name}): {e}")

    ok = False
    try:
        ok = _provision_auth()
    except Exception as e:  # noqa: BLE001 — never break start on this
        log_red(f"auth provision error: {e}")

    if not ok or not _admin_ready():
        for b, p in backups:
            try:
                _shutil.copy2(b, p)
            except OSError:
                pass
        log_red("auth provision FAILED — restored previous .storage/auth")
        return False
    _mark_onboarding_user_done()
    return True

class _WSConn:
    """Minimal HA auth websocket client (stdlib only, single connection)."""

    def __init__(self, sock: socket.socket, buf: bytes = b"") -> None:
        self._s = sock
        self._buf = buf

    def _send_frame(self, opcode: int, payload: bytes) -> None:
        """Send one masked frame; client frames must always be masked."""
        mask = os.urandom(4)
        masked = bytes(b ^ mask[i % 4] for i, b in enumerate(payload))
        n = len(payload)
        if n < 126:
            hdr = bytes([0x80 | opcode, 0x80 | n])
        elif n < 65536:
            hdr = bytes([0x80 | opcode, 0x80 | 126]) + n.to_bytes(2, "big")
        else:
            hdr = bytes([0x80 | opcode, 0x80 | 127]) + n.to_bytes(8, "big")
        self._s.sendall(hdr + mask + masked)

    def send(self, payload: dict) -> None:
        self._send_frame(0x1, json.dumps(payload).encode())

    def _take(self, n: int) -> bytes:
        """Return exactly n bytes, or raise once the peer has closed.

        The EOF branch is the load-bearing one: ``recv()`` returning ``b""``
        appended nothing, so ``while len(buf) < n`` never became true and the
        loop spun at 100% CPU for as long as the caller kept waiting — which is
        every ``status``/``start`` that talks to hass while it restarts.
        """
        while len(self._buf) < n:
            chunk = self._s.recv(4096)
            if not chunk:
                raise ConnectionError("websocket closed")
            self._buf += chunk
        head, self._buf = self._buf[:n], self._buf[n:]
        return head

    def _read_frame(self) -> tuple[bool, int, bytes]:
        """One frame: (fin, opcode, payload)."""
        b0, b1 = self._take(2)
        fin = bool(b0 & 0x80)
        opcode = b0 & 0x0F
        ln = b1 & 0x7F
        if ln == 126:
            ln = int.from_bytes(self._take(2), "big")
        elif ln == 127:
            ln = int.from_bytes(self._take(8), "big")
        if b1 & 0x80:                       # masked: only clients send these
            mask = self._take(4)
            body = self._take(ln)
            body = bytes(c ^ mask[i % 4] for i, c in enumerate(body))
        else:
            body = self._take(ln)
        return fin, opcode, body

    def recv(self) -> dict:
        """Next JSON text message, after answering control frames.

        The wire is frame-based and only two opcodes carry our protocol: text
        (and its continuation).  Reading it as "bytes until something parses"
        turned a normal close into a JSONDecodeError, and a ping into the same —
        while the peer, never answered, dropped the connection a moment later.
        """
        parts: list[bytes] = []
        while True:
            fin, opcode, body = self._read_frame()
            if opcode == 0x8:               # close
                raise ConnectionError("websocket closed by peer")
            if opcode == 0x9:               # ping: pong carries the same payload
                self._send_frame(0xA, body)
                continue
            if opcode == 0xA:               # pong: nobody asked, ignore
                continue
            if opcode not in (0x1, 0x0):    # binary/unknown: not our protocol
                continue
            parts.append(body)
            if fin:
                break
        raw = b"".join(parts)
        if not raw:
            raise ConnectionError("empty websocket message")
        return json.loads(raw.decode())

    def call(self, payload: dict, tries: int = 4) -> dict | None:
        """Send one command, return its `result` frame (None on timeout)."""
        self.send(payload)
        for _ in range(tries):
            res = self.recv()
            if res.get("type") == "result":
                return res
        return None


@contextlib.contextmanager
def _ws_open(bearer: str, timeout: float = 10.0):
    """Open + authenticate a websocket to HA's /api/websocket."""
    s = socket.create_connection(("127.0.0.1", PORT), timeout)
    try:
        s.settimeout(timeout)
        key = base64.b64encode(os.urandom(16)).decode()
        # Host is a protocol field, not a dial target — keep the name here
        # even though the socket above connects to the IPv4 literal.
        # helpers/network.py::get_url() accepts "localhost" as a known
        # hostname unconditionally, but an IP literal passes only while
        # allow_ip is on (it is off when api.use_ssl is set).  HA answers
        # 101 + auth_required for any Host here, even a malformed one, so
        # changing this buys nothing and would trade the unconditional name
        # for a deployment-dependent address.
        s.sendall((
            f"GET /api/websocket HTTP/1.1\r\n"
            f"Host: localhost:{PORT}\r\n"
            "Upgrade: websocket\r\nConnection: Upgrade\r\n"
            f"Sec-WebSocket-Key: {key}\r\n"
            "Sec-WebSocket-Version: 13\r\n"
            f"Authorization: Bearer {bearer}\r\n\r\n"
        ).encode())
        head = b""
        while b"\r\n\r\n" not in head:
            chunk = s.recv(4096)
            if not chunk:
                raise OSError("handshake closed")
            head += chunk
        if b" 101 " not in head.split(b"\r\n", 1)[0]:
            raise OSError("websocket upgrade rejected")
        ws = _WSConn(s, head.split(b"\r\n\r\n", 1)[1])
        first = ws.recv()
        if first.get("type") != "auth_required":
            raise OSError(f"unexpected first frame: {first}")
        ws.send({"type": "auth", "access_token": bearer})
        ok = ws.recv()
        if ok.get("type") != "auth_ok":
            raise OSError(f"auth failed: {ok}")
        yield ws
    finally:
        s.close()


def _ws_llat(bearer: str, timeout: float = 10.0) -> str | None:
    """Create a long-lived access token via HA's websocket API."""
    try:
        with _ws_open(bearer, timeout) as ws:
            stale_id = None
            res = ws.call({"id": 1, "type": "auth/refresh_tokens"})
            if res and res.get("success"):
                for t in res.get("result") or []:
                    if (t.get("client_name") == LLAT_CLIENT_NAME
                            and t.get("type") == "long_lived_access_token"):
                        stale_id = t.get("id")
                        break
            if stale_id:
                res = ws.call({"id": 2, "type": "auth/delete_refresh_token",
                               "refresh_token_id": stale_id})
                if res and res.get("success"):
                    log("llat: revoked stale HomeAnt token")
                else:
                    log(f"llat: revoke stale failed: {(res or {}).get('error')}")
            res = ws.call({
                "id": 3,
                "type": "auth/long_lived_access_token",
                "client_name": LLAT_CLIENT_NAME,
                "lifespan": LLAT_LIFESPAN_DAYS,
            })
            if res and res.get("success"):
                return res.get("result")
            log(f"llat: create failed: {(res or {}).get('error')}")
            return None
    except Exception as e:
        log(f"llat: websocket error: {e}")
        return None


def _ws_purge_normal(bearer: str, timeout: float = 10.0) -> None:
    """Drop the `normal` refresh token this login just minted.

    Every login mints a ~90-day refresh token; without cleanup they pile up in
    .storage/auth.  We revoke exactly the current one and never call
    `auth/delete_all_refresh_tokens`: that one takes every normal token of the
    account, and this account is the owner — someone may well be signed in
    through a browser, whose session this run has no business ending.
    """
    try:
        with _ws_open(bearer, timeout) as ws:
            res = ws.call({"id": 1, "type": "auth/refresh_tokens"})
            current = None
            if res and res.get("success"):
                for t in res.get("result") or []:
                    if t.get("is_current") and t.get("type") == "normal":
                        current = t.get("id")
                        break
            if not current:
                return
            done = False
            try:
                # Revoking the current token drops this socket — expected.
                res = ws.call({"id": 2, "type": "auth/delete_refresh_token",
                               "refresh_token_id": current})
                done = bool(res and res.get("success"))
            except Exception:
                done = True         # socket killed by the revoke itself
            if not done:
                log("auth: admin token revoke returned no result")
    except Exception as e:
        log(f"auth token purge skipped: {e}")


def _token_ok(tok: str) -> bool:
    """Probe GET /api/ with the token (HA answers 200 only for valid auth)."""
    try:
        st, _ = _http_get(f"{MCP_PROBE_BASE}/api/",
                          headers={"Authorization": f"Bearer {tok}"})
        return st == 200
    except Exception:
        return False


def _mcp_token(create: bool = True, fail: dict | None = None) -> str | None:
    """Cached owner LLAT for the MCP endpoint — user-invisible.

    Priority: .mcp-token cache -> login as USERNAME -> create LLAT (ws) -> cache.

    The token belongs to the owner account, so an agent holding it has admin
    rights on this instance.  That is the deliberate trade of this design: one
    account means one credential pair in the config file and no second identity
    to keep in sync, and the token never travels — it is printed for the user to
    paste and cached 0600.

    ``fail`` is an optional out-dict: on failure it gets ``{"kind": "login"}``
    when the credential was rejected, or ``{"kind": "llat"}`` when the login
    worked but HA refused to mint the token.  Those two need different advice,
    so the caller cannot collapse them into one message.
    """
    try:
        tok = MCP_TOKEN_FILE.read_text(encoding="utf-8").strip()
    except OSError:
        tok = ""
    if tok:
        if _token_ok(tok):
            return tok
        log("cached MCP token rejected — recreating")
        if create:
            # Drop the dead token before minting a new one: if minting fails the
            # stale file would otherwise stay behind and `status` would keep
            # reporting a rejected cache instead of an empty one.  Deliberately
            # skipped on the read-only path — status must not mutate state.
            try:
                MCP_TOKEN_FILE.unlink()
            except OSError:
                pass
    if not create:
        return None
    bearer = _login(cf("USERNAME", "admin"), cf("PASSWORD", "homeant"))
    if not bearer:
        if fail is not None:
            fail["kind"] = "login"
        return None
    tok = _ws_llat(bearer)
    if not tok:
        if fail is not None:
            fail["kind"] = "llat"
        return None
    try:
        MCP_TOKEN_FILE.write_text(tok, encoding="utf-8")
        if not IS_WIN:
            os.chmod(MCP_TOKEN_FILE, 0o600)
    except OSError as e:
        log(f"MCP token cache failed: {e}")
    # The login above minted a normal refresh token too; revoke just that one,
    # so a browser session on this same account survives (see _ws_purge_normal).
    # It has to be *this* bearer, not the LLAT: the selector is
    # `is_current and type == "normal"`, and authenticating with a long-lived
    # token points is_current at that long-lived token instead — the selector
    # then matches nothing and every run leaves its login token behind.
    _ws_purge_normal(bearer)
    return tok


def _mcp_diag() -> tuple[bool, str]:
    """Probe the MCP endpoint with the cached MCP token. Returns (ok, message).

    Reads the cache file directly instead of going through
    ``_mcp_token(create=False)``: that call returns None both when the file is
    missing and when the token was rejected, which made this report "no cached
    .mcp-token" for an install that had one — just an invalid one.
    """
    tok = _cached_mcp_token()
    if not tok:
        return False, "no cached .mcp-token"
    if _token_ok(tok):
        return True, "token valid"
    return False, "cached token rejected (start auto-recreates)"


def _mcp_client_config(tok: str) -> dict:
    """Copy-paste config block for MCP clients (token inlined on purpose:
    the user pastes it into any client and it just works, no edits)."""
    return {
        "mcpServers": {
            "homeant": {
                "url": MCP_CLIENT_URL,
                "headers": {"Authorization": f"Bearer {tok}"},
            }
        }
    }


def _mcp_config_text(tok: str) -> str:
    """Render the block `status` and the end of `start` print.

    Plain JSON and nothing else.  The block is pasted into client config
    editors, and those editors validate before they save: a ``//`` marker — the
    way this block used to delimit the part worth copying — and a trailing
    comma both come back as "invalid JSON", which tells the reader nothing they
    can act on.  So the whole document is valid, and the hint about merging the
    single ``homeant`` entry into an existing ``mcpServers`` lives in the
    sentence printed above the block, which is not part of it.

    ``indent=3`` keeps the real nesting: ``url`` sits one level under
    ``homeant`` and ``Authorization`` one level under ``headers``.  A flat
    prefix on every line would look aligned but read as a wall of keys, which
    is the thing this block has to avoid.  Built from ``_mcp_client_config`` so
    a new field there cannot drift out of the print.
    """
    return json.dumps(_mcp_client_config(tok), indent=3, ensure_ascii=False)


def _cached_mcp_token() -> str | None:
    """The provisioned LLAT, read straight from its cache file.

    Deliberately *not* validated: ``_token_ok()`` does a live ``GET /api/``
    probe, which is exactly what cannot be trusted while the core is still
    starting up.
    """
    try:
        return MCP_TOKEN_FILE.read_text(encoding="utf-8").strip() or None
    except OSError:
        return None


def _ha_core_state() -> tuple[int, str | None]:
    """``(http_status, state)`` from ``GET /api/core/state``.

    HA ships this view for supervisor's "is core running" poll
    (``components/api/__init__.py`` -> ``APICoreStateView``): it reports
    ``hass.state`` as STARTING / RUNNING / ....  That is the authoritative,
    cheap signal for "integrations finished loading" — which is when
    ``homeant_mdns`` registers the ``homeassistant.local`` record — as opposed
    to "the HTTP port is listening", which happens much earlier.
    """
    tok = _cached_mcp_token()
    if not tok:
        return 0, None
    try:
        status, body = _http_get(
            f"{MCP_PROBE_BASE}/api/core/state",
            headers={"Authorization": f"Bearer {tok}"},
            timeout=5.0,
        )
    except Exception:
        return 0, None
    state = body.get("state") if isinstance(body, dict) else None
    return status, state if isinstance(state, str) else None


def _wait_for_ha_running(timeout: float = 120.0, t0: float | None = None) -> bool:
    """Poll ``/api/core/state`` until the core reports RUNNING.

    Returns True only when RUNNING was observed.  False means "not RUNNING
    within the timeout" or "probe unsupported" — advisory, the caller carries
    on to the DNS check either way.
    """
    wait_start = time.monotonic()        # drives the polling deadline
    started = wait_start if t0 is None else t0  # t0 only for the reported duration
    deadline = wait_start + timeout
    announced = False
    unsupported = 0
    if not _cached_mcp_token():
        log("core state probe skipped: no cached MCP token")
        return False
    while time.monotonic() < deadline:
        status, state = _ha_core_state()
        if state == "RUNNING":
            if announced:
                log(f"home assistant running (after {time.monotonic() - started:.1f}s)")
            return True
        if status in (401, 403, 404):
            unsupported += 1
            if unsupported >= 3:
                log(f"core state probe unavailable (HTTP {status}) — continuing")
                return False
        else:
            unsupported = 0
        if not announced:
            log("waiting for Home Assistant to finish starting ...")
            announced = True
        time.sleep(1.0)
    log(f"WARNING: core not RUNNING after {timeout:.0f}s — continuing")
    return False


def _mcp_entry_present() -> bool:
    """True when HA's storage still carries the mcp_server config entry.

    Read straight off disk because that is the only evidence available once
    setup has failed: a loaded entry leaves no trace anywhere else, and a
    missing one is the difference between "the route was never registered" and
    "the route exists but the integration is broken".
    """
    path = HA_ROOT / ".storage" / "core.config_entries"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    entries = data.get("data", {}).get("entries")
    if not isinstance(entries, list):
        return False
    return any(
        isinstance(e, dict) and e.get("domain") == "mcp_server" for e in entries
    )


def _mcp_probe(tok: str, timeout: float = 15) -> str:
    """Empty when /api/mcp really answers an ``initialize`` request.

    Minting a token only proves the login worked.  The route is registered by
    mcp_server's ``async_setup``, which runs only while its config entry is
    loaded — and HA installs that entry's pip requirements at runtime, so the
    first boot after a fresh install can import-fail and leave no route behind.
    Without this probe the run prints SUCCESS and the user discovers the truth
    in their own client, as a 404 on an SSE handshake.

    It probes MCP_PROBE_BASE, not MCP_CLIENT_URL: the facts under test here
    are server-side (is the route registered, does the token answer), and
    loopback is the one address that is always present.  Whether this box can
    resolve MCP_HOSTNAME says nothing about clients, so it is deliberately
    not part of the check.
    The empty ProxyHandler is the other deliberate choice, because an
    HTTP_PROXY in the environment would otherwise route the check through a
    stranger.
    """
    import urllib.request as _ur

    url = f"{MCP_PROBE_BASE}/api/mcp"
    body = json.dumps({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "initialize",
        "params": {
            "protocolVersion": "2025-03-26",
            "capabilities": {},
            "clientInfo": {"name": "homeant", "version": "0"},
        },
    }).encode("utf-8")
    req = _ur.Request(
        url, data=body, method="POST",
        headers={
            "Authorization": f"Bearer {tok}",
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
        },
    )
    opener = _ur.build_opener(_ur.ProxyHandler({}))
    try:
        with opener.open(req, timeout=timeout) as resp:
            if resp.status == 200:
                return ""
            return f"the MCP endpoint answered HTTP {resp.status} — see home-assistant.log"
    except _ur.HTTPError as e:
        if e.code == 404:
            if not _mcp_entry_present():
                # The seed writes the entry once, guarded by the config/ tree
                # fingerprint; a wiped ~/.homeant/.storage therefore leaves the
                # fingerprint matching and the entry gone for good.  Saying so
                # is the difference between "run start again" (does nothing)
                # and the one command that does put it back.
                return _tilde_text(
                    "the mcp_server integration has no config entry in "
                    f"{HA_ROOT / '.storage' / 'core.config_entries'}, so /api/mcp was "
                    f"never registered — stop hass, delete {SEED_MARKER}, then start "
                    "to re-seed"
                )
            return _tilde_text(
                "the mcp_server integration is not loaded even though its entry "
                f"exists — see {HA_ROOT / 'home-assistant.log'}"
            )
        if e.code == 401:
            return "the core rejected the freshly minted token"
        return f"the MCP endpoint answered HTTP {e.code}"
    except Exception as e:  # noqa: BLE001 - transport failures all read the same
        return f"cannot reach {url}: {type(e).__name__}: {e}"


def _ensure_mcp_ready(fail: dict | None = None, tok: str | None = None) -> str | None:
    """Warm the MCP token cache, verify the endpoint, build the client config.

    Returns the ready-to-copy config block (the same marked-up text `status`
    prints), or None when no token could be minted (agents would get 401) or
    the endpoint does not actually answer.  Nothing is printed here: the reason
    goes into ``fail`` so ``_finish_setup`` can turn it into the single FAIL
    line, instead of the same problem being described twice.

    ``tok`` lets the caller mint the token earlier than this call: the RUNNING
    gate authenticates with it, so the token has to exist before the gate while
    the probe must come after it.
    """
    tok = tok or _mcp_token(fail=fail)
    if not tok:
        return None
    why = _mcp_probe(tok)
    if why:
        if fail is not None:
            fail["kind"] = "endpoint"
            fail["why"] = why
        return None
    return _mcp_config_text(tok)

# ── main ─────────────────────────────────────────────────────────────────────

def _register_cleanup() -> None:
    """Ensure hass (if we started one via cmd_start) gets killed on early exit.

    Detached hass.exe keeps .venv/Scripts/hass.exe locked, which breaks the
    next `uv sync`.  Atexit + signal handlers cover Ctrl+C, exception, and
    premature sys.exit().  Normal completion sets _KEEP_HASS so the running
    hass is left alone — cmd_start already backgrounded it on purpose.

    IMPORTANT: We only clean up hass that *this process* started
    (_WE_STARTED_HASS).  A stale PID file from a previous homeant.py run
    must NEVER trigger cleanup — that hass is not ours to kill.
    """
    import atexit

    _STOPPED = {"yes": False}   # avoid double-stop on Ctrl+C (signal + atexit)
    _KEEP_HASS = {"yes": False} # set True when cmd_start completes normally
    _WE_STARTED_HASS = {"yes": False}  # set True ONLY by cmd_start after launch

    def _cleanup() -> None:
        if _STOPPED["yes"] or _KEEP_HASS["yes"]:
            return
        if not _WE_STARTED_HASS["yes"]:
            return   # not our hass — don't touch it
        if SPAWNED_PID:
            _STOPPED["yes"] = True
            # The in-memory pid, not a lookup: this runs while we are exiting,
            # and the only process it may kill is the one this run launched.
            _stop_pid(SPAWNED_PID)

    atexit.register(_cleanup)

    def _on_sigint(signum, frame):
        _cleanup()
        raise KeyboardInterrupt()   # let main()'s try/except produce the usual "cancelled" msg

    def _on_sigterm(signum, frame):
        _cleanup()
        sys.exit(143)

    signal.signal(signal.SIGINT, _on_sigint)
    if hasattr(signal, "SIGTERM"):   # Windows has no SIGTERM
        signal.signal(signal.SIGTERM, _on_sigterm)

    # Expose setters so cmd_start can mark "keep hass on exit"
    def _mark_keep_hass() -> None:
        _KEEP_HASS["yes"] = True

    def _mark_we_started_hass() -> None:
        _WE_STARTED_HASS["yes"] = True

    # monkey-patch onto module-level so callers can find it
    import sys as _sys
    _sys.modules[__name__]._mark_keep_hass = _mark_keep_hass
    _sys.modules[__name__]._mark_we_started_hass = _mark_we_started_hass  # noqa: F841  (Pylance sees monkey-patch at runtime)


def main() -> int:
    global CFG
    enable_ansi()
    _register_cleanup()   # kill detached hass.exe on any exit path

    # The usage line is suppressed, not rewritten. Left alone argparse prints
    # the brace list twice — once in `usage:` and once as the heading of the
    # positional block — and only the heading is worth keeping, because it also
    # carries each command's one-line description. Writing `<command>` there
    # would just trade a duplicate for a placeholder that says less than the
    # list two lines below it, so the line goes entirely. A bare `homeant` then
    # prints this same screen with rc=2 (see below) instead of argparse's
    # one-line "required: command", which would have nothing left to point at.
    #
    # The version is printed, not offered as a flag: `--version` would make
    # "which build is this?" a question the user has to think to ask, while the
    # answer belongs in every run and every help screen. One read of
    # pyproject.toml, one `banner()` below, so the copies cannot drift.
    ver = _local_version() or "unknown"

    def banner() -> str:
        """The two lines every entry point opens with.

        Same text for the help screen and for a real run, on purpose: a pasted
        `homeant status` and a pasted `homeant --help` should look like the same
        program, and both answer "which build?" without being asked. One
        function, so the two copies cannot drift.

        Both lines carry the `[homeant]` tag, in the same slot the log lines use.
        The installers print the same pair with `[install]` instead, so a pasted
        log says which program produced it without anyone having to remember
        what the first line of each one looked like — and a support thread that
        starts with the installer's output is not mistaken for a `homeant` run.
        """
        return f"[homeant] HomeAnt — Control home through Agent.\n[homeant] version {ver}"

    parser = argparse.ArgumentParser(
        prog="homeant",
        usage=argparse.SUPPRESS,
        description=banner(),
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Options for `start`:
  --reinstall   reinstall the current release now, whether or not this tree is
                already the newest

Config:
  project_root/homeant.cfg

Typical workflow:
  ./homeant start               # Windows: .\\homeant start
  re-run the same command after any manual step it asks you for
""",
    )
    # No `required=True`: with the usage line gone, argparse's own complaint
    # for a bare `homeant` would be a single line naming a placeholder nobody
    # can act on. The check below prints the whole screen instead, still rc=2.
    sub = parser.add_subparsers(dest="command")

    def add(name: str, help_text: str, func) -> argparse.ArgumentParser:
        """Register a subcommand on the one help screen.

        `add_help=False` on purpose: five of the six commands take no options at
        all, so their own page would print a usage line and nothing else, and
        the sixth has exactly one switch — which the epilog above already
        describes. One screen is one thing to keep true. `-h` stays accepted so
        the habit still works; it prints this same text, not a per-command page.
        """
        p = sub.add_parser(name, help=help_text, add_help=False)
        # Placed first so the shipped flag check (`add_argument("--…"`) does not
        # read it as a switch of the command: this one belongs to help.
        p.add_argument("-h", "--help", action="store_true",
                       help=argparse.SUPPRESS)
        p.set_defaults(func=func)
        return p

    p_start = add("start", "Bring the install up to date, then start hass",
                  cmd_start)
    # The two switches, one choice per run.  A mutually exclusive group rather
    # than two independent booleans: `--no-upgrade --reinstall` would otherwise
    # have to be resolved by an unwritten precedence rule, and the answer would
    # live in the order of the `if`s below.
    #
    # The pair is named after what happens to the install, not after the
    # network: handing over to the installer *is* an upgrade, so its opposite
    # is `--no-upgrade`, and the user-facing override is `--reinstall`.  There
    # is no positive form of the default — checking the release host is what
    # happens when neither is given, and a third spelling of "yes" would only
    # be one more thing to keep in sync.
    #
    # Both are `store_true` and never values: `--no-upgrade false` would parse
    # as the string "false", which is true in Python, and the switch would
    # silently do nothing.
    #
    #   (none)        check the release host for a newer version and offer it
    #   --no-upgrade  do not upgrade at all: no probe, no hand-over. The
    #                 installer sets this on its own final start, where probing
    #                 would reopen the loop
    #   --reinstall   skip the comparison and hand over unconditionally
    #
    # `--no-upgrade` is hidden from `--help` (SUPPRESS, not removed): its
    # caller is the installer, whose own final `start` is the only run allowed
    # to skip the probe.  A user who met it in the help would have found a
    # switch whose correct use is "never type this" — and typing it by hand
    # silently turns off upgrades.  `--reinstall` is the user-facing half.
    net = p_start.add_mutually_exclusive_group()
    net.add_argument(
        "--no-upgrade", action="store_true", help=argparse.SUPPRESS)
    net.add_argument(
        "--reinstall", action="store_true",
        help="Reinstall the current release now, whether or not this tree is "
             "already the newest")
    # The supervisor contract, not a user-facing mode: the service unit's
    # ExecStart is `start --foreground`.  Named for what it does to this
    # process (stays attached) rather than for its caller, because docker and
    # a terminal are just two more supervisors.  Hidden from `--help` for the
    # same reason as `--no-upgrade`: its caller is a service manager, and a
    # foreground hass in a terminal looks like a hang, not like a mode.
    p_start.add_argument(
        "--foreground", action="store_true", help=argparse.SUPPRESS)
    # The Windows SCM entry point.  Not a user-facing mode either: it is what
    # the service registration's ImagePath runs, and its only job is the
    # StartServiceCtrlDispatcher handshake the SCM insists on — the work stays
    # in `--foreground`, spawned one layer down.  Both switches, never values,
    # for the same reason as the online pair.  Hidden from `--help`: it is the
    # one flag that does nothing useful outside the SCM.
    p_start.add_argument(
        "--service-host", action="store_true", help=argparse.SUPPRESS)

    for name, help_text, func in [
        ("status", "Health check + hass status", cmd_status),
        ("stop", "Stop hass", cmd_stop),
        ("disable", "Turn off start at boot; the running home keeps running "
                    "(start turns it back on)", cmd_disable),
        ("logs", "Stream hass logs", cmd_logs),
    ]:
        add(name, help_text, func)

    # No prompt, no --yes and no --keep-data: typing the verb *is* the decision.
    # The guard rails refuse automatically
    # instead of asking, so a wrong HA_ROOT gets an explanation rather than a
    # yes/no question nobody has the information to answer.  Keeping the data
    # is what `stop` does; a partial uninstall is a state nobody can name.
    add("uninstall", "Remove the service registration and the data directory",
        cmd_uninstall)

    args = parser.parse_args()

    # One screen, wherever help was asked for. Every subcommand accepts `-h`
    # and prints the top-level text (see `add`); the flag is consumed here so
    # it never reaches a `cmd_*` that has no such attribute in mind.
    if getattr(args, "help", False):
        parser.print_help()
        return 0

    # No verb typed. rc=2 keeps it an error for scripts; the text is the full
    # screen because "which commands are there?" is the only useful answer.
    if args.command is None:
        parser.print_help()
        return 2

    # Every command opens with the same two lines the help screen opens with
    # (see `banner`). Printed, not logged: the banner has no severity marker, so
    # log() would only re-add the prefix the second line already carries.
    print(banner(), flush=True)

    # `start` reads homeant.cfg (USERNAME/PASSWORD/XIAOMI_*).  Everything
    # else (stop/status/logs) only touches PID file, HA_ROOT, or subprocess
    # control.
    #
    # `--foreground` and `--service-host` are excluded: both are the supervised
    # child, they read no cfg, and a process the service manager restarts must
    # not be the one writing to the source tree.  The orchestrated `start` has
    # already reconciled it.
    if not getattr(args, "service_host", False):
        # `start` owns the live config: it is what a fresh install runs and what
        # an upgrade ends with, so it creates the file from the template and
        # appends keys a newer version added. Doing it here, before load_cfg(),
        # is the whole point - the run that just gained a key also gets to use it.
        #
        # Every other command reads it, and must: `status` reports the MQTT keys,
        # `logs` logs in with USERNAME/PASSWORD, and `--foreground` starts the
        # broker from those same four keys — a `cf()` left on its defaults would
        # see an empty MQTT password and refuse the broker the installed config
        # already describes (that is the service manager's normal path).
        #
        # Writing stays with the orchestrated `start` alone: a supervised child
        # is restarted by the service manager and must not touch the source
        # tree, and the `start` that installed it has already reconciled the
        # file.  `--service-host` is excluded entirely: it only performs the
        # SCM handshake and the work happens one layer down.
        if args.command == "start" and not getattr(args, "foreground", False):
            _reconcile_cfg()
        CFG = load_cfg()

    rc = args.func(args)

    # If the command finished and hass is running in the background, don't kill
    # it.  The purpose of cmd_start is to launch a detached hass that keeps
    # serving after homeant.py exits.  Only early exits (Ctrl+C,
    # exception, failed start) should trigger cleanup via atexit.
    #
    # Pending counts as finished: the whole point of that state is "come back
    # later", and the thing we would come back to — the flow's webhook,
    # the HA API — lives inside this hass process.  Killing it turns every URL
    # already printed into a 404 and drops the pending flow with it.  That is
    # also why PENDING returns 0: zero means "leave the service alone", the one
    # thing both finished states have in common.
    if rc == 0 and callable(globals().get("_mark_keep_hass")) and SPAWNED_PID:
        _mark_keep_hass()

    return rc


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.stderr.write("\n[cancelled]\n")
        sys.exit(130)
